window.__CHRONICLE_CHUNK["cn-07"] = [
  {id:"cn--1949--p01",track:"cn",year:1949,yearApprox:false,dim:"politics",weight:4,title:"新政协第一届全体会议开幕",summary:"635名代表与会，代行全国人大职权，选出中央人民政府委员会。",detail:{background:"解放战争胜利推进，建立全国政权的条件成熟。1949年6月15日新政协筹备会第一次会议在北平成立筹备机构。",process:"9月21日至30日，中国人民政治协商会议第一届全体会议在北平中南海怀仁堂开幕，出席会议代表635人，设11个界别；会议通过组织法、共同纲领并选举中央人民政府委员会，毛泽东当选主席。",impact:"在普选的全国人大召开前代行其职权，确立中国共产党领导的多党合作与政治协商格局。",figures:["毛泽东","周恩来","李济深","张澜","宋庆龄"],place:"北平（今北京）中南海怀仁堂",state:"中华人民共和国",sources:["《中国人民政治协商会议第一届全体会议文献》（1949年）","《人民日报》1949年9月22日"],"tags":["建国","政治协商","统一战线"]},related:["cn--1949--i01", "cn--1949--p02"]},
  {id:"cn--1949--i01",track:"cn",year:1949,yearApprox:false,dim:"institution",weight:4,title:"《共同纲领》通过",summary:"起临时宪法作用的纲领确立国体、政体与经济政策基本框架。",detail:{background:"各民主党派、团体需就新政权的性质与政策达成一致，草案由筹备会第三小组起草并经全体会议讨论。",process:"9月29日全体会议表决通过《中国人民政治协商会议共同纲领》，共7章60条，规定国体为工人阶级领导的以工农联盟为基础的人民民主国家，经济上实行五种经济成分并存发展。",impact:"1954年宪法颁布前实际起临时宪法作用，其民族区域自治、外交原则等条款成为长期制度起点。",figures:["周恩来","胡愈之","张奚若"],place:"北平中南海怀仁堂",state:"中华人民共和国",sources:["《中国人民政治协商会议共同纲领》（1949年9月29日通过）","《人民日报》1949年9月30日"],"tags":["临时宪法","国体","多党合作"]},related:["cn--1949--p01", "cn--1954--i01"]},
  {id:"cn--1949--p02",track:"cn",year:1949,yearApprox:false,dim:"politics",weight:5,title:"开国大典与中央人民政府成立",summary:"10月1日北京30万人集会，毛泽东宣告中华人民共和国成立。",detail:{background:"政协一届一次会议完成选举与任命，10月1日下午中央人民政府委员会举行第一次会议宣告就职。",process:"10月1日下午3时在天安门广场举行开国大典，参加群众约30万人，毛泽东按下电钮升起第一面五星红旗并宣读中央人民政府公告；受阅部队约1.64万人、飞机17架。",impact:"标志中华人民共和国正式成立，此后10月1日定为国庆日，国家纪年改用公元。",figures:["毛泽东","朱德","周恩来","聂荣臻"],place:"北京天安门广场",state:"中华人民共和国",sources:["中央人民政府公告（1949年10月1日）","《人民日报》1949年10月2日"],"tags":["建国","国庆","阅兵"]},related:["cn--1949--p01", "cn--1949--i01", "cn--1949--p03"]},
  {id:"cn--1949--p03",track:"cn",year:1949,yearApprox:false,dim:"politics",weight:3,title:"定都北京并确定国旗国歌",summary:"政协决议改北平为北京为首都，以五星红旗、《义勇军进行曲》为标志。",detail:{background:"首都选址与国旗、国歌方案由筹备会第六小组公开征集，共收到国旗稿近3000件。",process:"9月27日全体会议通过四项决议：改北平为北京并作为中华人民共和国首都；采用公元纪年；以《义勇军进行曲》为代国歌；以五星红旗为国旗。国旗图案在曾联松设计稿基础上修改确定。",impact:"完成新国家象征体系与纪年制度的确定，中央机关随后由香山迁入北京城内办公。",figures:["毛泽东","周恩来","曾联松","马叙伦"],place:"北平（今北京）",state:"中华人民共和国",sources:["中国人民政治协商会议第一届全体会议主席团公布四项决议（1949年9月27日）"],"tags":["首都","国旗","纪年"]},related:["cn--1949--p02"]},
  {id:"cn--1949--i02",track:"cn",year:1949,yearApprox:false,dim:"institution",weight:3,title:"中央人民政府组织法施行",summary:"设人民革命军事委员会、政务院等，确立建国初期政府组织序列。",detail:{background:"中央政权机构组织需以法律形式确定，草案由新政协筹备会第二小组起草。",process:"9月27日通过《中华人民共和国中央人民政府组织法》，10月1日中央人民政府委员会第一次会议决议执行；设政务院为最高行政机关，下辖4个委员会与30个部，任命周恩来为政务院总理兼外交部长。",impact:"构建中央到大行政区的管理架构，为1954年国务院取代政务院奠定组织基础。",figures:["毛泽东","周恩来","朱德","高岗"],place:"北京中南海",state:"中华人民共和国",sources:["《中华人民共和国中央人民政府组织法》（1949年10月1日施行）"],"tags":["政府组织","政务院","建制"]},related:["cn--1949--i01", "cn--1954--p02"]},
  {id:"cn--1949--m01",track:"cn",year:1949,yearApprox:false,dim:"military",weight:3,title:"第三野战军攻占上海",summary:"5月12日至27日解放上海，城市完整接管并成为财政重心。",detail:{background:"渡江战役后中共中央决定尽量保全上海工业基础，提出入城纪律并预先组织军事接管委员会。",process:"5月12日发起上海战役，5月23日总攻，27日市区战斗结束；第9、第10兵团参战约27万人，解放军伤亡3万余人，6月上旬崇明岛等地肃清。",impact:"上海回归国家财政体系，据《上海统计年鉴》该市1949年工业总产值约占全国工业总量的四分之一以上，成为建国初期税收与工业的主要来源。",figures:["粟裕","张震","饶漱石","陈毅"],place:"上海及吴淞口",state:"中华人民共和国",sources:["《中国人民解放军第三野战军战史》（解放军出版社）","《上海军事志》"],"tags":["解放战争","城市接管","上海"]},related:["cn--1949--e01"]},
  {id:"cn--1949--e01",track:"cn",year:1949,yearApprox:false,dim:"economy",weight:3,title:"上海查封证券大楼取缔银元投机",summary:"6月10日军管会采取行动稳定物价，人民币取得市场本位地位。",detail:{background:"上海解放后银元投机推动6月物价较5月大幅上涨，人民币流通受阻。",process:"6月10日上海市军事管制委员会派部队进入汉口路证券大楼，拘捕主要投机者200余人，收缴银元数万枚；同日公布金银外币管理及使用人民币的布告。",impact:"此后上海物价在下半年回落，陈云把此次行动与1950年3月统一全国财经工作并列为稳定市场的两步关键。",figures:["陈毅","曾山"],place:"上海汉口路证券大楼",state:"中华人民共和国",sources:["《陈云文选》第二卷（1949—1956）","《上海金融志》"],"tags":["金融","物价","人民币"]},related:["cn--1950--e01", "cn--1949--m01"]},
  {id:"cn--1949--m02",track:"cn",year:1949,yearApprox:false,dim:"military",weight:3,title:"新疆和平解放",summary:"9月25、26日陶峙岳、包尔汉通电起义，西北边疆完成交接。",detail:{background:"兰州、西宁解放后，西北军政长官公署与新疆省府内部主和派占上风，中共中央派邓力群赴伊宁转达意图。",process:"9月25日陶峙岳率驻新疆部队约7万人通电起义，26日包尔汉率新疆省政府通电服从毛泽东朱德命令；10月下旬第一野战军第1、第2兵团进驻哈密、迪化、喀什等地，26日彭德怀进入迪化。",impact:"以较小代价完成西北边疆政权交接，为1955年新疆维吾尔自治区成立与边疆建设兵团体制创造条件。",figures:["陶峙岳","包尔汉","彭德怀","王震"],place:"迪化（今乌鲁木齐）",state:"中华人民共和国",sources:["中央人民政府革命军事委员会、政务院关于新疆起义通电的复电（1949年10月23日）","《新疆通志·大事记》"],"tags":["起义","西北边疆","进驻"]},related:["cn--1955--p03"]},
  {id:"cn--1949--p04",track:"cn",year:1949,yearApprox:false,dim:"politics",weight:3,title:"中苏建立外交关系",summary:"10月2日苏联承认新中国并建交，随后多国相继跟进。",detail:{background:"1949年7月刘少奇率团秘密访苏，10月1日苏联、朝鲜先后来照会表示承认。",process:"10月2日中苏互派大使建立外交关系；至1950年1月，保加利亚、罗马尼亚、匈牙利、朝鲜、捷克斯洛伐克、波兰、蒙古、德意志民主共和国、阿尔巴尼亚、苏联先后与新中国建交；1950年1月2日周恩来赴莫斯科参与谈判。",impact:"确立建国初期的外交布局，为1950年2月《中苏友好同盟互助条约》与156项援建工程铺路。",figures:["毛泽东","周恩来","斯大林","罗申"],place:"北京、莫斯科",state:"中华人民共和国",sources:["中华人民共和国外交部《中华人民共和国外交史》第一卷（1949—1956）","新华社1949年10月3日电"],"tags":["外交","中苏","承认"]},related:["cn--1950--p01"]},
  {id:"cn--1949--c01",track:"cn",year:1949,yearApprox:false,dim:"culture",weight:2,title:"第一次中华全国文代会召开",summary:"7月北平会议合并解放区与国统区文艺队伍，成立全国文联。",detail:{background:"中共中央邀请国统区文艺工作者北上，代表来自解放区、国统区与部队三个方面。",process:"7月2日至19日中华全国文学艺术工作者代表大会在北平召开，出席650余人；郭沫若作《为建设新中国的人民文艺而奋斗》总报告，成立中华全国文学艺术界联合会及各专业协会。",impact:"形成此后三十余年文艺体制的骨干结构，文艺为工农兵服务的方向被确立为工作方针。",figures:["郭沫若","茅盾","周扬","巴金"],place:"北平（今北京）",state:"中华人民共和国",sources:["《中华全国文学艺术工作者代表大会纪念文集》（1949年8月）"],"tags":["文艺体制","文联","会议"]},related:["cn--1956--c01"]},
  {id:"cn--1950--p01",track:"cn",year:1950,yearApprox:false,dim:"politics",weight:5,title:"《中苏友好同盟互助条约》签订",summary:"2月14日莫斯科签约，同盟期三十年并配套贷款与协定。",detail:{background:"毛泽东1949年12月16日抵达莫斯科，谈判围绕旧约权益、中国长春铁路、旅顺口及新疆合营公司等问题持续约两个月。",process:"1950年2月14日周恩来与苏联外长维辛斯基在克里姆林宫签署条约，有效期三十年；同日签订关于中国长春铁路、旅顺口及大连的协定与苏联贷款协定（贷款3亿美元、年利1%）。",impact:"确立五十年代中方安全与工业化的外部依托。该条约有效期三十年，1980年2月期满前，中方于1979年宣布期满后不再延长。",figures:["毛泽东","周恩来","斯大林","维辛斯基"],place:"莫斯科克里姆林宫",state:"中华人民共和国",sources:["《中苏友好同盟互助条约》（1950年2月14日签订）","《周恩来年谱（1949—1976）》上卷"],"tags":["同盟条约","外交","贷款"]},related:["cn--1949--p04", "cn--1953--e01"]},
  {id:"cn--1950--i01",track:"cn",year:1950,yearApprox:false,dim:"institution",weight:4,title:"《婚姻法》公布施行",summary:"4月30日公布，废除包办强迫婚姻，确立一夫一妻、男女平等。",detail:{background:"婚姻制度变革被中央视为瓦解宗法制度的抓手，草案由中央法制委员会与全国妇联共同起草。",process:"1950年4月13日中央人民政府委员会第七次会议通过《中华人民共和国婚姻法》，30日公布施行，共8章27条；1951年至1952年在全国城乡开展贯彻婚姻法运动，1953年3月进入高潮。",impact:"这是新中国制定的第一部法律。据1953年中央贯彻婚姻法运动委员会的总结通报，运动在多数新区乡级以上单位展开，结婚登记与解除婚约、离婚案件由基层政权统一受理。",figures:["邓颖超","谢觉哉","王昆仑"],place:"北京；全国城乡",state:"中华人民共和国",sources:["《中华人民共和国婚姻法》（1950年4月30日公布）","《建国以来刘少奇文稿》第二册"],"tags":["婚姻","妇女","首部法律"]},related:["cn--1950--i02"]},
  {id:"cn--1950--i02",track:"cn",year:1950,yearApprox:false,dim:"institution",weight:5,title:"《土地改革法》公布与新土改启动",summary:"6月28日通过并保存富农经济，土改在占全国人口多数地区展开。",detail:{background:"1947年《中国土地法大纲》适用于战争环境，中央为稳定城市与民族资产阶级改变政策口径。",process:"6月28日中央人民政府委员会第八次会议通过《中华人民共和国土地改革法》，30日公布施行；规定没收地主土地、耕畜、农具与多余粮食，同时保存富农经济；到1952年底，除部分少数民族地区外约3亿无地少地农民获得约7亿亩土地。",impact:"终结了地主土地所有制，确立个体农民土地所有制，同时为国家统购统销与农业合作化提供了基层动员结构。",figures:["毛泽东","刘少奇","薄一波"],place:"全国新解放区",state:"中华人民共和国",sources:["《中华人民共和国土地改革法》（1950年6月30日公布）","《建国以来重要文献选编》第1册"],"tags":["土地改革","富农政策","农业"]},related:["cn--1953--p01", "cn--1955--p04"]},
  {id:"cn--1950--m01",track:"cn",year:1950,yearApprox:false,dim:"military",weight:4,title:"志愿军入朝与抗美援朝开始",summary:"10月8日组成志愿军，19日夜渡江，25日首战打响。",detail:{background:"1950年6月25日朝鲜战争爆发，9月15日美军在仁川登陆，10月上旬越过三八线北推并轰炸鸭绿江两岸。",process:"10月8日中央决定组成中国人民志愿军，彭德怀任司令员兼政治委员；10月19日夜第38、39、40、42军等分三路渡江入朝；25日第40军在温井两水洞与南朝鲜军接触，第一次战役开始。",impact:"中国自此进入以抗美援朝为中心的战时财政与社会动员体制，直接推动军工、铁路与粮食调运扩张。",figures:["毛泽东","彭德怀","邓华","洪学智"],place:"安东（今丹东）至朝鲜温井地区",state:"中华人民共和国",sources:["《抗美援朝战争史》第一卷（军事科学出版社）","新华社1950年10月19日电"],"tags":["抗美援朝","渡江","首战"]},related:["cn--1950--m02", "cn--1953--m02", "world--1950--m01"]},
  {id:"cn--1950--m02",track:"cn",year:1950,yearApprox:false,dim:"military",weight:3,title:"第二次战役与收复平壤",summary:"11月25日起志愿军反击，将战线推回三八线附近。",detail:{background:"第一次战役后“联合国军”发动圣诞节前结束的总攻势，东西两线兵力突出。",process:"11月25日至12月24日第二次战役，西线第38军穿插三所里、龙源里切断退路，东线第9兵团在长津地区作战；12月6日收复平壤，24日“联合国军”与永兴岛守军自兴南港海上撤离，战线退至三八线附近。",impact:"据《抗美援朝战争史》记载，第二次战役共歼敌3.6万余人，迫使美方重新评估战争目标并于12月推动停火动议。",figures:["彭德怀","韩先楚","宋时轮","李奇微"],place:"朝鲜熙川、三所里、长津湖",state:"中华人民共和国",sources:["《抗美援朝战争史》第一卷（军事科学出版社，2000年版）"],"tags":["战役","长津湖","平壤"]},related:["cn--1950--m01", "cn--1951--m01"]},
  {id:"cn--1950--m03",track:"cn",year:1950,yearApprox:false,dim:"military",weight:3,title:"昌都战役",summary:"10月6日至24日进藏先头部队控制昌都，打开和谈通道。",detail:{background:"西藏地方当局拒绝中央代表赴拉萨谈判，在昌都方向集中藏军主力设防。",process:"10月6日第18军等部发起强渡金沙江作战，19日围困昌都，24日藏军第九代本丁典·格桑益西率部2700余人停止抵抗，共歼藏军5700余人；12月19日拉萨局势变化，西藏地方政府同意派代表谈判。",impact:"军事行动直接促成1951年5月《关于和平解放西藏办法的协议》的谈判与签署。",figures:["张国华","谭冠三","阿沛·阿旺晋美"],place:"西康昌都（今属西藏）",state:"中华人民共和国",sources:["《西藏和平解放与繁荣发展》白皮书（国务院新闻办公室，2021年）","《西藏通史》当代卷"],"tags":["昌都","进藏","谈判"]},related:["cn--1951--p01"]},
  {id:"cn--1950--p02",track:"cn",year:1950,yearApprox:false,dim:"politics",weight:3,title:"镇压反革命运动展开",summary:"3月与10月两次中央指示，重点打击土匪、特务与恶霸。",detail:{background:"建国初期各地潜伏武装、帮会及特务组织活动频繁，1950年上半年广西、湖南等地发生多起袭击事件。",process:"3月中共中央发出《关于镇压反革命活动的指示》，10月10日再次发出指示纠正“宽大无边”偏向；1951年2月21日公布《中华人民共和国惩治反革命条例》作为法律依据。据《中国共产党的九十年》记载，运动到1951年10月基本结束。",impact:"完成对旧帮会、一贯道等组织的取缔并重建基层治安体系；运动中出现过扩大化偏差，1951年中央多次指示纠正。",figures:["毛泽东","刘少奇","罗瑞卿","彭真"],place:"全国新老解放区",state:"中华人民共和国",sources:["《关于镇压反革命活动的指示》（1950年3月、10月10日）","《中华人民共和国惩治反革命条例》（1951年2月21日公布）"],"tags":["镇反","治安","刑事"]},related:["cn--1950--m01"]},
  {id:"cn--1950--p03",track:"cn",year:1950,yearApprox:false,dim:"politics",weight:3,title:"中共七届三中全会",summary:"6月会议要求争取财政经济状况基本好转，部署土改与调整工商业。",detail:{background:"建国未满一年即面临物价、失业与军费三重压力，毛泽东提出不要“四面出击”。",process:"6月6日至9日在北京召开七届三中全会，毛泽东作《为争取国家财政经济状况的基本好转而斗争》书面报告，刘少奇作关于土地改革的报告，全会部署土改、调整工商业、节减军队三项任务。",impact:"全会确定的“三年准备、十年计划经济建设”节奏，成为1953年开始第一个五年计划的时间基础。",figures:["毛泽东","刘少奇","周恩来","陈云","薄一波"],place:"北京中南海",state:"中华人民共和国",sources:["《毛泽东文集》第六卷","《建国以来重要文献选编》第1册"],"tags":["全会","经济调整","部署"]},related:["cn--1950--e01", "cn--1953--p01"]},
  {id:"cn--1950--e01",track:"cn",year:1950,yearApprox:false,dim:"economy",weight:4,title:"统一全国财政经济工作",summary:"3月政务院决定统一收支、物资与现金管理，结束长期通胀。",detail:{background:"解放初期各大行政区财政分散，1949年四次物价风潮使全国批发物价总水平大幅上涨。",process:"1950年3月3日政务院公布《关于统一国家财政经济工作的决定》，统一全国财政收入、物资调度与现金管理；4月起物价回落，当年财政赤字由年初预计的占支出总额约三分之二降至年末基本平衡。",impact:"据陈云在中央工作会议上的总结，统一财经是与军事胜利同等重要的一步，为1953年转入计划建设提供了价格与财政前提。",figures:["陈云","周恩来","薄一波"],place:"北京；全国各大行政区",state:"中华人民共和国",sources:["《关于统一国家财政经济工作的决定》（1950年3月3日）","《陈云文选》第二卷"],"tags":["财政统一","通胀","物价"]},related:["cn--1949--e01", "cn--1950--p03"]},
  {id:"cn--1950--p04",track:"cn",year:1950,yearApprox:false,dim:"politics",weight:2,title:"海南岛战役与舟山守军撤退",summary:"4月木帆船渡海解放海南，5月舟山群岛无战斗交接。",detail:{background:"国民党军退守台湾、海南与舟山，构成对华南沿海港口的封锁威胁。",process:"4月16日第15兵团以木帆船为主强渡琼州海峡，在琼崖纵队接应下23日占领海口，5月1日全岛解放；5月16日至19日舟山守军撤往台湾。",impact:"缓解了广州、上海方向的海上封锁压力，同时暴露渡海装备短板，直接影响此后海防与空军建设投入。",figures:["韩先楚","邓华","薛岳"],place:"海南岛、舟山群岛",state:"中华人民共和国",sources:["《中国人民解放军第四野战军战史》（解放军出版社）"],"tags":["渡海","解放","华南"]},related:["cn--1949--m01"]},
  {id:"cn--1951--p01",track:"cn",year:1951,yearApprox:false,dim:"politics",weight:4,title:"《关于和平解放西藏办法的协议》签订",summary:"5月23日17条协议签署，人民解放军随后进驻西藏。",detail:{background:"1950年10月昌都战役后，西藏地方政府派出以阿沛·阿旺晋美为首席代表的代表团赴京谈判。",process:"5月23日中央人民政府与西藏地方政府在北京签订《关于和平解放西藏办法的协议》，共17条，规定西藏回归祖国、驱逐帝国主义势力、实行民族区域自治与维持西藏现有政治制度；10月26日进藏部队抵达拉萨。",impact:"实现大陆全境军事与政治统一，西藏在保留原有政教体制的同时设立驻藏机构，为1959年后自治区建制铺路。",figures:["毛泽东","阿沛·阿旺晋美","扎喜·才旦多仁","张国华"],place:"北京；拉萨",state:"中华人民共和国",sources:["《关于和平解放西藏办法的协议》（1951年5月23日）","《西藏和平解放与繁荣发展》白皮书（2021年）"],"tags":["西藏","协议","进驻"]},related:["cn--1950--m03", "cn--1959--m01"]},
  {id:"cn--1951--p02",track:"cn",year:1951,yearApprox:false,dim:"politics",weight:4,title:"三反运动发动",summary:"12月1日中央决定在党和国家机关内反对贪污、浪费与官僚主义。",detail:{background:"1951年10月中央作出精兵简政、增产节约决定后，发现部分干部在采购、加工订货中被私商腐蚀。",process:"1951年12月1日中共中央作出《关于实行精兵简政、增产节约、反对贪污、反对浪费和反对官僚主义的决定》；1952年1月26日中央指示在私营工商业者中开展反行贿、反偷税漏税、反盗骗国家财产、反偷工减料、反盗窃经济情报的五反运动，三反与五反互为表里推进。",impact:"据中央人民政府节约检查委员会1952年10月25日的公报，三反与五反运动在全国范围基本结束；运动此后确立了国家机关内部的纪律检查常规，同时重塑了国家对城市工商业的管理边界与公私关系。",figures:["毛泽东","刘少奇","薄一波","彭真"],place:"北京；全国城市",state:"中华人民共和国",sources:["《中共中央关于实行精兵简政增产节约、反对贪污浪费官僚主义的决定》（1951年12月1日）","《建国以来重要文献选编》第3册"],"tags":["三反","五反","干部纪律"]},related:["cn--1951--f01", "cn--1952--p01"]},
  {id:"cn--1951--f01",track:"cn",year:1951,yearApprox:false,dim:"figure",weight:3,title:"刘青山、张子善案判决",summary:"12月4日河北人民法院公审，两名地委书记因贪污被判死刑。",detail:{background:"二人均为1930年代入党的地专级干部，在天津专区动用民工款、专区款并经营机关生产获利。",process:"1951年12月4日河北省人民法院在保定公审，以贪污总额184亿元（旧币）判处刘青山、张子善死刑，1952年2月10日执行；判决前经毛泽东、周恩来等审议。",impact:"该案被作为三反运动的标志性案件长期引用，对建国初期干部经济纪律形成强烈信号，也为此后贪污罪的量刑口径提供了先例。",figures:["毛泽东","刘青山","张子善","董必武"],place:"保定（河北省人民法院）",state:"中华人民共和国",sources:["《人民日报》1951年12月5日、1952年2月11日","薄一波《若干重大决策与事件的回顾》"],"tags":["典型案件","人物","廉政"]},related:["cn--1951--p02"]},
  {id:"cn--1951--m01",track:"cn",year:1951,yearApprox:false,dim:"military",weight:3,title:"志愿军第四次与第五次战役",summary:"1月至6月连续攻势，战线最终稳定在三八线附近。",detail:{background:"“联合国军”以李奇微替代麦克阿瑟后采用磁性战术，志愿军携行补给通常只能维持一周。",process:"1月25日至4月21日第四次战役在横城、砥平里方向阻击；4月22日至6月10日第五次战役推进至汉城以南、昭阳江地区，此后双方转入三八线附近相持与筑垒对峙。",impact:"战役结束后战争形态转为阵地对峙，中方提出“零敲牛皮糖”的战术，停战谈判的军事议题趋于僵持。",figures:["彭德怀","李奇微","邓华","陈赓"],place:"朝鲜汉江、铁原、金化地区",state:"中华人民共和国",sources:["《抗美援朝战争史》第二卷（军事科学出版社）"],"tags":["战役","相持","阵地战"]},related:["cn--1951--m02", "cn--1950--m02"]},
  {id:"cn--1951--m02",track:"cn",year:1951,yearApprox:false,dim:"military",weight:3,title:"朝鲜停战谈判开始",summary:"7月10日开城谈判，议题包括军事分界线与战俘安排。",detail:{background:"1951年5月17日中朝方面商定谈判方针，6月23日苏联代表马立克在联合国提出停火建议。",process:"7月10日朝鲜人民军、中国人民志愿军代表团与“联合国军”代表团在开城来凤庄开始谈判，8月起围绕军事分界线僵持，10月25日会址迁至板门店；战俘遣返问题使谈判拖延至1953年。",impact:"形成“边打边谈”的战争形态，谈判期间发生上甘岭战役等高强度作战。",figures:["李克农","邓华","乔冠华","南日","哈里逊"],place:"朝鲜开城、板门店",state:"中华人民共和国",sources:["《朝鲜停战谈判》（世界知识出版社）","《抗美援朝战争史》第二卷"],"tags":["谈判","停战","板门店"]},related:["cn--1952--m01", "cn--1953--m02", "world--1953--p02"]},
  {id:"cn--1951--s01",track:"cn",year:1951,yearApprox:false,dim:"science",weight:3,title:"治淮委员会成立与治淮工程展开",summary:"5月在蚌埠成立治淮委，确立蓄泄兼筹的流域治理方针。",detail:{background:"1950年夏淮河流域特大洪水，皖北受灾人口约1300万，毛泽东为治淮会议题词“一定要把淮河修好”。",process:"1950年11月治淮委员会筹备，1951年5月在蚌埠正式成立并全面开工；到1952年建成官厅水库、佛子岭连拱坝等控制性工程，完成淮沭新河、苏北灌溉总渠等骨干河道。",impact:"这是新中国第一个全流域综合治水工程，形成此后流域治理“专门委员会加群众突击施工”的工作模式。",figures:["毛泽东","邵力子","张恺帆"],place:"安徽蚌埠、洪泽湖流域",state:"中华人民共和国",sources:["《当代中国的水利事业》（当代中国出版社）","《治淮》期刊1951年创刊号"],"tags":["水利","流域治理","淮河"]},related:["cn--1954--d01"]},
  {id:"cn--1952--m01",track:"cn",year:1952,yearApprox:false,dim:"military",weight:3,title:"上甘岭战役",summary:"10月14日至11月25日争夺两处高地，坑道坚守成为战例。",detail:{background:"1952年10月“联合国军”发起金化攻势，目标为597.9高地与541高地北侧（上甘岭地区）。",process:"第15军以坑道依托坚守，据志愿军司令部的战役总结，敌向约3.7平方公里阵地倾泻炮弹190余万发、炸弹7000余枚；10月20日、10月30日两次反击争夺，11月25日战斗结束，第12军接替防守。",impact:"坑道防御体系成为此后国防工事与阵地作战的模板，中朝方面在谈判桌上因此获得有利地位。",figures:["秦基伟","崔建功","李德生"],place:"朝鲜金化以北上甘岭",state:"中华人民共和国",sources:["《抗美援朝战争史》第二卷（军事科学出版社）","中国人民志愿军第15军上甘岭战役总结（1952年）"],"tags":["战役","坑道","坚守"]},related:["cn--1952--f01", "cn--1951--m02"]},
  {id:"cn--1952--f01",track:"cn",year:1952,yearApprox:false,dim:"figure",weight:3,title:"黄继光牺牲与授特级英雄",summary:"上甘岭反击中以身体压住敌火力点，年21岁。",detail:{background:"1951年入朝的第135团通信员黄继光在上甘岭597.9高地反击战中参加爆破组。",process:"10月20日凌晨在冲锋受阻时扑向敌射孔，牺牲，年21岁；1953年4月8日中国人民志愿军领导机关为其记特等功、授特级英雄称号，1953年6月朝鲜民主主义人民共和国授予金星奖章与共和国英雄称号。",impact:"与邱少云并列为抗美援朝宣传中传播最广的英雄叙事，其事迹长期进入中小学课本与部队教材。",figures:["黄继光","万福来","冯玉瓒"],place:"朝鲜金化上甘岭597.9高地",state:"中华人民共和国",sources:["中国人民志愿军政治部关于黄继光同志记功授称的决定（1953年4月）","《人民日报》1953年4月11日"],"tags":["英雄叙事","人物","上甘岭"]},related:["cn--1952--m01", "cn--1963--f01"]},
  {id:"cn--1952--f02",track:"cn",year:1952,yearApprox:false,dim:"figure",weight:2,title:"罗盛教救人事迹",summary:"1月在朝鲜平安南道三度入冰河救溺水儿童，牺牲时21岁。",detail:{background:"志愿军入朝后开展群众纪律与爱民教育，文书罗盛教所在的部队在成川郡一带驻训。",process:"1月2日罗盛教在朝鲜平安南道成川郡石田里遇到朝鲜少年崔莹冰面塌落坠水，三次潜入冰窟托举救人，因体力耗尽牺牲；1952年9月志愿军领导机关为其记一等功，授一级国旗勋章与模范青年团员称号。",impact:"成为抗美援朝期间中朝民间叙事中引用最广的救人典型之一，与黄继光同期进入宣传与教材体系。",figures:["罗盛教","崔莹"],place:"朝鲜平安南道成川郡石田里",state:"中华人民共和国",sources:["中国人民志愿军政治部关于罗盛教同志事迹的通报（1952年）","《人民日报》1952年9月"],"tags":["人物","典型","爱民"]},related:["cn--1952--f01"]},
  {id:"cn--1952--i01",track:"cn",year:1952,yearApprox:false,dim:"institution",weight:4,title:"全国高等院校院系调整",summary:"7月至9月按苏联模式重组，工科与专门学院大幅扩张。",detail:{background:"1951年12月政务院通过关于1952年高等学校调整设置的方案，为工业化培养专门技术人才。",process:"1952年7月至9月以华北、华东、东北为重点展开，全国原有高等学校由1951年的211所经合并、拆分与改组后调整为181所（不同统计口径为181—183所），其中专门学院占比大幅上升、综合性大学数目明显缩减；清华大学、浙江大学、山东大学的工科整体调出，北京形成“八大学院”格局。",impact:"确立了专门学院与工科优先的高等教育格局，也改变了综合性大学的学科结构，是1952年后科研与人才培养体制的组织基础。",figures:["马寅初","潘梓年","教育部"],place:"北京、天津、南京、上海、杭州",state:"中华人民共和国",sources:["《关于全国高等学校1952年调整设置的方案》（1951年12月）","《中华人民共和国教育大事记（1949—1982）》"],"tags":["教育改革","苏联模式","工科"]},related:["cn--1949--c01", "cn--1977--i01"]},
  {id:"cn--1952--i02",track:"cn",year:1952,yearApprox:false,dim:"institution",weight:3,title:"民族区域自治实施纲要公布",summary:"8月8日公布，将自治区、自治州、自治县建制规范化。",detail:{background:"《共同纲领》已确立民族区域自治原则，内蒙古自治区的先例与新区推行需要具体条例。",process:"1952年8月8日中央人民政府委员会第18次会议批准《中华人民共和国民族区域自治实施纲要》公布施行，共7章40条，规定自治机关组成、干部培养与自治权利。",impact:"以法规形式确认自治机关民族干部配备比例，构成此后民族区域自治制度的操作依据，1955至1965年四个省级自治区相继成立。",figures:["李维汉","乌兰夫","刘格平"],place:"北京；各少数民族聚居区",state:"中华人民共和国",sources:["《中华人民共和国民族区域自治实施纲要》（1952年8月8日批准）","《中华人民共和国民族区域自治法》（1984年）"],"tags":["民族区域自治","法规","建制"]},related:["cn--1955--p03", "cn--1965--p02"]},
  {id:"cn--1952--s01",track:"cn",year:1952,yearApprox:false,dim:"science",weight:3,title:"成渝铁路建成通车",summary:"7月1日全线通车，为新中国第一条完全自主修建的铁路。",detail:{background:"线路始于清末筹议，1937年起两次开工均未完；施工由西南军区承担，采用筑路部队与失业工人结合的劳动方式。",process:"1950年6月15日开工，1952年7月1日成都、重庆同时举行通车典礼，正线长505公里；全线使用钢轨5.6万余吨、道岔4000余组，均由沈阳、鞍山等厂供应，民工与部队累计投入约30万工日。",impact:"打通四川盆地南向通道，带动内江、自贡沿线糖、盐工业恢复，成为建国初期“自力更生修路”的代表性工程。",figures:["邓小平","贺龙","陈锡联"],place:"四川成都至重庆",state:"中华人民共和国",sources:["《四川铁路志》","《人民日报》1952年7月2日"],"tags":["铁路","工程","西南"]},related:["cn--1952--e01", "cn--1970--s02"]},
  {id:"cn--1952--e01",track:"cn",year:1952,yearApprox:false,dim:"economy",weight:3,title:"国民经济恢复时期结束",summary:"1952年工农业总产值827亿元，比1949年增长约77.5%。",detail:{background:"1949至1952年为经济恢复阶段，中央目标是使主要产品产量达到或超过历史最高水平。",process:"据国家统计局数据，1952年全国工农业总产值827亿元，比1949年增长77.5%；工业总产值349亿元，比1949年增长约145%；粮食产量1.639亿吨，比1949年增长约42.8%；钢135万吨，超过1943年历史最高水平。",impact:"恢复期完成使中央判断可以转入大规模计划建设，1953年起进入第一个五年计划并同步启动统购统销。",figures:["周恩来","陈云","贾拓夫"],place:"全国",state:"中华人民共和国",sources:["国家统计局《中国统计年鉴（1981）》","国家统计局《国民经济发展统计公报（1952年）》"],"tags":["经济恢复","统计","工业产值"]},related:["cn--1953--e01", "cn--1953--i02"]},
  {id:"cn--1952--p01",track:"cn",year:1952,yearApprox:false,dim:"politics",weight:3,title:"五反运动定案与工商业格局变化",summary:"1952年上半年定案，私营工业在国家加工订货中的占比上升。",detail:{background:"1952年1月起在各大城市开展反对行贿、偷税漏税、盗骗国家财产、偷工减料、盗窃经济情报的斗争。",process:"到1952年上半年陆续定案，私营工商户被划分为守法户、基本守法户、半守法半违法户、严重违法户、完全违法户五类；运动后国家对私营工业实行加工订货、统购包销的覆盖面显著扩大。",impact:"据《剑桥中国史》第15卷引用的统计，私营工业在全国工业总产值中比重由1951年约37%降至1953年约24%，为1956年全行业公私合营创造了条件。",figures:["毛泽东","刘少奇","陈云","李维汉"],place:"北京、上海、天津、武汉、广州",state:"中华人民共和国",sources:["《建国以来重要文献选编》第3册","《剑桥中国史》第15卷（中华人民共和国下部，1949—1965）"],"tags":["五反","私营工商业","改造"]},related:["cn--1951--p02", "cn--1955--e02"]},
  {id:"cn--1952--p02",track:"cn",year:1952,yearApprox:false,dim:"politics",weight:3,title:"亚洲及太平洋区域和平会议在北京召开",summary:"10月2日开幕，37国367位代表与会，为首次在京大型国际会议。",detail:{background:"会议倡议源于1952年10月在北京召开的亚洲及太平洋区域和平会议筹备会议与国际和平组织推动。",process:"10月2日至13日在北京召开，来自37个国家的367位代表出席，宋庆龄任执行主席之一并致开幕词；会议通过《我们人民之间的合作与友谊》等文件，成立常设联络委员会。",impact:"为新中国提供了绕过建交承认问题直接开展民间外交的平台，会后中方与多国工会、妇联、科技团体建立常态联系。",figures:["宋庆龄","郭沫若","刘宁一","约里奥—居里"],place:"北京",state:"中华人民共和国",sources:["《宋庆龄年谱（1893—1981）》","《人民日报》1952年10月14日"],"tags":["民间外交","和平会议","北京"]},related:["cn--1955--p05"]},
  {id:"cn--1952--i03",track:"cn",year:1952,yearApprox:false,dim:"institution",weight:2,title:"机关和部队开始实行工资制改革准备",summary:"1952年军队与机关供给制向等级制过渡，为1956年工资改革铺垫。",detail:{background:"建国初期沿用供给制，随着干部规模扩大与工业化需要，中央要求统一等级与报酬制度。",process:"1952年3月总干部管理部与政务院内务部拟定职务与等级对应关系，军队实行部队长以下官兵的供给等级标准，1955年9月国务院发布《关于军队实行薪金制的指示》。",impact:"形成以职务等级为核心的分配框架，1956年全国工资改革即以此为基础建立24级工资标准。",figures:["聂荣臻","罗荣桓","李聚奎"],place:"北京；全国机关部队",state:"中华人民共和国",sources:["《国务院关于军队实行薪金制的指示》（1955年9月）","《当代中国的劳动工资》"],"tags":["工资制","供给制","制度"]},related:["cn--1955--p01", "cn--1956--i02"]},
  {id:"cn--1953--p01",track:"cn",year:1953,yearApprox:false,dim:"politics",weight:5,title:"过渡时期总路线正式提出",summary:"确立社会主义工业化与对农业、手工业、资本主义工商业的改造。",detail:{background:"1952年底中央认为恢复期已过；1953年6月15日毛泽东在政治局会议讲话中批评“确立新民主主义社会秩序”的提法。",process:"1953年12月中共中央批准并转发中央宣传部《为动员一切力量把我国建设成为一个伟大的社会主义国家而斗争——关于党在过渡时期总路线的学习和宣传提纲》，完整表述总路线，规定过渡期约需三个五年计划。",impact:"总路线结束了新民主主义阶段的政策设想，直接推动统购统销、宪法制订与1956年社会主义改造高潮。",figures:["毛泽东","刘少奇","周恩来","李维汉"],place:"北京",state:"中华人民共和国",sources:["《为动员一切力量把我国建设成为一个伟大的社会主义国家而斗争》（1953年12月）","《毛泽东文集》第六卷"],"tags":["总路线","工业化","改造"]},related:["cn--1953--i02", "cn--1956--e01", "cn--1958--p01"]},
  {id:"cn--1953--e01",track:"cn",year:1953,yearApprox:false,dim:"economy",weight:4,title:"第一个五年计划开始执行",summary:"集中力量建设156项工程，1953年起转入计划建设阶段。",detail:{background:"“一五”自1951年起编制、五易其稿，1955年7月一届全国人大二次会议正式批准，但1953年已按纲要执行。",process:"计划安排施工限额以上建设单位694个，其中苏联援建的156项实际施工150项；1953年12月鞍钢大型轧钢厂、无缝钢管厂、七号高炉三大工程竣工投产，武汉、包头两大钢铁基地同年进入选址与设计准备。",impact:"奠定重工业骨架。据国家统计局，1953至1957年工业总产值年均增长18.4%，但农业与轻工业投入比例偏低，成为1956年反冒进与后续调整的议题。",figures:["周恩来","陈云","李富春","贾拓夫"],place:"鞍山、长春、武汉、西安、兰州",state:"中华人民共和国",sources:["《中华人民共和国发展国民经济的第一个五年计划（1953—1957）》","国家统计局《中国统计年鉴（1983）》"],"tags":["一五计划","156项","重工业"]},related:["cn--1952--e01", "cn--1957--e01", "cn--1953--p01"]},
  {id:"cn--1953--i01",track:"cn",year:1953,yearApprox:false,dim:"institution",weight:3,title:"全国首次基层普选与选举法施行",summary:"2月公布选举法，1953下半年至1954年完成基层选举与人口登记。",detail:{background:"《共同纲领》规定召开普选的人民代表大会，1952年12月中央人民政府委员会作出相应决定。",process:"1953年2月11日中央人民政府委员会第二十二次会议通过《全国人民代表大会及地方各级人民代表大会选举法》；同时开展全国人口调查登记，以1953年6月30日24时为登记标准时间；基层选举共选出基层人大代表约156万人。",impact:"完成中国历史上第一次全国性基层选举与首次现代人口普查（总人口6.02亿），为1954年第一届全国人大召开提供组织前提。",figures:["邓小平","乌兰夫","彭真"],place:"全国（普查标准时点1953年6月30日）",state:"中华人民共和国",sources:["《中华人民共和国全国人民代表大会及地方各级人民代表大会选举法》（1953年2月11日通过）","国家统计局《第一次人口普查公报》"],"tags":["普选","选举法","人口普查"]},related:["cn--1954--p01", "cn--1953--i02"]},
  {id:"cn--1953--i02",track:"cn",year:1953,yearApprox:false,dim:"institution",weight:4,title:"粮食统购统销政策实施",summary:"10月决定在农村计划收购、在城市计划供应粮食。",detail:{background:"1952年下半年起部分城市出现粮荒，1953年粮食收购进度落后、销量激增，大城市库存下降。",process:"1953年10月16日中共中央作出《关于实行粮食的计划收购与计划供应的决议》，11月15日又对油料、棉花实行同类办法；1955年8月国务院发布市镇粮食定量供应与农村统购统销暂行办法。",impact:"国家取得农产品流通的主导权，取消粮食自由市场，通过工农产品比价为工业化积累资金；城乡分割的粮食供给体制自此成型。",figures:["毛泽东","陈云","邓小平","曾山"],place:"全国（决策在北京）",state:"中华人民共和国",sources:["《关于实行粮食的计划收购与计划供应的决议》（1953年10月16日）","《陈云文选》第二卷"],"tags":["统购统销","粮食","城乡二元"]},related:["cn--1955--e01", "cn--1985--e01"]},
  {id:"cn--1953--m02",track:"cn",year:1953,yearApprox:false,dim:"military",weight:4,title:"朝鲜停战协定签署",summary:"7月27日板门店签字，志愿军与“联合国军”双方停止军事行动。",detail:{background:"1953年5月战俘遣返协议接近达成，6月8日李承晚方面强行“就地释放”朝鲜人民军战俘，中方决定以军事压力配合谈判。",process:"7月10日至27日金城战役歼敌5.3万余人（据《抗美援朝战争史》），27日上午克拉克、金雄、彭德怀三方代表在板门店签署《朝鲜军事停战协定》，27日22时起双方停止一切军事行动。",impact:"抗美援朝战争结束。据中方统计，志愿军两年零九个月作战共歼敌109万余人，自身战斗减员36.6万余人；此后东北与华北长期保持战备态势。",figures:["彭德怀","克拉克","金雄","南日"],place:"朝鲜板门店",state:"中华人民共和国",sources:["《朝鲜军事停战协定》（1953年7月27日）","《抗美援朝战争史》第三卷（军事科学出版社）"],"tags":["停战","板门店","抗美援朝"]},related:["cn--1951--m02", "cn--1952--m01", "world--1953--p02"]},
  {id:"cn--1953--p02",track:"cn",year:1953,yearApprox:false,dim:"politics",weight:3,title:"日内瓦会议筹备与印度支那问题",summary:"中方决定出席四大国会议，为1954年解决印度支那冲突铺路。",detail:{background:"1953年9月苏联在联大提出召开五大国会议讨论远东问题，中、朝、越三方经协商同意参加。",process:"1953年12月至1954年1月，周恩来与金日成、彭德怀及越南劳动党反复磋商，中央确定争取和平、反对美国扩大战争的方针；1954年2月柏林四国外长会议达成协议，由日内瓦会议讨论朝鲜与印度支那问题。",impact:"这是新中国首次以大国身份参与多边国际会议的准备，为此后中日、中美直接接触提供了外交经验。",figures:["周恩来","莫洛托夫","范文同","金日成"],place:"北京、莫斯科、河内",state:"中华人民共和国",sources:["《周恩来年谱（1949—1976）》上卷","《中华人民共和国外交史》第一卷"],"tags":["日内瓦","多边外交","筹备"]},related:["cn--1954--p04", "cn--1965--m01", "world--1954--p01"]},
  {id:"cn--1953--p03",track:"cn",year:1953,yearApprox:false,dim:"politics",weight:3,title:"高岗、饶漱石事件处理",summary:"12月中央政治局会议提出防范问题，1955年3月决议开除党籍。",detail:{background:"1953年夏全国财经会议、秋季组织工作会议期间，高岗在中央与会者中活动，攻击刘少奇、周恩来。",process:"1953年12月下旬毛泽东主持中央政治局会议，提出解决高岗问题；1954年2月七届四中全会通过《关于增强党的团结的决议》；1955年3月中国共产党全国代表会议通过《关于高岗、饶漱石反党联盟的决议》，开除高岗、饶漱石党籍。",impact:"此案确立了此后党内“反党集团”类问题的处理范式，并直接推动集体领导与总书记制度的调整（1954年设中央秘书长）。",figures:["毛泽东","高岗","饶漱石","刘少奇","邓小平"],place:"北京、杭州",state:"中华人民共和国",sources:["《中国共产党全国代表会议关于高岗饶漱石反党联盟的决议》（1955年3月）","《建国以来重要文献选编》第6册"],"tags":["高饶","党内斗争","纪律"]},related:["cn--1955--p02"]},
  {id:"cn--1953--c01",track:"cn",year:1953,yearApprox:false,dim:"culture",weight:2,title:"中国佛教协会成立",summary:"6月3日在北京广济寺成立，处理佛教事务并对接对外交流。",detail:{background:"中央拟以全国性宗教团体统一管理佛教事务，并配合对斯里兰卡、缅甸等国的佛教友好往来。",process:"1953年6月3日成立大会在北京广济寺召开，圆瑛当选会长，喜饶嘉措、达理亚、贡布慈丹（十世班禅）等任副会长；同年办理佛牙舍利赴缅甸等国供奉事宜。",impact:"形成“爱国宗教团体”管理模式，宗教事务被纳入统战与对外友好工作体系，此后的中国道教协会、伊斯兰教协会均仿此建立。",figures:["圆瑛","喜饶嘉措","赵朴初","十世班禅"],place:"北京广济寺",state:"中华人民共和国",sources:["《当代中国的宗教工作》（当代中国出版社）","《人民日报》1953年6月4日"],"tags":["宗教","佛教","统战"]},related:["cn--1954--i01"]},
  {id:"cn--1953--e02",track:"cn",year:1953,yearApprox:false,dim:"economy",weight:3,title:"城镇粮食定量供应与票证制度起步",summary:"统购统销配套实行城市按计划定量供应，凭票购粮。",detail:{background:"1953年10月中央决议要求同时管住销售端，否则收购粮食将继续流向黑市。",process:"1953年11月起北京、天津、上海等城市按人口与工种实行粮食定量供应并发票证；1955年8月25日国务院发布《市镇粮食定量供应暂行办法》，按重体力劳动、轻体力劳动、机关工作人员、一般居民、儿童等类别分等定量供应。",impact:"票证供应体制成为此后三十余年城镇民生分配的基本形态，并与户籍制度共同构成城乡分割的制度基础。",figures:["陈云","李先念","曾山"],place:"北京、天津、上海等城市",state:"中华人民共和国",sources:["《市镇粮食定量供应暂行办法》（1955年8月25日）","《当代中国的粮食工作》"],"tags":["票证","定量供应","民生"]},related:["cn--1953--i02", "cn--1955--e01"]},
  {id:"cn--1953--s01",track:"cn",year:1953,yearApprox:false,dim:"science",weight:3,title:"中国科学院编译出版委员会与规划准备",summary:"着手制定自然科学与技术十二年远景规划的前期调研。",detail:{background:"1951年中国科学院已设编译出版局与编译局；1952年底政务院财经委要求科学工作与国家计划衔接。",process:"1953年中国科学院调整所属研究所，撤销和合并13个研究所（局），新设力学、数学、应用物理等所；同年成立以竺可桢、钱三强等为核心的规划准备组，为1956年《十二年科技规划》提供学科底数。",impact:"完成了从“接收旧机构”向“按国家计划重排科研序列”的转换，1956年规划中的“紧急措施”项目多源于此期调查。",figures:["竺可桢","钱三强","郭沫若","恽子强"],place:"北京",state:"中华人民共和国",sources:["《中国科学院院典》","《当代中国的科学技术事业》（当代中国出版社）"],"tags":["科研体制","规划准备","科学院"]},related:["cn--1955--c01", "cn--1956--s02"]},
  {id:"cn--1954--p01",track:"cn",year:1954,yearApprox:false,dim:"politics",weight:3,title:"第一届全国人民代表大会第一次会议",summary:"9月15日开幕，1226名代表出席，通过第一部宪法。",detail:{background:"1953年基层普选后，由省、市、自治区与军队共选出代表1226人；会议因淮河流域防汛工作推迟。",process:"9月15日至28日在北京中南海怀仁堂召开，毛泽东致《为建设一个伟大的社会主义国家而奋斗》开幕词；会议通过宪法与五个组织法，选举毛泽东为国家主席，刘少奇当选全国人大常委会委员长，决定周恩来任国务院总理。",impact:"以根本法确认人民民主与社会主义两项原则、确立人民代表大会制度为政权组织形式，全国政协由此不再代行人大职权。",figures:["毛泽东","刘少奇","周恩来","宋庆龄","李济深"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["《第一届全国人民代表大会第一次会议汇刊》（1954年）","《建国以来毛泽东文稿》第5册"],"tags":["人大","制宪","国家主席"]},related:["cn--1954--i01", "cn--1949--i01", "cn--1954--p02"]},
  {id:"cn--1954--i01",track:"cn",year:1954,yearApprox:false,dim:"institution",weight:5,title:"“五四宪法”通过",summary:"9月20日无记名投票通过，共4章106条，确立根本政治制度。",detail:{background:"宪法起草委员会由中央人民政府委员会1953年1月13日决定成立、毛泽东任主席；毛泽东率起草小组1953年12月底赴杭州，约两个月完成初稿，1954年3月经中央政治局扩大会议讨论通过，6月起交付全民讨论。",process:"1954年9月20日一届全国人大一次会议以无记名投票全票通过《中华人民共和国宪法》，共4章106条。据中央人民政府委员会公布的报告，全国约1.5亿人参加讨论，提出修改与补充意见118万余条。宪法规定国家主席、全国人大常委会、国务院、地方各级人大与人民法院、人民检察院的职权。",impact:"取代《共同纲领》成为国家根本法，确立人大制度与民族区域自治的宪法地位；1982年宪法在结构与基本原则层面上的延续，使学界普遍称其为“八二宪法的蓝本”。",figures:["毛泽东","刘少奇","邓小平","张奚若"],place:"北京中南海怀仁堂（起草于杭州西湖刘庄）",state:"中华人民共和国",sources:["《中华人民共和国宪法》（1954年9月20日通过）","宪法起草委员会《关于宪法草案的报告》（1954年9月）"],"tags":["宪法","制宪","人大"]},related:["cn--1954--p01", "cn--1982--i01"]},
  {id:"cn--1954--p02",track:"cn",year:1954,yearApprox:false,dim:"politics",weight:3,title:"国务院组成与政务院撤销",summary:"9月27日任命周恩来为总理，11月1日国务院开始办公。",detail:{background:"宪法规定中央人民政府设国务院即中央人民政府，取代原政务院体制。",process:"1954年9月27日一届全国人大一次会议任命周恩来为国务院总理，29日任命副总理与各部部长；11月1日国务院正式办公，政务院印鉴缴回。军队系统9月28日成立中共中央军事委员会，毛泽东任主席，彭德怀主持军委日常工作。",impact:"完成中央机构由“委员会—政务院”向“人大—国务院”体系的转换，部委由政务院时期的35个调整为国务院初期的48个。",figures:["周恩来","陈云","彭德怀","邓小平"],place:"北京中南海",state:"中华人民共和国",sources:["《第一届全国人民代表大会第一次会议关于国务院组成人员的决定》（1954年9月27日）","《建国以来毛泽东文稿》第5册"],"tags":["国务院","改组","军委"]},related:["cn--1949--i02", "cn--1954--p01"]},
  {id:"cn--1954--p03",track:"cn",year:1954,yearApprox:false,dim:"politics",weight:4,title:"中印、中缅声明确认和平共处五项原则",summary:"6月、12月先后写入两国联合声明，成为中方外交基本准则。",detail:{background:"1953年12月31日周恩来在接见印度政府代表团时首次完整提出五项原则；1954年6月周恩来访印、访缅将其写入正式文件。",process:"6月28日《中印两国总理联合声明》、6月29日《中缅两国总理联合声明》均以互相尊重领土主权、互不侵犯、互不干涉内政、平等互惠、和平共处为准则；12月周恩来访缅再次确认，1955年万隆会议十项原则吸收其内容。",impact:"五项原则成为此后中国对外条约与联合声明中的常用条款，1950年代后期被多个亚非国家文件与1970年代联大有关国际经济秩序的文件引用。",figures:["周恩来","尼赫鲁","吴努"],place:"新德里、仰光、北京",state:"中华人民共和国",sources:["《中印两国总理联合声明》（1954年6月28日）","《周恩来外交文选》（1990年）"],"tags":["和平共处五项原则","周边外交","声明"]},related:["cn--1955--p05", "cn--1956--p03"]},
  {id:"cn--1954--s01",track:"cn",year:1954,yearApprox:false,dim:"science",weight:3,title:"武汉长江大桥正式开工",summary:"9月动工，采用管柱钻孔法，为长江上首座公铁两用桥。",detail:{background:"1950年起铁道部设计总局进行勘察与选线，苏联专家建议采用当时世界上少用的管柱基础方案。",process:"1954年9月正式开工（桥台工程），1955年7月1日主体开工；施工高峰期投入职工约2.8万人，苏联专家康斯坦丁·西林等参与技术审查，共完成管柱基础8个桥墩。",impact:"为1957年10月通车及京广线全线贯通创造条件；管柱法成为此后中国大跨度桥梁深水基础技术的起点。",figures:["彭敏","梅旸春","康斯坦丁·西林"],place:"湖北武昌蛇山与汉阳龟山之间",state:"中华人民共和国",sources:["《武汉长江大桥工程总结报告》（人民交通出版社）","《当代中国的桥梁建设》"],"tags":["桥梁","工程","管柱法"]},related:["cn--1957--s01", "cn--1968--s01"]},
  {id:"cn--1954--p04",track:"cn",year:1954,yearApprox:false,dim:"politics",weight:3,title:"日内瓦会议闭幕与中美会谈启动",summary:"7月21日签署印度支那停战协定，中美次年起举行大使级会谈。",detail:{background:"朝鲜问题因各方立场未达成协议；印度支那问题在越南民主共和国、老挝、柬埔寨问题上分别谈判。",process:"4月26日至7月21日，周恩来率中国代表团出席，与苏、美、英、法及越老柬三方谈判；7月21日签署关于在越南、老挝、柬埔寨停止敌对行动的协定，越南以北纬17度线临时分界。会外中方与英方代表接触，9月14日达成双方侨民遣返协议，随后自1955年8月1日起在日内瓦举行中美大使级会谈。",impact:"结束了印度支那战事并提升了新中国的多边谈判地位，中美大使级会谈此后延续15年、共136次。",figures:["周恩来","莫洛托夫","杜勒斯","艾登","范文同","王炳南"],place:"瑞士日内瓦",state:"中华人民共和国",sources:["《日内瓦会议最后宣言》（1954年7月21日）","《中华人民共和国外交史》第一卷"],"tags":["日内瓦","印度支那","中美会谈"]},related:["cn--1953--p02", "cn--1955--p05", "world--1954--p01", "world--1954--m01"]},
  {id:"cn--1954--p05",track:"cn",year:1954,yearApprox:false,dim:"politics",weight:3,title:"全国政协二届一次会议",summary:"12月21日至25日召开，通过章程并明确政协不再是权力机关。",detail:{background:"一届全国人大已召开，政协代行人大职权的历史任务结束，需要重新界定其性质与职能。",process:"1954年12月21日至25日中国人民政治协商会议第二届全国委员会第一次会议在北京召开，到会委员559人；会议通过《中国人民政治协商会议章程》，毛泽东在同年的最高国务会议上说明政协是各党派的“政治协商机关”，周恩来当选主席。",impact:"确立政协作为统一战线组织而非国家权力机关的定位，其政治协商、民主监督职能为此后数十年运行框架。",figures:["周恩来","毛泽东","李济深","章伯钧"],place:"北京",state:"中华人民共和国",sources:["《中国人民政治协商会议章程》（1954年12月25日通过）","《政协第二届全国委员会第一次会议文件汇刊》"],"tags":["政协","统一战线","定位"]},related:["cn--1949--p01", "cn--1954--p01"]},
  {id:"cn--1954--d01",track:"cn",year:1954,yearApprox:false,dim:"disaster",weight:3,title:"1954年长江淮河流域大水",summary:"6至8月持续暴雨，长江中下游与皖北受灾人口约1888万。",detail:{background:"1954年梅雨期延长，长江、淮河、辽河等流域多条支流同时涨水，江汉平原与皖北受灾最重。",process:"据中央防汛总指挥部资料，1954年长江流域持续13次洪水，武汉关8月18日水位达29.73米；全国受灾面积约1.7亿亩，受灾人口约1888万人，死亡约3万人，倒塌房屋214万间。荆江分洪区三次开闸分洪。",impact:"中央决定加固荆江大堤、扩大蓄洪垦殖与汉丹、焦枝等铁路改线论证，并把大规模水利建设列入“一五”计划追加项目。",figures:["林一山","王任重","李四光"],place:"湖北、安徽、江苏、湖南、辽宁",state:"中华人民共和国",sources:["《中国水旱灾害》（水利电力出版社）","《当代中国的水利事业》"],"tags":["洪灾","长江","防汛"]},related:["cn--1951--s01", "cn--1954--s01"]},
  {id:"cn--1955--p06",track:"cn",year:1955,yearApprox:false,dim:"politics",weight:3,title:"一届人大二次会议批准一五计划",summary:"7月5日至30日会议听取李富春报告，正式通过第一个五年计划。",detail:{background:"计划草案自1951年起编制，1953、1954年两次修订控制数字，1955年3月已先经党的全国代表会议讨论。",process:"1955年7月5日至30日第一届全国人民代表大会第二次会议在北京召开，李富春作《关于发展国民经济的第一个五年计划的报告》；7月30日会议通过决议，批准计划草案，规定五年全国正常预算收入与支出均约972亿元，经济文化建设支出占59.8%。",impact:"五年计划由此成为具有法律效力的国家建设纲领，其指标体系与编制程序构成此后历次五年计划的模板。",figures:["李富春","周恩来","陈云","邓小平"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["《中华人民共和国发展国民经济的第一个五年计划（1953—1957）》（人民出版社，1955年）、《第一届全国人民代表大会第二次会议汇刊》"],"tags":["五年计划","立法程序","指标"]},related:["cn--1953--e01", "cn--1955--p02"]},
  {id:"cn--1955--p01",track:"cn",year:1955,yearApprox:false,dim:"politics",weight:3,title:"中国人民解放军首次实行军衔制",summary:"9月27、28日授衔，产生10位元帅、10位大将、上千名将军。",detail:{background:"1952年起总干部部着手准备，1955年2月8日主席令公布《中国人民解放军军官服役条例》。",process:"9月27日主席团授予朱德、彭德怀、林彪、刘伯承、贺龙、陈毅、罗荣桓、徐向前、聂荣臻、叶剑英元帅军衔；同日国务院授予粟裕、徐海东、黄克诚、陈赓、肖劲光、张云逸、罗瑞卿、王树声、许光达等10人大将军衔。据《中国人民解放军军史》记载，1955年至1965年先后授予将官以上军衔者为元帅10名、大将10名、上将57名、中将177名、少将1360名。",impact:"结束了长期延续的供给制与无等级传统，建立正规化军衔与薪金体系，是军队专业化建设的关键一步；军衔制于1965年5月被取消。",figures:["毛泽东","朱德","彭德怀","罗荣桓","粟裕"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["《中国人民解放军军官服役条例》（1955年2月8日主席令）","《中华人民共和国授衔资料》（解放军出版社）"],"tags":["授衔","军制","正规化"]},related:["cn--1952--i03", "cn--1955--i01"]},
  {id:"cn--1955--p02",track:"cn",year:1955,yearApprox:false,dim:"politics",weight:3,title:"党的全国代表会议通过一五计划与开除高饶",summary:"3月21日至31日代表会议出席1036人，通过两项关键决议。",detail:{background:"“一五”计划草案需在提交人大前先经党内程序，同时高饶问题的组织处理也需在全国层面确认。",process:"1955年3月21日至31日在北京召开中国共产党全国代表会议，通过《关于发展国民经济的第一个五年计划的决议》与《关于高岗、饶漱石反党联盟的决议》，开除高岗、饶漱石、向明、郭锋等党籍；选举产生中央监察委员会，董必武任书记。",impact:"完成“一五”计划的党内立法程序，并以设立监察委员会取代原纪律检查委员会，改变党内监督机构序列。",figures:["毛泽东","邓小平","陈云","董必武"],place:"北京",state:"中华人民共和国",sources:["《中国共产党全国代表会议关于发展国民经济的第一个五年计划的决议》（1955年3月31日）","《建国以来重要文献选编》第6册"],"tags":["代表会议","一五计划","纪律检查"]},related:["cn--1953--e01", "cn--1953--p03"]},
  {id:"cn--1955--p04",track:"cn",year:1955,yearApprox:false,dim:"politics",weight:4,title:"农业合作化高潮启动",summary:"7月毛泽东作报告后批评“小脚女人”，合作社数量一年内倍增。",detail:{background:"1955年上半年全国农业生产合作社达67万个，中央内部围绕“要不要收缩”出现意见分歧。",process:"7月31日至8月1日中央召集省、市、自治区党委书记会议，毛泽东作《关于农业合作化问题》报告；9月编辑《中国农村的社会主义高潮》并写序言，批评“右倾机会主义”；10月4日至11日七届六中全会通过《关于农业合作化问题的决议》。到1955年底合作社由67万个增至150余万个，入社农户比例由14%升至60%以上。",impact:"原设想约需15年的合作化被压缩到1956年基本实现，1958年人民公社化直接建立在这一组织基础与批右倾政治氛围之上。",figures:["毛泽东","邓子恢","谭震林","廖鲁言"],place:"北京（报告于中南海怀仁堂）",state:"中华人民共和国",sources:["毛泽东《关于农业合作化问题》（1955年7月31日）","《中国农村的社会主义高潮》序言（1955年9月）"],"tags":["合作化","农业","批右倾"]},related:["cn--1956--e01", "cn--1958--p02"]},
  {id:"cn--1955--p05",track:"cn",year:1955,yearApprox:false,dim:"politics",weight:4,title:"万隆亚非会议召开",summary:"4月18日至24日29国与会，周恩来提出“求同存异”。",detail:{background:"1954年科伦坡五国会议倡议，1955年在印度尼西亚筹备；会议初期出现针对共产主义的争论发言。",process:"4月18日至24日在万隆举行，与会29国代表出席；4月19日周恩来在全体会议作补充发言，提出“中国代表团是来求团结而不是来吵架的”“我们是来求同而不是来立异的”；会议通过《关于促进世界和平与合作的宣言》形成十项原则，并决议设立亚非国家文化与经济合作机制。",impact:"打开中国与埃及、印尼、缅甸、阿富汗等国的建交与援助渠道。据外交部《中华人民共和国外交史》记载，1956至1958年新增建交国中多数为亚非国家。",figures:["周恩来","苏加诺","尼赫鲁","吴努","陈毅"],place:"印度尼西亚万隆会议大厦",state:"中华人民共和国",sources:["《周恩来在亚非会议全体会议上的补充发言》（1955年4月19日）","《亚非会议最后公报》（1955年4月24日）"],"tags":["万隆","求同存异","第三世界"]},related:["cn--1954--p03", "cn--1956--p03", "world--1955--p03"]},
  {id:"cn--1955--p03",track:"cn",year:1955,yearApprox:false,dim:"politics",weight:3,title:"新疆维吾尔自治区成立",summary:"10月1日成立，为第二个省级少数民族自治区。",detail:{background:"1953至1954年完成全区民族识别与自治准备工作，1955年9月召开首届人大一次会议。",process:"1955年9月14日国务院全体会议第17次会议通过《关于成立新疆维吾尔自治区、撤销新疆省建制的议案》，10月1日新疆维吾尔自治区正式成立，赛福鼎·艾则孜当选自治区主席；全区少数民族干部比例由1952年的约34%升至1957年前后接近半数。",impact:"标志民族区域自治在西北边疆全面落地，1958年广西壮族自治区、宁夏回族自治区相继成立，1965年西藏自治区成立。",figures:["赛福鼎·艾则孜","王恩茂","乌兰夫"],place:"乌鲁木齐",state:"中华人民共和国",sources:["《国务院关于成立新疆维吾尔自治区、撤销新疆省建制的议案》（1955年9月14日）、《新疆通志·大事记》"],"tags":["民族区域自治","新疆","建制"]},related:["cn--1952--i02", "cn--1965--p02"]},
  {id:"cn--1955--e01",track:"cn",year:1955,yearApprox:false,dim:"economy",weight:3,title:"农村粮食“三定”到户",summary:"8月国务院发布定产、定购、定销办法，缓解统购过头粮矛盾。",detail:{background:"1954年度粮食征购中部分地区的“过头粮”引发农民不满，据陈云在国务院会议上的说明，1954年多购了约70亿斤粮食。",process:"1955年8月25日国务院颁布《农村粮食统购统销暂行办法》与《市镇粮食定量供应暂行办法》，实行定产、定购、定销三年不变，并以户为单位公布数字；同时压缩征购指标，据《中国共产党的九十年》记载，1955年4月中央决定把粮食征购指标由原定的926亿斤减为830亿斤。",impact:"在不改变统购体制的前提下抑制“购过头粮”，1955至1957年粮食供应趋于稳定；但“以户见面”在合作化高潮中被合作社统一数字取代。",figures:["陈云","李先念","曾山"],place:"全国农村（决定于北京作出）",state:"中华人民共和国",sources:["《农村粮食统购统销暂行办法》（1955年8月25日）、《建国以来重要文献选编》第7册"],"tags":["粮食","三定","统购"]},related:["cn--1953--i02", "cn--1959--e01"]},
  {id:"cn--1955--e02",track:"cn",year:1955,yearApprox:false,dim:"economy",weight:3,title:"私营工商业改造决议草案通过",summary:"11月中央政治局会议通过决议，确定实行全行业公私合营与定息。",detail:{background:"“一五”期间加工订货与统购包销已将私营工业纳入国家计划，中央认为具备全面改造条件。",process:"1955年10月中央召开资本家座谈会并放映合作化纪录片；10月27日至12月17日中央政治局会议（11月16日至24日为第二次会议）通过《关于资本主义工商业改造问题的决议（草案）》，确定把私营工商业通过国家资本主义改造为社会主义企业，实行定息办法。",impact:"1956年底全国私营工业产值99%、商业零售总额82%纳入公私合营或合作组织，城市私营与个体经济几近消失。",figures:["陈云","李维汉","毛泽东","荣毅仁"],place:"北京、上海、天津、武汉",state:"中华人民共和国",sources:["《中共中央关于资本主义工商业改造问题的决议（草案）》（1955年11月）、《当代中国资本主义工商业的社会主义改造》"],"tags":["公私合营","定息","工商业改造"]},related:["cn--1952--p01", "cn--1956--i01"]},
  {id:"cn--1955--s01",track:"cn",year:1955,yearApprox:false,dim:"science",weight:3,title:"第一辆解放牌载重汽车下线",summary:"7月13日长春第一汽车制造厂试制成功CA10型4吨载货车。",detail:{background:"第一汽车制造厂列入156项工程，1953年7月15日在长春奠基，苏联提供产品图纸与工艺装备，投资约4亿元。",process:"1955年7月13日第一辆“解放”牌CA10型载重汽车装配下线，最高时速65公里、载重4吨；1956年7月15日全厂正式投产，当年生产4000辆，1957年达1.3万余辆。",impact:"结束中国不能批量制造汽车的历史；长春此后长期承担中国汽车工业的技术扩散与人才培养，1980年代二汽建设即由此输出干部与图纸。",figures:["郭力","孟少农","饶斌"],place:"吉林长春第一汽车制造厂",state:"中华人民共和国",sources:["《中国汽车工业史（1953—1997）》（机械工业出版社）、《人民日报》1956年7月15日"],"tags":["汽车工业","156项","长春"]},related:["cn--1953--e01", "cn--1956--p05"]},
  {id:"cn--1955--c01",track:"cn",year:1955,yearApprox:false,dim:"culture",weight:3,title:"中国科学院学部成立",summary:"6月设立四大学部，选聘163名（后为217名）首批学部委员。",detail:{background:"1949年建院后仿照苏联科学院模式设立学部，以解决全国学术领导机构缺位问题。",process:"1955年6月1日至9日中国科学院学部成立大会在北京举行，设数理、化学、生物、哲学社会科学四部共23个专门学部，选聘首批学部委员163人；1956年补选哲学社会科学部委员57人，共217人（含1957年前递补）。",impact:"形成“学部委员”这一国家最高学术称号体系，1993年10月改为院士制度后，首批名单仍被视为当代中国学术谱系的起点。",figures:["郭沫若","李四光","竺可桢","茅以升","华罗庚"],place:"北京",state:"中华人民共和国",sources:["《中国科学院院典（1949—1999）》","《人民日报》1955年6月2日"],"tags":["科学院","学部","学术体制"]},related:["cn--1953--s01", "cn--1956--s02"]},
  {id:"cn--1955--i01",track:"cn",year:1955,yearApprox:false,dim:"institution",weight:3,title:"兵役法公布，义务兵役制取代志愿兵制",summary:"7月30日通过第一部兵役法，1955冬季起征兵。",detail:{background:"朝鲜战争结束后需要稳定的兵员补充与预备役制度，1955年3月全国代表会议已作布置。",process:"1955年7月30日一届全国人大二次会议通过《中华人民共和国兵役法》，规定志愿兵役制改为义务兵役制，步兵服役4年、空军5年、海军3年；1955年冬至1956年春在全国各县（市）分批进行首次征集，据《当代中国的军事工作》记载，征集工作按“统一计划、分批分期、就地分配”的原则实施。",impact:"完成军队兵员制度由革命战争时期的志愿、募补制向法定义务兵役的转换，预备役与退伍军人安置制度同步建立。",figures:["彭德怀","聂荣臻","罗荣桓"],place:"北京；全国各县（市）分批实施",state:"中华人民共和国",sources:["《中华人民共和国兵役法》（1955年7月30日）、《当代中国的军事工作》"],"tags":["兵役法","义务兵役","军制"]},related:["cn--1955--p01", "cn--1978--i02"]},
  {id:"cn--1956--p01",track:"cn",year:1956,yearApprox:false,dim:"politics",weight:4,title:"《论十大关系》发表",summary:"4月25日政治局扩大会议讲话，提出调动一切积极因素建设社会主义。",detail:{background:"1956年2月至4月中央听取国务院34个部门汇报，历时一个半月，形成对苏联模式的系统反思。",process:"4月25日毛泽东在中央政治局扩大会议上作《论十大关系》报告，论述重工业与轻工业农业、沿海与内地、中央与地方、党与非党、汉族与少数民族等十大关系；5月2日在最高国务会议再次阐述，1976年12月由《人民日报》公开发表。",impact:"学界普遍视为独立探索社会主义建设道路的开端，其农轻重比例的思路反映在中共八大“二五”计划建议与1957年的安排中。",figures:["毛泽东","刘少奇","周恩来","陈云"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["毛泽东《论十大关系》（1956年4月25日讲话）、《毛泽东文集》第七卷"],"tags":["十大关系","路线探索","苏联模式"]},related:["cn--1956--p02", "cn--1957--e01"]},
  {id:"cn--1956--p02",track:"cn",year:1956,yearApprox:false,dim:"politics",weight:4,title:"中共八大召开",summary:"9月15日至27日1026名代表出席，提出国内主要矛盾已经变化。",detail:{background:"七大后十一年未开全国代表大会，“一五”临近收官，需要确立新的建设路线与党章。",process:"9月15日至27日在北京全国政协礼堂召开，出席代表1026人、56个外国共产党和工人党代表团与会；毛泽东致开幕词，刘少奇作政治报告，邓小平作关于修改党章的报告，周恩来作“二五”计划建议报告。大会指出国内主要矛盾已是人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾。",impact:"八大路线在1957年下半年反右扩大化后实际被搁置；1981年《关于建国以来党的若干历史问题的决议》重新肯定“八大所制定的路线是正确的”。",figures:["毛泽东","刘少奇","周恩来","邓小平","陈云","米高扬"],place:"北京全国政协礼堂",state:"中华人民共和国",sources:["《中国共产党第八次全国代表大会文献》（人民出版社，1957年）、《关于建国以来党的若干历史问题的决议》（1981年）"],"tags":["八大","主要矛盾","党章"]},related:["cn--1957--p01", "cn--1958--p01", "cn--1956--e01"]},
  {id:"cn--1956--c01",track:"cn",year:1956,yearApprox:false,dim:"culture",weight:4,title:"“百花齐放、百家争鸣”方针系统阐述",summary:"5月26日陆定一作报告，双百成为科学文艺工作方针。",detail:{background:"1956年1月知识分子问题会议确定“向科学进军”，4月28日毛泽东在政治局扩大会议上提出“艺术上不同的形式和风格可以自由发展，科学上不同的学派可以自由争论”。",process:"5月26日中央宣传部在北京召开1000多人大会，陆定一作《百花齐放，百家争鸣》报告系统阐述方针；6月《文汇报》发表关于遗传学、文学批评的讨论文章，学界围绕米丘林—李森科学派与摩尔根学派的评价展开争鸣。",impact:"1957年反右派斗争扩大化后该方针被长期中断；1978年后重新恢复执行，1980年邓小平在中国文联四大上不再以阶级斗争口径解释文艺问题。",figures:["毛泽东","陆定一","周扬","郭沫若"],place:"北京",state:"中华人民共和国",sources:["陆定一《百花齐放，百家争鸣》（1956年5月26日）、《建国以来重要文献选编》第9册"],"tags":["双百方针","学术","文艺"]},related:["cn--1957--p01", "cn--1949--c01"]},
  {id:"cn--1956--e01",track:"cn",year:1956,yearApprox:false,dim:"economy",weight:4,title:"社会主义改造基本完成",summary:"据国家统计局，1956年公有制经济在国民收入中占约92.7%。",detail:{background:"1955年下半年农业合作化与1956年初全行业公私合营相继形成高潮。",process:"据国家统计局《1956年国民经济计划执行结果的公报》，1956年国民收入中社会主义公有制经济占92.7%，其中国营经济占53.4%、合作社经济占32.8%、公私合营经济占8.1%；资本家按核定股额领取年息5%定息，期限原拟7年、后延长至1966年9月停发。",impact:"确立单一公有制与计划经济的基础。同期出现的自发市场经营与“地下工厂”现象，促使1956年12月陈云提出“三个主体、三个补充”设想。",figures:["毛泽东","刘少奇","陈云","李维汉"],place:"全国（统计口径见国家统计局公报）",state:"中华人民共和国",sources:["国家统计局《1956年国民经济计划执行结果的公报》","《陈云文选》第三卷"],"tags":["三大改造","公有制","定息"]},related:["cn--1955--e02", "cn--1956--i01"]},
  {id:"cn--1956--i01",track:"cn",year:1956,yearApprox:false,dim:"institution",weight:4,title:"全行业公私合营高潮",summary:"1月至2月全国多数城市实现资本主义工商业全行业合营。",detail:{background:"1955年11月中央决议草案通过后，北京率先行动，工商界递交合营申请形成风潮。",process:"1956年1月10日北京宣布全行业公私合营，1月底全国50个大中城市、2月扩展至93个市与43个县；全国8.8万余户私营工业、240万余户私营商业实行全行业合营，涉及私营职工约330万人。",impact:"城市产权结构在极短时间内完成国家接管，但清产核资与人事安排粗糙，此后出现小商品品种减少、服务网点收缩等问题，1956年下半年国务院多次发文善后。",figures:["陈云","荣毅仁","李烛尘","胡子昂"],place:"北京、上海、天津、广州、武汉",state:"中华人民共和国",sources:["《关于资本主义工商业社会主义改造问题的报告》（陈云，1956年1月）、《当代中国的城市经济体制改革》"],"tags":["公私合营","定息","城市经济"]},related:["cn--1955--e02", "cn--1956--e01"]},
  {id:"cn--1956--e02",track:"cn",year:1956,yearApprox:false,dim:"economy",weight:3,title:"中共八届二中全会反对急躁冒进",summary:"11月会议确定1957年基建投资111亿元，重申反对急躁冒进。",detail:{background:"1956年基本建设规模失控，全年基建投资135亿元、比上年接近翻番并超过计划约60亿元，财政、物资与信贷三口出现不平衡，钢材、水泥与日用消费品供应紧张。",process:"11月10日至15日中共八届二中全会在北京召开，周恩来作《关于1957年国民经济收支预算的发言》、陈云谈建设规模与国力适应问题；会议确定1957年基建投资111亿元、钢产量412万吨。",impact:"“既反保守又反冒进、在综合平衡中稳步前进”成为1957年经济工作方针，但在1958年1月南宁会议上被毛泽东点名批评，反冒进从此成为政治错误。",figures:["周恩来","陈云","李先念","薄一波"],place:"北京中南海",state:"中华人民共和国",sources:["《建国以来重要文献选编》第9册、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["反冒进","综合平衡","指标调整"]},related:["cn--1957--e01", "cn--1958--p03"]},
  {id:"cn--1956--p03",track:"cn",year:1956,yearApprox:false,dim:"politics",weight:3,title:"与埃及、柬埔寨建交并启动对外援助",summary:"5月、8月先后建交，同年对外经援以优惠贷款与成套项目为主。",detail:{background:"万隆会议后中方以经济技术援助打开与阿拉伯国家及东南亚国家的关系。",process:"1956年5月30日与埃及建交，8月1日与柬埔寨建交；据《中华人民共和国外交史》记载，1956年中国政府与多国签订经济援助协定，援助形式以优惠贷款和成套项目施工为主，项目集中在纺织、水泥、制糖等轻工业。",impact:"初步形成中国对外经济援助的操作范式；1964年周恩来访问非洲十国期间提出的对外经济技术援助八项原则即在此基础上总结形成。",figures:["周恩来","纳赛尔","西哈努克","陈毅"],place:"北京、开罗、金边",state:"中华人民共和国",sources:["《中华人民共和国外交史》第一卷（1949—1956，世界知识出版社）","《中国的对外援助》白皮书（国务院新闻办公室，2011年）"],"tags":["建交","对外援助","万隆"]},related:["cn--1955--p05", "cn--1954--p03"]},
  {id:"cn--1956--p04",track:"cn",year:1956,yearApprox:false,dim:"politics",weight:3,title:"中共八大设立书记处与集体领导制度调整",summary:"9月至11月选出中央委员97人、候补73人，邓小平任总书记。",detail:{background:"1956年9月政治局会议讨论修改党章，决定中央委员会设总书记与副主席若干人，不设主席以下的个人集权结构。",process:"9月27日八大选举中央委员会委员97人、候补委员73人；11月15日八届一中全会选举毛泽东为中央委员会主席，刘少奇、周恩来、朱德、陈云为副主席，邓小平为总书记，由6人组成中央政治局常务委员会。",impact:"形成此后二十余年沿用的高层组织形式，1969年九大党章改设“副主席和接班人”条款后该结构中断。",figures:["毛泽东","邓小平","刘少奇","周恩来","陈云","朱德"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第八届中央委员会第一次全体会议公报》（1956年11月15日）、《中国共产党章程》（1956年9月26日通过）"],"tags":["八大","书记处","组织制度"]},related:["cn--1956--p02", "cn--1969--p01"]},
  {id:"cn--1956--p05",track:"cn",year:1956,yearApprox:false,dim:"politics",weight:3,title:"第一汽车制造厂正式投产",summary:"7月15日建成投产，年产能3万辆，结束不批量造车的历史。",detail:{background:"该厂列入156项工程，1953年7月15日奠基，1955年7月试制出第一辆解放牌汽车。",process:"1956年7月15日第一汽车制造厂举行建成投产典礼，设计年产3万辆载重汽车，全厂建筑面积约100万平方米、设备总台套约1.2万台（其中从苏联、东欧进口约半数）；1956年至1957年累计生产1.7万余辆。",impact:"奠定长春作为中国汽车工业基地的地位，其图纸、工艺与干部支撑了1960年代第二汽车制造厂与四川汽车厂的建设。",figures:["饶斌","郭力","孟少农"],place:"吉林长春",state:"中华人民共和国",sources:["《中国汽车工业史（1953—1997）》、《人民日报》1956年7月16日"],"tags":["汽车工业","投产","156项"]},related:["cn--1955--s01", "cn--1953--e01"]},
  {id:"cn--1956--s02",track:"cn",year:1956,yearApprox:false,dim:"science",weight:4,title:"十二年科技发展规划制定",summary:"《1956—1967年科学技术发展远景规划纲要》确定57项重点任务。",detail:{background:"1956年1月知识分子问题会议提出“向科学进军”，国务院成立科学规划委员会，由陈毅任主任，数百名科学家与苏联专家参与编制。",process:"规划自1956年初分专业组起草，1956年6月形成《1956—1967年科学技术发展远景规划纲要（修正草案）》，共列出57项重要科学技术任务、近600个中心问题，并对核技术、半导体、计算机、电子学、自动化、喷气技术采取“紧急措施”。",impact:"以“任务带学科”的方式建立了中国科技规划体制，1958年中国科学技术大学在规划牵引下成立；据《当代中国的科学技术事业》记载，规划的主要任务在1963年前后提前完成。",figures:["陈毅","郭沫若","李四光","竺可桢","钱学森","华罗庚"],place:"北京、武汉",state:"中华人民共和国",sources:["《1956—1967年科学技术发展远景规划纲要（修正草案）》、《当代中国的科学技术事业》"],"tags":["科技规划","紧急措施","向科学进军"]},related:["cn--1955--c01", "cn--1964--s01"]},
  {id:"cn--1956--i02",track:"cn",year:1956,yearApprox:false,dim:"institution",weight:3,title:"全国工资改革与等级工资制",summary:"6月国务院决定改革工资制度，建立机关与企业的等级工资序列。",detail:{background:"建国初期供给制与工资制并存，地区之间、行业之间报酬混乱，工业化要求统一的等级工资制度。",process:"1956年6月16日国务院通过并公布《关于工资改革的决定》，把全国机关、企事业单位职工工资统一为按产业、职务分级的等级工资制，国家机关行政人员分为24级；改革覆盖全国约5000万职工中的绝大多数，1956年职工年平均工资比上年提高约14.5%。",impact:"形成此后近三十年基本稳定的等级工资序列，其级别与职务相对分离的做法延续到1985年结构工资制改革。",figures:["周恩来","李先念","薄一波"],place:"全国（决定在北京作出）",state:"中华人民共和国",sources:["《国务院关于工资改革的决定》（1956年6月16日）、《当代中国的劳动工资》"],"tags":["工资改革","等级制","分配制度"]},related:["cn--1952--i03", "cn--1955--p01"]},
  {id:"cn--1956--c02",track:"cn",year:1956,yearApprox:false,dim:"culture",weight:3,title:"知识分子问题会议与“向科学进军”",summary:"1月14日至20日会议，周恩来作报告并改变知识分子阶级属性判断。",detail:{background:"1955年底中央在筹备会议上判断全国科学技术人才与高等学府师资严重不足，已不能适应有计划的经济建设需要。",process:"1956年1月14日至20日中共中央召开关于知识分子问题的会议，周恩来作《关于知识分子问题的报告》，指出知识分子已经是工人阶级的一部分，并部署在12年内扩大科学院、高校与专业科研人员队伍；会议同时决定成立中央知识分子问题十人小组。",impact:"直接催生了十二年科学技术发展远景规划与1956年高校、科研机构的扩招扩编；1957年后该判断被批判为“忽视阶级斗争”。",figures:["周恩来","陈毅","陆定一","郭沫若"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["周恩来《关于知识分子问题的报告》（1956年1月14日）、《建国以来重要文献选编》第8册"],"tags":["知识分子","向科学进军","科技政策"]},related:["cn--1956--s02", "cn--1978--s01"]},
  {id:"cn--1957--p01",track:"cn",year:1957,yearApprox:false,dim:"politics",weight:4,title:"整风运动启动",summary:"4月27日中央发出整风指示，5月起召开党外人士座谈会听取批评。",detail:{background:"1956年9月八大已提出反对主观主义、宗派主义与官僚主义；1957年2月最高国务会议后，中央决定以正确处理人民内部矛盾为主题开展整风。",process:"1957年4月27日中共中央发出《关于整风运动的指示》，规定以正确处理人民内部矛盾为主题，反对官僚主义、宗派主义和主观主义；5月上旬起中央统战部和民盟等先后召开座谈会，6月6日中共召开民主人士座谈会听取批评意见。",impact:"整风由党内教育转为发动党外人士提意见，为随后转向反击右派提供了政治场景；6月8日《人民日报》发表社论《这是为什么？》，运动方向自此改变。",figures:["毛泽东","刘少奇","邓小平","陆定一"],place:"北京；全国各省市",state:"中华人民共和国",sources:["《中共中央关于整风运动的指示》（1957年4月27日）、《建国以来重要文献选编》第10册"],"tags":["整风","官僚主义","党外座谈"]},related:["cn--1957--p02", "cn--1956--p02", "cn--1957--c01"]},
  {id:"cn--1957--p02",track:"cn",year:1957,yearApprox:false,dim:"politics",weight:5,title:"反右派斗争及其扩大化",summary:"6月8日中央发出反击指示，1981年历史决议认定斗争被严重扩大化。",detail:{background:"整风座谈中出现质疑中国共产党领导、质疑社会主义制度的言论，中央判断为政治性进攻。",process:"1957年6月8日中共中央发出《关于组织力量准备反击右派分子进攻的指示》，同日《人民日报》发表《这是为什么？》社论；9月至10月在杭州召开的八届三中全会把反右派斗争延伸到地、县。据1981年《关于建国以来党的若干历史问题的决议》记载，“反右派斗争被严重地扩大化了”。",impact:"按1980年代复查改正工作汇总的口径，全国被划为右派分子者55万余人；据中央组织部等五部门1978年9月印发的实施方案，为错划右派改正的工作在1978年底至1981年陆续完成。这一事件此后长期影响党外知识分子与多党合作。",figures:["毛泽东","陆定一","邓小平","章伯钧"],place:"北京；全国高校与机关",state:"中华人民共和国",sources:["《关于建国以来党的若干历史问题的决议》（1981年6月）","《建国以来重要文献选编》第10册","中央组织部等五部门关于摘掉右派分子帽子的实施方案（1978年9月）"],"tags":["反右","扩大化","历史决议"]},related:["cn--1957--p01", "cn--1957--c01", "cn--1958--p01"]},
  {id:"cn--1957--c01",track:"cn",year:1957,yearApprox:false,dim:"culture",weight:4,title:"《关于正确处理人民内部矛盾的问题》发表",summary:"2月27日讲话、6月19日见报，提出两类矛盾学说。",detail:{background:"1956年波兰、匈牙利事件后，中央着手讨论社会主义社会的矛盾问题；1957年2月扩大的最高国务会议为讲话提供了场合。",process:"2月27日毛泽东在中南海怀仁堂扩大的最高国务会议上作《如何处理人民内部的矛盾》讲话，论述敌我矛盾与人民内部矛盾的区分，涉及肃反、统筹兼顾与各派关系、“百家争鸣”等12个问题；6月19日整理稿《关于正确处理人民内部矛盾的问题》在《人民日报》公开发表。",impact:"“两类矛盾”成为此后国家处理社会问题的官方分析框架；“长期共存、互相监督”作为多党合作方针写入1957年后文件，并在1982年宪法序言中扩展为十六字方针。",figures:["毛泽东","陆定一","李维汉"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["毛泽东《关于正确处理人民内部矛盾的问题》（1957年2月27日讲话、6月19日发表）、《毛泽东文集》第七卷"],"tags":["两类矛盾","长期共存","最高国务会议"]},related:["cn--1957--p01", "cn--1956--c01", "cn--1982--i01"]},
  {id:"cn--1957--e01",track:"cn",year:1957,yearApprox:false,dim:"economy",weight:3,title:"第一个五年计划超额完成",summary:"1957年工农业总产值1241亿元，钢产量535万吨。",detail:{background:"1953—1957年计划以156项建设工程为中心，1955年7月经一届全国人大二次会议批准。",process:"据国家统计局公布的执行结果，1957年全国工农业总产值1241亿元，比1952年增长67.8%；国民收入910亿元，比1952年增长53%；钢535万吨、原煤1.31亿吨、粮食3900亿斤；五年全国完成固定资产投资780余亿元，新增固定资产492亿元。",impact:"计划指标普遍提前完成，使中央形成“可以更快些”的判断；1957年10月八届三中全会后“二五”计划指标被逐步抬高，1958年提出以15年在主要工业产品产量上赶上英国。",figures:["周恩来","陈云","李富春","薄一波"],place:"全国",state:"中华人民共和国",sources:["国家统计局《关于1957年国民经济计划执行结果的公报》（1958年2月）、《中国统计年鉴（1981）》"],"tags":["一五计划","统计","工业化"]},related:["cn--1953--e01", "cn--1957--s01", "cn--1958--e01"]},
  {id:"cn--1957--s01",track:"cn",year:1957,yearApprox:false,dim:"science",weight:3,title:"武汉长江大桥建成通车",summary:"10月15日通车，京汉、粤汉两线自此接轨为京广铁路。",detail:{background:"大桥1955年9月1日主体开工，采用苏联专家建议的管柱钻孔法基础方案，由武汉长江大桥工程局施工。",process:"1957年10月15日举行建成通车典礼，正桥长1155.5米、8墩9孔，公铁两用双层布置，下层为双轨铁路、上层为4车道公路，连同引桥全长1670米；施工高峰期职工约2.8万人。通车后京汉、粤汉铁路接轨为京广铁路。",impact:"结束长江天堑阻断南北铁路干线的局面；管柱基础技术在此后1968年南京长江大桥的自主设计中被延用并发展为深水基础成套工艺。",figures:["彭敏","梅旸春","康斯坦丁·西林"],place:"湖北武汉蛇山与龟山之间",state:"中华人民共和国",sources:["《武汉长江大桥工程总结报告》（人民交通出版社）、《人民日报》1957年10月16日"],"tags":["桥梁","京广铁路","管柱法"]},related:["cn--1954--s01", "cn--1968--s01"]},
  {id:"cn--1958--p01",track:"cn",year:1958,yearApprox:false,dim:"politics",weight:4,title:"社会主义建设总路线",summary:"5月20日八大二次会议通过“鼓足干劲、力争上游、多快好省”。",detail:{background:"1957年11月莫斯科会议期间中方提出15年在主要工业产品产量上赶上英国的设想；1958年初南宁会议后反冒进被否定。",process:"1958年5月5日至23日中共八大第二次会议在北京召开，5月20日正式通过“鼓足干劲、力争上游、多快好省地建设社会主义”的总路线；会议同时通过关于在15年内或更短时间内赶上英国、关于在继续完成经济政治思想战线社会主义革命的同时技术革命与文化革命为战略任务的决议。",impact:"总路线强调主观努力与速度，弱化了综合平衡约束，成为大跃进与人民公社化运动的直接依据；1981年历史决议认为总路线“反映了广大人民要求加快经济发展的迫切愿望，但也忽视了客观的经济规律”。",figures:["毛泽东","刘少奇","邓小平","周恩来"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["《中国共产党第八次全国代表大会第二次会议关于中央委员会的工作报告的决议》（1958年5月20日）、《建国以来重要文献选编》第11册"],"tags":["总路线","八大二次","多快好省"]},related:["cn--1958--p02", "cn--1958--p03", "cn--1956--p02"]},
  {id:"cn--1958--p02",track:"cn",year:1958,yearApprox:false,dim:"politics",weight:5,title:"人民公社化运动",summary:"8月29日北戴河会议作出建立人民公社决议，年底入社农户超九成。",detail:{background:"1958年4月河南遂平嵖岈山卫星人民公社试行，多地出现小社并大社、办公共食堂与“组织军事化、行动战斗化、生活集体化”。",process:"1958年8月17日至30日北戴河中央政治局扩大会议通过《关于在农村建立人民公社问题的决议》，要求全国农村尽快实现公社化；会议同时确定1958年钢产量1070万吨、比1957年翻一番。据国家统计局资料，到1958年底全国将74万余个农业合作社合并为2.6万余个人民公社，入社农户占总农户99%以上，公共食堂普遍兴办并实行吃饭不要钱。",impact:"公社以社为单位统一核算与分配，助长“一平二调”的共产风；1981年历史决议指出这一“大跃进”和人民公社化运动“使得‘左’倾错误严重地泛滥开来”。1961年《农业六十条》改以生产队为基本核算单位。",figures:["毛泽东","谭震林","吴芝圃"],place:"河北北戴河；全国农村",state:"中华人民共和国",sources:["《中共中央关于在农村建立人民公社问题的决议》（1958年8月29日）、《建国以来重要文献选编》第11册"],"tags":["人民公社","北戴河会议","共产风"]},related:["cn--1955--p04", "cn--1958--e01", "cn--1961--i01"]},
  {id:"cn--1958--p03",track:"cn",year:1958,yearApprox:false,dim:"politics",weight:3,title:"南宁会议批评反冒进",summary:"1月11日至22日中央工作会议，反冒进被指“促退”。",detail:{background:"1956年11月八届二中全会后形成的反冒进方针，被毛泽东认为“使六亿人民泄了气”。",process:"1958年1月11日至22日中共中央在南宁召开工作会议，毛泽东在会上多次批评1956年以来的反冒进，周恩来、陈云作检讨；会议提出以后经济工作以“鼓足干劲”为宣传方针，并布置为总路线作系统说明。2月《人民日报》社论把反冒进称为“促退”。",impact:"党内以综合平衡约束高指标的纠错机制被削弱，八届二中全会确立的方针公开否定；5个月后北戴河会议即通过1070万吨钢指标与公社化决议。",figures:["毛泽东","周恩来","陈云","薄一波"],place:"广西南宁",state:"中华人民共和国",sources:["毛泽东在南宁会议上的讲话（1958年1月）、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["南宁会议","反冒进","高指标"]},related:["cn--1956--e02", "cn--1958--p01"]},
  {id:"cn--1958--e01",track:"cn",year:1958,yearApprox:false,dim:"economy",weight:4,title:"全民大炼钢铁运动",summary:"9月起土法炼钢，年底宣布完成1070万吨钢指标。",detail:{background:"北戴河会议确定1958年钢产量1070万吨，而当年6月底全国仅产钢370万吨，缺口被要求以群众运动弥补。",process:"1958年9月起各地兴建小高炉、土转炉，据中央统战部与国家经委的汇报材料，参加炼钢与采矿的人员最多时达数千万人；12月19日宣布完成1070万吨指标，其中土钢、土铁占相当比重。当年机械、铁路与商业因劳动力外流而受阻。",impact:"大量劳动力离开秋收，林木与煤炭被过度调用，1958年粮食丰产而未及归仓；浮夸的统计数字使中央对农业与工业形势的判断失真，是此后困难时期的重要成因。",figures:["毛泽东","薄一波","李富春","彭德怀"],place:"全国（重点为河北、河南、四川、湖北、山西）",state:"中华人民共和国",sources:["国家统计局《关于1958年国民经济计划执行结果的公报》（1959年）、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["大跃进","大炼钢铁","浮夸风"]},related:["cn--1958--p01", "cn--1958--p02", "cn--1959--e01"]},
  {id:"cn--1958--m01",track:"cn",year:1958,yearApprox:false,dim:"military",weight:3,title:"炮击金门",summary:"8月23日福建前线大规模炮击，10月起形成打打停停格局。",detail:{background:"1958年7月美军在黎巴嫩登陆、加强在台湾海峡的军事存在；台湾当局在金门、马祖驻有重兵并不断骚扰闽南沿海。",process:"8月23日人民解放军福建前线部队对金门实施突然大规模炮击，金门守军三名中将副司令在炮击中死亡；10月6日由国防部长彭德怀发布、毛泽东起草的《告台湾同胞书》宣布暂停炮击7天，10月25日确定“双日不打、单日打”的打打停停办法。",impact:"形成军事对峙与政治喊话并用的金马格局，美国关于1954年《中美共同防御条约》适用范围的表态成为中美大使级会谈中的持续议题；这一格局客观上保留了金马作为两岸联系纽带的地位。",figures:["毛泽东","彭德怀","叶飞"],place:"福建厦门、金门海域",state:"中华人民共和国",sources:["中华人民共和国国防部《告台湾同胞书》（1958年10月6日）、《彭德怀军事文选》"],"tags":["金门","台海","炮战"]},related:["cn--1954--p04", "cn--1955--i01"]},
  {id:"cn--1959--p01",track:"cn",year:1959,yearApprox:false,dim:"politics",weight:3,title:"庐山会议前期与彭德怀信",summary:"7月2日至8月1日政治局扩大会议，7月14日彭德怀上书。",detail:{background:"1958年冬起中央已在纠左，1959年2月郑州会议、7月初庐山会议初期仍以总结“大跃进”教训、压缩空气为主题。",process:"1959年7月2日至8月1日中央政治局扩大会议在庐山召开，会议前期分组讨论经济工作与公社体制问题；7月14日彭德怀给毛泽东写信，谈到“小资产阶级的狂热性”与比例失调等问题；7月15日毛泽东将该信加注“彭德怀同志的意见书”后印发会议讨论，7月23日毛泽东在会上讲话，把信中的意见定性为右倾机会主义进攻。",impact:"会议主题由纠左转为反右，1958年11月郑州会议以来延续约一年的纠左进程被打断；1981年历史决议明确“庐山会议后期，毛泽东同志错误地发动了对彭德怀同志的批判”。",figures:["毛泽东","彭德怀","张闻天","黄克诚"],place:"江西庐山",state:"中华人民共和国",sources:["彭德怀给毛泽东的信（1959年7月14日）、《关于建国以来党的若干历史问题的决议》（1981年6月）"],"tags":["庐山会议","彭德怀","纠左中断"]},related:["cn--1959--p02", "cn--1958--p02", "cn--1961--p01"]},
  {id:"cn--1959--p02",track:"cn",year:1959,yearApprox:false,dim:"politics",weight:4,title:"八届八中全会与“反右倾”斗争",summary:"8月2日至16日全会通过反右倾决议，运动延伸至全党。",detail:{background:"7月23日讲话后会议转入对彭德怀、黄克诚、张闻天、周小舟的批判，会期由政治局扩大会议延续为中央全会。",process:"1959年8月2日至16日中共八届八中全会在庐山召开，通过《为保卫党的总路线、反对右倾机会主义而斗争》的决议与《关于以彭德怀同志为首的反党集团的决议》；会后在全国各级党政机关开展“反右倾”斗争，一批干部被重点批判和组织处理。1978年12月中共十一届三中全会后，中共中央为彭德怀、黄克诚、张闻天、周小舟等人平反、恢复名誉。",impact:"据1981年历史决议，八届八中全会关于所谓“彭德怀、黄克诚、张闻天、周小舟反党集团”的决议“是完全错误的”，这场斗争“在政治上使党内从中央到基层的民主生活遭到严重损害，在经济上打断了纠正极‘左’错误的进程”；1959、1960年的高征购与高指标因此得以延续，直接加重了农村困难。",figures:["毛泽东","彭德怀","林彪","黄克诚","张闻天"],place:"江西庐山",state:"中华人民共和国",sources:["《中国共产党第八届中央委员会第八次全体会议公报》（1959年8月16日）、《关于建国以来党的若干历史问题的决议》（1981年6月）"],"tags":["反右倾","八届八中全会","平反"]},related:["cn--1959--p01", "cn--1962--p01", "cn--1959--e01"]},
  {id:"cn--1959--e01",track:"cn",year:1959,yearApprox:false,dim:"economy",weight:3,title:"高征购与农村粮食紧张",summary:"征购率升至统购统销以来高点，粮食产量连续两年下降。",detail:{background:"1958年夏秋中央一度估计当年粮食产量达5000亿斤，1959年度征购与出口指标在此估计基础上确定。",process:"据国家统计局后来公布的修正序列，全国粮食产量由1958年的4000亿斤降至1959年的3400亿斤、1960年的2870亿斤；农业部门统计显示1959年度粮食征购量与征购率为统购统销实行以来的高点，农村口粮普遍减少。1960年6月中央发出关于粮食问题的指示，8月起多地报告春荒与水肿病发生情况。",impact:"高征购与口粮不足并存使农村劳动力受损，成为此后两年人口变动的直接经济背景；1961年1月中央决定调减粮食征购、提高收购价格并进口部分粮食。",figures:["毛泽东","李先念","谭震林","陈云"],place:"全国农村（河南、山东、四川、甘肃、安徽为重灾区）",state:"中华人民共和国",sources:["国家统计局编《新中国五十五年统计资料汇编》、《建国以来毛泽东文稿》第9册"],"tags":["粮食征购","统购统销","农村困难"]},related:["cn--1955--e01", "cn--1961--d01", "cn--1959--p02"]},
  {id:"cn--1959--m01",track:"cn",year:1959,yearApprox:false,dim:"military",weight:3,title:"西藏局势与国务院解散西藏地方政府",summary:"3月拉萨发生武装叛乱，28日国务院下令由筹委会行使职权。",detail:{background:"1955年起康区等地出现武装冲突，1959年2月雪董会议后拉萨局势急剧紧张；西藏地方政府中的部分官员与叛乱武装会合。",process:"1959年3月10日拉萨发生武装叛乱，叛乱分子包围西藏军区机关；3月17日达赖喇嘛等离开拉萨，3月22日驻藏部队对拉萨市区叛乱武装发起反击；3月28日国务院发布命令，宣布解散西藏地方政府、由西藏自治区筹备委员会行使西藏地方政府职权，并在西藏开展废除政教合一封建农奴制的民主改革。据《西藏民主改革50年》白皮书记载，平叛作战延续至1960年代初。",impact:"西藏延续数百年的政教合一地方政权形态结束，1965年9月西藏自治区正式成立；达赖此后长期在国外活动，中央政府指称其以分裂国家为目标。",figures:["毛泽东","张国华","阿沛·阿旺晋美"],place:"西藏拉萨、山南",state:"中华人民共和国",sources:["《中华人民共和国国务院命令》（1959年3月28日）、《西藏民主改革50年》白皮书（国务院新闻办公室，2013年）"],"tags":["西藏","平叛","民主改革"]},related:["cn--1951--p01", "cn--1965--p02"]},
  {id:"cn--1960--p01",track:"cn",year:1960,yearApprox:false,dim:"politics",weight:4,title:"苏联召回在华专家、废止合同",summary:"7月16日苏方照会单方撤专家，8月1日起中止数百个协议。",detail:{background:"1958年夏以来中苏在长波电台与联合舰队、对台与对美政策、和平共处问题上分歧加深；1960年6月布加勒斯特会议上苏共对中共代表团提出指责。",process:"1960年7月16日苏联政府照会中国政府，决定撤换全部在华苏联专家并中止部分经济与科技合同；至9月1日共有1390名专家被召回，中止的专家项目与合同涉及600余个单位。8月22日中国政府复照说明立场，同时邀请苏方派专家来华未获回应。",impact:"在建重点工程、国防科研与高校教学一度受阻，中央决定改用自力更生的办法继续推进原子弹与运载技术研制，1960年冬成立国防科委系统抓总机制；两国论战自1960年11月莫斯科会议后走向公开化。",figures:["赫鲁晓夫","周恩来","聂荣臻","李富春"],place:"北京、莫斯科；全国援华项目单位",state:"中华人民共和国",sources:["中华人民共和国政府关于苏联政府1960年7月16日照会的复照（1960年8月）、《聂荣臻回忆录》"],"tags":["中苏论战","撤专家","自主研制"]},related:["cn--1963--p02", "cn--1964--s01", "cn--1969--m01", "world--1963--c01"]},
  {id:"cn--1960--x01",track:"cn",year:1960,yearApprox:false,dim:"explore",weight:3,title:"首次从北坡登顶珠穆朗玛峰",summary:"5月25日凌晨王富洲、贡布、屈银华登顶。",detail:{background:"1955年起中国开始组织珠峰登山准备，1958年打通绒布寺以北的物资运输线；同年在珠峰工作的苏联登山队因两国关系变化撤回。",process:"1960年3月至5月中国登山队对北坡东北山脊路线实施突击，1960年5月25日凌晨4时20分王富洲、贡布（藏族）、屈银华三人从北坡登顶，将中华人民共和国国旗与毛泽东塑像留在峰顶；突击过程中刘连满以肩托举同伴通过“第二台阶”岩壁。",impact:"完成人类首次从北坡登顶珠穆朗玛峰，被国际登山界视为高海拔攀登的艰难路线纪录；1961年中尼签订边界条约将珠峰定为界峰，1975年中国测绘队再登该峰并测得8848.13米岩面高程。",figures:["王富洲","贡布","屈银华","刘连满","史占春"],place:"西藏定日珠穆朗玛峰北坡",state:"中华人民共和国",sources:["新华社1960年5月25日北京电、《中国登山运动史》（体育文史资料）"],"tags":["珠峰","登山","北坡"]},related:["cn--1960--p01"]},
  {id:"cn--1960--i01",track:"cn",year:1960,yearApprox:false,dim:"institution",weight:3,title:"《紧急指示信》（“十二条”）发出",summary:"11月3日中央发出农村人民公社政策紧急指示信。",detail:{background:"1959年冬到1960年春多地报告农村缺粮与“一平二调”问题，河南、山东、甘肃等省委的材料被中央转发。",process:"1960年11月3日中共中央发出《关于农村人民公社当前政策问题的紧急指示信》，由周恩来主持起草、毛泽东审定，共12条：重申以生产队为基础的三级所有制至少30年不变，彻底清理并退还一平二调的财物，允许社员经营少量自留地与家庭副业，恢复农村集市贸易，整风整社。",impact:"这是1958年后第一份系统性纠左的中央文件，为1961年《农业六十条》与八字方针提供了政策起点；但粮食征购基数未立即下降，农村困难的缓解延续到1961年。",figures:["毛泽东","周恩来","李先念"],place:"北京；全国农村",state:"中华人民共和国",sources:["《中共中央关于农村人民公社当前政策问题的紧急指示信》（1960年11月3日）、《建国以来重要文献选编》第13册"],"tags":["紧急指示信","十二条","纠左"]},related:["cn--1960--p01", "cn--1961--i01"]},
  {id:"cn--1960--e01",track:"cn",year:1960,yearApprox:false,dim:"economy",weight:3,title:"大庆石油会战",summary:"2月中央批准会战，1963年宣布石油消费基本自给。",detail:{background:"1959年9月26日松基三井喷出工业油流，松辽盆地发现大油田；当时全国原油年产量三百余万吨，进口成品油占消费近半。",process:"1960年2月中共中央批准石油工业部在松辽地区组织石油会战，从全军转业官兵与全国各油田调集3万余人、4000余台（套）设备；会战按“先集中勘探、再集中建设产能”的程序展开，1960年6月1日正式打响，王进喜率钻井队在缺少起重设备的条件下以人拉肩扛卸载并安装钻机。",impact:"据《当代中国的石油工业》记载，全国原油产量1963年达648万吨，周恩来在1963年12月第三届全国人民代表大会第一次会议的政府工作报告中宣布我国石油消费基本自给，1965年起实现全部自给；会战形成的岗位责任制与“三老四严”成为工业企业管理的样板。",figures:["余秋里","康世恩","王进喜","李四光"],place:"黑龙江大庆（松辽盆地）",state:"中华人民共和国",sources:["《当代中国的石油工业》（中国社会科学出版社）、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["石油会战","大庆","基本自给"]},related:["cn--1960--p01", "cn--1964--e01"]},
  {id:"cn--1961--p01",track:"cn",year:1961,yearApprox:false,dim:"politics",weight:4,title:"“调整、巩固、充实、提高”八字方针",summary:"1月14日至18日八届九中全会正式通过调整方针。",detail:{background:"1960年8月李富春在国家计委汇报中提出“调整、巩固、提高”，周恩来在起草文件时增加“充实”二字；1960年冬经济全面紧张。",process:"1961年1月14日至18日中共八届九中全会在北京召开，听取并讨论李富春关于1960年计划执行情况和1961年计划安排的意见，正式通过“调整、巩固、充实、提高”的方针；会议决定把农业放在首要位置，压缩基建规模与工业指标，并原则同意以三年左右时间作为调整期。",impact:"八字方针是建国后第一次在全国计划层面系统纠正“左”的错误；据国家统计局数据，全国钢产量由1960年的1866万吨降至1961年的870万吨、1962年的748万吨，农业与市场的恢复自1962年起出现。",figures:["毛泽东","刘少奇","周恩来","邓小平","陈云","李富春"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第八届中央委员会第九次全体会议公报》（1961年1月18日）、《周恩来年谱（1949—1976）》下卷"],"tags":["八字方针","调整期","八届九中全会"]},related:["cn--1961--i01", "cn--1958--p01", "cn--1962--p01"]},
  {id:"cn--1961--i01",track:"cn",year:1961,yearApprox:false,dim:"institution",weight:3,title:"《农业六十条》起草与修改",summary:"3月广州会议成草案，年内两次修正并取消供给制与公共食堂。",detail:{background:"1961年1月毛泽东在中央工作会议上号召“大兴调查研究之风”，3月率田家英等到广东调查；湖南、浙江的调查材料直接提出公共食堂问题。",process:"1961年3月15日至23日广州中央工作会议起草并通过《农村人民公社工作条例（草案）》，共60条；5月北京会议、6月杭州会议先后通过修正草案与修正案，取消对社员的部分供给制，明确办不办公共食堂由社员讨论决定。同年10月7日中央发出指示，把人民公社的基本核算单位下放到生产队。",impact:"该条例以法规形式界定公社、大队、生产队三级权责，是1961至1965年农业恢复最重要的制度条件；1962年9月八届十中全会通过《农村人民公社工作条例修正草案》，使“三级所有、队为基础”长期稳定。",figures:["毛泽东","田家英","陈正人","胡乔木"],place:"广州、北京、杭州",state:"中华人民共和国",sources:["《农村人民公社工作条例（草案）》（1961年3月22日印发）、《建国以来重要文献选编》第14册"],"tags":["六十条","三级所有","调查研究"]},related:["cn--1960--i01", "cn--1962--e01"]},
  {id:"cn--1961--d01",track:"cn",year:1961,yearApprox:false,dim:"disaster",weight:5,title:"严重经济困难与人口变动",summary:"1961年粮食产量降至2950亿斤，年末总人口比上年减少约350万。",detail:{background:"1959至1961年农业生产连续下降，叠加高征购、自然灾害与苏联废止合同等因素，全国普遍出现粮食短缺。",process:"据国家统计局公布的修正序列，全国粮食总产量由1958年的4000亿斤降至1959年的3400亿斤、1960年的2870亿斤、1961年的2950亿斤；全国人口出生率由1957年的34.03‰降至1961年的12.04‰，死亡率由1957年的10.80‰升至1961年的14.20‰，1961年末总人口比1960年末减少约350万人。学界对这一时期非正常减少人口的规模与成因有不同估计，官方公开口径为上述年度出生与死亡率序列。",impact:"中央被迫全面调整：1961年调减征购、提高农产品收购价格、进口粮食并精简城镇人口；1962年1月毛泽东在扩大的中央工作会议上就工作中的错误作自我批评，强调发扬民主。",figures:["毛泽东","刘少奇","周恩来","陈云"],place:"全国（河南、山东、四川、甘肃、安徽等地为重）",state:"中华人民共和国",sources:["国家统计局编《中国统计年鉴（1983）》人口与农业序列、《关于建国以来党的若干历史问题的决议》（1981年6月）"],"tags":["经济困难","人口变动","统计口径"]},related:["cn--1959--e01", "cn--1961--p01", "cn--1962--p01"]},
  {id:"cn--1961--e01",track:"cn",year:1961,yearApprox:false,dim:"economy",weight:2,title:"精减职工与压缩城镇人口",summary:"1961至1963年减少职工约1887万人、城镇人口约2600万人。",detail:{background:"1958至1960年全民所有制单位职工人数由3100余万增至5000万以上，城镇粮食销量成倍增加，财政负担加重。",process:"1961年5月中央工作会议作出减少城镇人口、精减职工的决定，随后由各省按“先从1958年后从农村招入人员中精减”的顺序推行，并对回乡人员安排口粮与安置补助。据国家统计局劳动统计序列，1961年至1963年6月全国共精减职工约1887万人、减少城镇人口约2600万人。",impact:"1963年7月中央宣布精减任务基本完成。这是建国后唯一一次大规模城镇化逆转，直接减轻了粮食与财政压力，也为1963至1965年经济恢复创造了条件。",figures:["周恩来","李富春","李先念","薄一波"],place:"全国（重点为京津沪与东北工业城市）",state:"中华人民共和国",sources:["《周恩来年谱（1949—1976）》下卷、国家统计局编《中国劳动统计年鉴》"],"tags":["精减职工","城镇人口","调整"]},related:["cn--1961--p01", "cn--1961--d01"]},
  {id:"cn--1962--p01",track:"cn",year:1962,yearApprox:false,dim:"politics",weight:4,title:"七千人大会",summary:"1月11日至2月7日五级干部会议，毛泽东在会上作自我批评。",detail:{background:"1961年经济继续下滑，中央认为需要统一全党对困难原因与责任的认识；此前邓小平主持起草了会议报告稿。",process:"1962年1月11日至2月7日中共中央召开扩大的中央工作会议，出席者包括中央、中央局、省、地、县五级党委负责干部共7118人，史称“七千人大会”；1月27日刘少奇代表中央作报告，会上分组讨论并对工作中的缺点错误提出批评，1月30日毛泽东在讲话中就中央工作的错误作自我批评并强调民主集中制，2月邓小平、周恩来分别发言。",impact:"会议在一定程度上恢复党内民主氛围，推动了对“反右倾”案件中被错批干部的甄别平反，并确认了调整方针；但1962年9月八届十中全会重提阶级斗争后，这一纠左取向被中断。",figures:["毛泽东","刘少奇","周恩来","邓小平","陈云"],place:"北京",state:"中华人民共和国",sources:["刘少奇《在扩大的中央工作会议上的报告》（1962年1月27日）、《建国以来重要文献选编》第15册"],"tags":["七千人大会","民主集中制","甄别平反"]},related:["cn--1959--p02", "cn--1961--d01", "cn--1962--p02"]},
  {id:"cn--1962--p02",track:"cn",year:1962,yearApprox:false,dim:"politics",weight:4,title:"八届十中全会重提阶级斗争",summary:"9月24日至27日全会，把阶级斗争问题扩大化、绝对化。",detail:{background:"1962年上半年中央内部就形势判断、包产到户与甄别平反等问题存在不同意见；8月北戴河中央工作会议已先行讨论阶级、矛盾问题。",process:"1962年9月24日至27日中共八届十中全会在北京召开，毛泽东作关于阶级、形势、矛盾的讲话，提出在由资本主义向共产主义过渡的整个历史时期都存在阶级和阶级斗争；会议把“黑暗风”“单干风”“翻案风”列为批判对象，通过《农村人民公社工作条例修正草案》与《关于进一步巩固人民公社集体经济、发展农业生产的决定》。",impact:"这一论断此后被概括为“以阶级斗争为纲”，成为1963年起的社会主义教育运动与1966年“文化大革命”的思想和政策准备；对包产到户的政策讨论同时被中止。",figures:["毛泽东","刘少奇","邓小平","康生","陈伯达"],place:"北京（前期会议在北戴河）",state:"中华人民共和国",sources:["《中国共产党第八届中央委员会第十次全体会议公报》（1962年9月27日）、《关于建国以来党的若干历史问题的决议》（1981年6月）"],"tags":["八届十中全会","阶级斗争","单干风"]},related:["cn--1962--e01", "cn--1963--p01", "cn--1966--p01"]},
  {id:"cn--1962--m01",track:"cn",year:1962,yearApprox:false,dim:"military",weight:3,title:"中印边境自卫反击战",summary:"10月20日至11月21日东段西段作战，随后主动停火后撤。",detail:{background:"1951年后印度军队逐步向麦克马洪线以北推进，1959年朗久、空喀山口发生武装冲突；1962年6月起印方推行“前进政策”，在中印边界西段建立数十个据点。",process:"1962年10月20日中国边防部队在东段（克节朗、达旺方向）与西段（阿克赛钦）实施反击，23日进至达旺；11月18日至20日进行第二阶段作战。11月21日中国政府发表声明宣布全线停火，停火自11月22日零时起生效，并自12月1日起主动后撤至1959年11月7日实际控制线中方一侧，随后归还缴获的武器装备、释放并遣返被俘人员。",impact:"作战结束了西段据点对峙态势，此后边境长期保持相对平静；中印关系进入低谷，边界问题由1981年起的副外长级会谈与2003年后的边界问题特别代表会晤机制处理。",figures:["毛泽东","周恩来","刘伯承","张国华"],place:"中印边界东段与西段",state:"中华人民共和国",sources:["中华人民共和国政府声明（1962年11月21日）、《中华人民共和国对外关系文件集》第9集（世界知识出版社）"],"tags":["中印边境","反击战","停火后撤"]},related:["cn--1962--p02", "cn--1969--m01"]},
  {id:"cn--1962--e01",track:"cn",year:1962,yearApprox:false,dim:"economy",weight:3,title:"安徽“责任田”与包产到户争论",summary:"1961年安徽试行责任田，1962年被作为“单干风”批评。",detail:{background:"1960年秋安徽部分地区因缺粮自发实行“借地种麦”，1961年2月省委决定试行包产到田、责任到人的“责任田”办法。",process:"据曾希圣向华东局和中央的报告，1961年7月全省实行责任田的生产队已占总数85.4%；1962年2月中央高层就包产到户交换意见，5月中央农村工作部负责人邓子恢向中央和毛泽东汇报，主张允许群众选择包产到户，浙江省委农村工作部钱让能亦上书为包产到户申说。8月北戴河会议后上述意见被批评为“单干风”。",impact:"包产到户的政策试验在1962年冬被明令纠正，此后长期作为政治错误保留在档案中；1978年11月安徽凤阳小岗村的包干契约重新开启同一政策路径。",figures:["曾希圣","邓子恢","钱让能","毛泽东"],place:"安徽、浙江、广西、甘肃",state:"中华人民共和国",sources:["《曾希圣关于实行“责任田”的报告》（1961年）、《建国以来重要文献选编》第15册"],"tags":["责任田","包产到户","单干风"]},related:["cn--1962--p02", "cn--1961--i01", "cn--1978--e01"]},
  {id:"cn--1962--s01",track:"cn",year:1962,yearApprox:false,dim:"science",weight:3,title:"第一台12000吨自由锻造水压机制成",summary:"6月上海建成，解决大型锻件依赖进口的瓶颈。",detail:{background:"“二五”计划把大吨位自由锻造水压机列为急需重大装备，此前大型电站转子、船用曲轴等锻件依赖进口，制约造船、电力与军工。",process:"1958年上海决定自行设计制造大吨位自由锻造水压机，由江南造船厂承担主体制造，第一机械工业部组织技术攻关，采用铸焊结合结构并按分段制造、整体装配的办法解决大型部件的加工与运输问题；1962年6月设备建成并投入试锻生产，公称压力12000吨，可锻大型钢锭。",impact:"使我国获得大型锻件的自主生产能力，其铸焊结合结构与分段制造、整体装配的工艺为此后各系列大吨位压机提供了技术基础。据《当代中国的机械工业》记载，该设备建成后长期承担电站、船舶与军工部门的大型锻件任务，我国由此不再依赖进口大锻件。",figures:["沈鸿","江南造船厂"],place:"上海江南造船厂",state:"中华人民共和国",sources:["《当代中国的机械工业》（当代中国出版社）、《上海机械工业志》"],"tags":["水压机","重型装备","锻造"]},related:["cn--1956--s02", "cn--1964--e01"]},
  {id:"cn--1963--p01",track:"cn",year:1963,yearApprox:false,dim:"politics",weight:3,title:"“前十条”与社会主义教育运动",summary:"5月20日中央通过农村社教决定草案，运动在部分基层展开。",detail:{background:"1962年9月八届十中全会后，浙江诸暨等地“干部参加劳动、矛盾不上交”的枫桥经验与清账理财做法被中央转发。",process:"1963年2月中央工作会议作出在城市开展反对贪污盗窃、反对投机倒把、反对铺张浪费、反对分散主义、反对官僚主义的部署；5月2日至12日杭州会议制定《关于目前农村工作中若干问题的决定（草案）》，共10个问题，称“前十条”，9月又制定《关于农村社会主义教育运动中一些具体政策的规定（草案）》，称“后十条”。运动随后在全国部分农村和少数城市基层展开。",impact:"社教运动在整顿干部作风与集体财务管理的同时，把大量人民内部矛盾作为阶级斗争处理；1965年1月《二十三条》提出运动重点是“整党内那些走资本主义道路的当权派”。",figures:["毛泽东","刘少奇","彭真","陶铸"],place:"北京、杭州；全国试点县",state:"中华人民共和国",sources:["《中共中央关于目前农村工作中若干问题的决定（草案）》（1963年5月20日）、《建国以来重要文献选编》第16册"],"tags":["社教运动","前十条","四清"]},related:["cn--1962--p02", "cn--1965--p01"]},
  {id:"cn--1963--p02",track:"cn",year:1963,yearApprox:false,dim:"politics",weight:3,title:"中央致苏共中央的“六一四复信”",summary:"6月14日发表《关于国际共产主义运动总路线的建议》。",detail:{background:"1963年3月30日苏共中央来信，就举行两党会谈与停止公开论战提出建议；1963年4月中共中央复信作出回应，双方在时代性质与总路线问题上分歧未解。",process:"1963年6月14日中共中央发出《关于国际共产主义运动总路线的建议》（对苏共3月30日来信的复信），共25个问题，就时代性质、战争与和平、国家与政党属性等问题陈述立场，批评苏共纲领中“全民国家”“全民党”等提法；自9月6日起《人民日报》《红旗》杂志陆续发表评苏共中央公开信的文章，至1964年7月共九篇。",impact:"复信发表后的1963年7月14日，苏共发表致苏联全体组织和全体党员的公开信，公开论战由此扩大；1963年7月邓小平率团赴莫斯科会谈无果，两党1964年11月在莫斯科再商破裂；学界一般以1963至1964年的公开信论战作为中苏分裂形成的标志。",figures:["毛泽东","刘少奇","邓小平","彭真"],place:"北京；莫斯科",state:"中华人民共和国",sources:["《关于国际共产主义运动总路线的建议》（1963年6月14日）、《人民日报》1963年6月17日"],"tags":["中苏论战","公开信","总路线"]},related:["cn--1960--p01", "cn--1969--p01"]},
  {id:"cn--1963--f01",track:"cn",year:1963,yearApprox:false,dim:"figure",weight:3,title:"“向雷锋同志学习”题词发表",summary:"3月5日《人民日报》刊发毛泽东题词，此后开展学雷锋活动。",detail:{background:"雷锋1960年参加中国人民解放军，1962年8月15日在辽宁抚顺执行任务时因公牺牲；其日记与事迹先在部队与沈阳地区传播。",process:"1963年3月5日《人民日报》发表毛泽东“向雷锋同志学习”题词，刘少奇、周恩来、朱德、邓小平等领导人的题词同时刊登；《中国青年》刊出毛泽东题词版本，团中央与各地党组织随即部署学习雷锋的宣传教育活动。",impact:"学雷锋活动成为此后群众性思想道德建设的固定载体，虽经1966至1976年政治动荡与1990年后志愿服务制度化，其年度化形式一直延续至今。",figures:["雷锋","毛泽东","周恩来","邓小平"],place:"北京；辽宁抚顺",state:"中华人民共和国",sources:["《人民日报》1963年3月5日、《毛泽东邓小平江泽民胡锦涛关于学雷锋的论述摘编》"],"tags":["学雷锋","典型宣传","道德建设"]},related:["cn--1952--f01", "cn--1963--p01"]},
  {id:"cn--1963--i01",track:"cn",year:1963,yearApprox:false,dim:"institution",weight:3,title:"中央决定试办托拉斯（工业公司）",summary:"1963年起按行业组建全国性公司，以经济办法管理工业。",detail:{background:"1961年《工业七十条》已确立党委领导下的厂长负责制，但政企不分、多头管理导致的效率问题仍在；刘少奇多次提出用经济办法管理工业。",process:"1963年10月起中央、国务院决定在工业和交通部门试办托拉斯，先期成立中国盐业公司等专业公司；1964年国务院批转国家经委《关于试办工业、交通托拉斯的意见（草案）》，先后成立或筹办石油、化学工业、有色金属、机械设备、纺织等12个全国性或区域性公司，实行统一计划、统一技术、统一调配。",impact:"这是建国后第一次以专业化公司替代行政管理局的尝试，1965年试办公司的利税与劳动生产率明显上升；“文化大革命”开始后该办法被作为“修正主义企业管理路线”批判并于1967年后中断。",figures:["刘少奇","周恩来","李富春","薄一波"],place:"北京；天津、上海、辽宁",state:"中华人民共和国",sources:["《关于试办工业、交通托拉斯的意见（草案）》（1964年）、《当代中国的经济体制改革》（当代中国出版社）"],"tags":["托拉斯","工业管理","专业化改组"]},related:["cn--1961--p01", "cn--1964--e01"]},
  {id:"cn--1964--s01",track:"cn",year:1964,yearApprox:false,dim:"science",weight:5,title:"第一颗原子弹爆炸成功",summary:"10月16日罗布泊试验成功，中国政府同时承诺不首先使用核武器。",detail:{background:"1955年1月中央作出发展原子能事业的决策，1958年建成反应堆与回旋加速器；1959年6月苏方拒绝提供原子弹教学模型与图纸资料，1962年11月成立以周恩来为主任的中央十五人专门委员会抓总研制。",process:"1964年10月16日15时，中国第一颗原子弹在新疆罗布泊核试验场塔架爆破成功，据《当代中国的国防科技事业》记载其当量约2.2万吨梯恩梯当量；张爱萍、刘西尧在试验现场主持。10月16日中国政府发表声明，宣布中国在任何时候、任何情况下都不首先使用核武器，并呼吁召开世界各国政府首脑会议讨论全面禁止和彻底销毁核武器。",impact:"中国成为继美、苏、英、法之后第五个拥有核武器的国家；不首先使用核武器的承诺此后成为中国核政策的固定公开表述，1996年中国签署《全面禁止核试验条约》。1965年5月14日中国成功进行首次原子弹空爆试验。",figures:["毛泽东","周恩来","聂荣臻","张爱萍","钱三强","邓稼先"],place:"新疆罗布泊核试验基地",state:"中华人民共和国",sources:["《中华人民共和国政府声明》（1964年10月16日）、《当代中国的国防科技事业》（当代中国出版社）"],"tags":["原子弹","核试验","不首先使用"]},related:["cn--1956--s02", "cn--1967--s01", "cn--1960--p01", "world--1964--s01"]},
  {id:"cn--1964--p02",track:"cn",year:1964,yearApprox:false,dim:"politics",weight:4,title:"中法建交",summary:"1月27日两国互认并建交，法国成为西方大国中第一个。",detail:{background:"1955年起中法通过瑞士领事渠道保持接触；1963年5月法国前总理富尔访华，与周恩来、陈毅会谈，双方在台湾代表权问题上反复磋商后形成法国与台湾当局“默契断交”的方案。",process:"1964年1月27日中法两国政府发表联合公报，宣布两国互相承认并建立外交关系，并决定在三个月内互派大使；公报同时就台湾问题作出说明，中方指出中华人民共和国政府是唯一合法政府，戴高乐政府承认这一立场。",impact:"建交使中华人民共和国首次与西方主要大国建立正式外交关系，法国在越南战争等问题上采取独立于美国的立场；年内双方互派首任大使，这一做法也推动部分西欧国家重新评估对华政策。",figures:["毛泽东","周恩来","戴高乐","陈毅"],place:"北京、巴黎",state:"中华人民共和国",sources:["《中法建交联合公报》（1964年1月27日）、《中华人民共和国外交史》第二卷（1957—1969）"],"tags":["中法建交","戴高乐","西方大国"]},related:["cn--1956--p03", "cn--1954--p03", "world--1964--p03"]},
  {id:"cn--1964--p03",track:"cn",year:1964,yearApprox:false,dim:"politics",weight:4,title:"三届全国人大一次会议与“两步走”设想",summary:"12月21日至1965年1月4日，首次完整提出四个现代化。",detail:{background:"调整时期经济恢复，中央考虑从第三个五年计划起重新规划长远建设目标。",process:"1964年12月21日至1965年1月4日第三届全国人民代表大会第一次会议在北京召开，出席代表3085人；周恩来在《政府工作报告》中首次完整提出“把我国建设成为一个具有现代农业、现代工业、国防和科学技术的社会主义强国”的目标，并提出两步走设想：1980年前建成独立的比较完整的工业体系和国民经济体系，20世纪内全面实现四个现代化。会议选举朱德为全国人大常委会委员长，决定周恩来为国务院总理。",impact:"四个现代化自此成为国家发展战略的正式表述，1975年四届全国人大一次会议予以重申，1979年后被“中国式的现代化”与小康目标具体化。",figures:["周恩来","朱德","董必武","李先念"],place:"北京人民大会堂",state:"中华人民共和国",sources:["周恩来《政府工作报告》（1964年12月21日）、《第三届全国人民代表大会第一次会议文件》"],"tags":["四个现代化","两步走","人大"]},related:["cn--1960--e01", "cn--1975--p01"]},
  {id:"cn--1964--e01",track:"cn",year:1964,yearApprox:false,dim:"economy",weight:4,title:"三线建设决策",summary:"1964年中央确定在西南西北腹地大规模布局工业与国防项目。",detail:{background:"1964年北部沿边与东南沿海安全形势趋紧，工业布局过度集中于沿海与东北；1964年春中央书记处会议听取关于后方工业基地建设的汇报，毛泽东在政治局会议上强调三线建设要从战争危险考虑。",process:"1964年5月至6月中央工作会议确定三线建设方针，8月中央作出集中力量加快三线建设的决定，随后建立三线建设的领导机构，国家计委与国务院工交部门把设计、施工与设备调配力量向内地转移；1964年至1965年国家基本建设投资向三线倾斜，安排成昆铁路、攀枝花钢铁基地、贵州六盘水煤矿、第二汽车制造厂与酒泉、西昌等国防科研项目。",impact:"三线建设持续三个五年计划，据《中国共产党的九十年》记载，1965至1975年国家在三线地区投入基本建设投资1290余亿元，形成川渝、黔滇、陕甘宁等工业基地；同时也因布点分散、配套不足留下长期调整问题。",figures:["毛泽东","周恩来","李富春","薄一波"],place:"四川、贵州、云南、陕西、甘肃等三线地区",state:"中华人民共和国",sources:["《建国以来毛泽东文稿》第11册、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["三线建设","工业布局","备战"]},related:["cn--1970--s02", "cn--1969--m01"]},
  {id:"cn--1965--p01",track:"cn",year:1965,yearApprox:false,dim:"politics",weight:3,title:"社教运动“二十三条”",summary:"1965年1月中央下发文件，提出运动重点是整“走资派”。",detail:{background:"1963年“前十条”与“后十条”执行中，各地反映“左”的偏向与基层干部人人过关问题；1964年底中央工作会议讨论修订政策。",process:"1965年1月中共中央制定并下发《农村社会主义教育运动中目前提出的一些问题》，共23条，统称“二十三条”；文件把城市与农村的社教运动统一称“四清”（清政治、清经济、清思想、清组织），并在第一条中提出运动的重点是“整党内那些走资本主义道路的当权派”。",impact:"“走资派”概念由这一文件首次进入中央文件，1966年5月《五一六通知》以此为依据展开；据1981年历史决议，社教运动中的许多问题被作为阶级斗争处理，造成混淆敌我的后果。",figures:["毛泽东","刘少奇","彭真","陶铸"],place:"北京；全国社教试点县",state:"中华人民共和国",sources:["《农村社会主义教育运动中目前提出的一些问题》（1965年1月14日）、《关于建国以来党的若干历史问题的决议》（1981年6月）"],"tags":["二十三条","四清","走资派"]},related:["cn--1963--p01", "cn--1966--p01"]},
  {id:"cn--1965--p02",track:"cn",year:1965,yearApprox:false,dim:"politics",weight:3,title:"西藏自治区正式成立",summary:"8月25日至9月6日首届人大会议召开，9月1日宣告自治区成立。",detail:{background:"1959年3月国务院令后由西藏自治区筹备委员会行使地方政府职权，1965年8月召开筹委会会议决定召开首届人民代表大会。",process:"1965年8月25日至9月6日西藏自治区第一届人民代表大会第一次会议在拉萨召开，9月1日大会宣告西藏自治区正式成立；会议选举阿沛·阿旺晋美为自治区人民委员会主席，并通过关于贯彻民族区域自治政策的决议。据《西藏和平解放与繁荣发展》白皮书记载，到会代表301人中藏族及其他少数民族代表占80%以上。",impact:"标志民族区域自治制度在西藏完成建制，与1955年新疆、1958年广西与宁夏回族自治区共同构成省级自治区体系；1984年《民族区域自治法》进一步细化自治权。",figures:["阿沛·阿旺晋美","毛泽东","周恩来","张国华"],place:"西藏拉萨",state:"中华人民共和国",sources:["《西藏和平解放与繁荣发展》白皮书（国务院新闻办公室，2021年）、《西藏自治区简史（1949—2015）》"],"tags":["西藏自治区","民族区域自治","建制"]},related:["cn--1959--m01", "cn--1955--p03", "cn--1952--i02"]},
  {id:"cn--1965--m01",track:"cn",year:1965,yearApprox:false,dim:"military",weight:4,title:"中国部队入越执行援越抗美任务",summary:"1965年6月起防空、工程、铁道部队陆续入越。",detail:{background:"1964年8月北部湾事件后美国扩大对越南北方的轰炸；1965年2月至3月美军在岘港登陆并开始“滚雷行动”，越南劳动党与政府请求中国提供军事援助。",process:"应越方请求，1965年6月9日中国防空部队先遣支队入越，随后工程、铁道、公路运输、海军扫雷等部队陆续开进；据《当代中国军事工作》记载，1965年6月至1973年10月先后赴越执行任务的中国部队共32万余人，同时在越人数最多时约17万人，执行防空作战、机场与铁路修建、桥梁抢修复旧等任务。",impact:"越南北方的交通与机场体系得以维持，美方轰炸的作战效果受到限制；中国方面承担了对越援助的主要军事工程任务，据中方公布的资料，援越部队在越牺牲千余人，1965年至1973年间陆续撤回国内。",figures:["毛泽东","周恩来","罗瑞卿","徐深吉"],place:"越南民主共和国（河内、海防、谅山等地）",state:"中华人民共和国",sources:["《当代中国的军事工作》（当代中国出版社）、《中华人民共和国对外关系文件集》第12集"],"tags":["抗美援越","防空作战","军事工程"]},related:["cn--1964--e01", "cn--1965--p03"]},
  {id:"cn--1965--s01",track:"cn",year:1965,yearApprox:false,dim:"science",weight:4,title:"首次人工全合成结晶牛胰岛素",summary:"9月17日上海通过鉴定，为世界上第一次人工合成蛋白质。",detail:{background:"1958年12月中国科学院上海生物化学研究所启动牛胰岛素合成研究，1960年起由生化所、上海有机化学研究所与北京大学化学系分工协作，先后攻克A链与B链的合成与拆合。",process:"1965年9月17日中国科学院等单位在上海召开结晶牛胰岛素人工全合成鉴定会，确认人工合成的结晶牛胰岛素与天然品在结晶形状、酶解肽谱、电泳行为、免疫反应与生物学活力上一致，小鼠降糖实验显示具有与天然胰岛素相同的生理活性。",impact:"这是人类第一次以化学方法全合成具有生物活力的蛋白质，是1965年后中国生命科学领域的标志性成果；相关论文1966年发表于《科学通报》与《生物化学杂志》，1982年获国家自然科学奖二等奖。",figures:["王应睐","钮经义","邹承鲁","汪猷"],place:"上海（中国科学院上海生物化学研究所）",state:"中华人民共和国",sources:["《人工全合成牛胰岛素研究》鉴定资料（1965年9月17日）、《中国科学院生物化学研究所所史》"],"tags":["人工合成","牛胰岛素","蛋白质"]},related:["cn--1956--s02", "cn--1955--c01"]},
  {id:"cn--1965--p03",track:"cn",year:1965,yearApprox:false,dim:"politics",weight:4,title:"《评新编历史剧〈海瑞罢官〉》发表",summary:"11月10日《文汇报》刊发姚文元文章，成为文革的导火索。",detail:{background:"吴晗1960年创作、1961年上演的京剧《海瑞罢官》与1959年后毛泽东号召学习海瑞的“敢于直言”风气有关；1964年起北京文艺界已出现对该剧的批评。",process:"1965年11月10日上海《文汇报》以头版刊发姚文元《评新编历史剧〈海瑞罢官〉》，点名批判该剧的“阶级斗争”立场与“让步政策”史观；据《中国共产党的九十年》记载，该文的组稿与发表由江青、张春桥等在上海秘密组织，北京市委与中央宣传部事先未获通报。文章在北京方面抵制后，11月30日《人民日报》《光明日报》转载。",impact:"该文被普遍视为“文化大革命”的导火索；彭真主持的文化革命五人小组于1966年2月制定《关于当前学术讨论的汇报提纲》（“二月提纲”）试图把讨论约束在学术范围内，同年5月《五一六通知》撤销该提纲并解散五人小组。",figures:["姚文元","吴晗","彭真","江青","毛泽东"],place:"上海《文汇报》；北京",state:"中华人民共和国",sources:["姚文元《评新编历史剧〈海瑞罢官〉》（《文汇报》1965年11月10日）、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["海瑞罢官","导火索","文艺批判"]},related:["cn--1965--p01", "cn--1966--p01"]},
  {id:"cn--1966--p01",track:"cn",year:1966,yearApprox:false,dim:"politics",weight:5,title:"“五一六通知”",summary:"5月16日中央政治局扩大会议通过通知，撤销“二月提纲”。",detail:{background:"1966年4月中旬中央书记局会议在杭州召开，起草了提交政治局扩大会议的通知稿；彭真等人的“二月提纲”在会上受到批判。",process:"1966年5月4日至26日中央政治局扩大会议在北京召开，5月16日通过《中国共产党中央委员会通知》（“五一六通知”），决定撤销《关于当前学术讨论的汇报提纲》、撤销文化革命五人小组，并设置隶属中央政治局常委的“文化革命小组”；通知提出“一批反党反社会主义的学术权威”的“代表人物”已被“混入”党内与政府内。",impact:"“五一六通知”是“文化大革命”全面发动的纲领性文件；1981年历史决议指出其“作为指导思想的一系列论点，严重地混淆了思想上、政治上、纪律上的界限”，并确认这场运动“是一场由领导者错误发动，被反革命集团利用，给党、国家和各族人民带来严重灾难的内乱”。",figures:["毛泽东","刘少奇","彭真","陈伯达","康生"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["《中国共产党中央委员会通知》（1966年5月16日）、《关于建国以来党的若干历史问题的决议》（1981年6月）"],"tags":["五一六通知","文革发动","中央政治局"]},related:["cn--1965--p03", "cn--1966--p02", "cn--1966--p03", "world--1966--p03"]},
  {id:"cn--1966--p02",track:"cn",year:1966,yearApprox:false,dim:"politics",weight:4,title:"八届十一中全会与“十六条”",summary:"8月1日至12日全会通过《十六条》，改组中央领导机构。",detail:{background:"6月起北京大学聂元梓等人大字报经中央人民广播电台播发，北京高校出现工作组争议；7月毛泽东回京后批评派工作组“站到镇压学生运动的机会主义路线方面”。",process:"1966年8月1日至12日中共八届十一中全会在北京召开，8月8日通过《关于无产阶级文化大革命的决定》（“十六条”），规定“这次运动的重点，是整党内那些走资本主义道路的当权派”，并提出“让群众在运动中自己教育自己”；全会改组中央领导机构，林彪排位在刘少奇之前，成为副主席与接班人。",impact:"“十六条”取代“五一六通知”成为运动的行动纲领，“文化小组”与“革命同学会”等群众组织由此获得合法性；会议同时决定撤换若干中央领导人，中央一线工作格局发生变化。",figures:["毛泽东","林彪","刘少奇","邓小平","陶铸"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["《中国共产党中央委员会关于无产阶级文化大革命的决定》（1966年8月8日）、《建国以来毛泽东文稿》第12册"],"tags":["十六条","八届十一中全会","改组"]},related:["cn--1966--p01", "cn--1966--p03", "world--1966--p03"]},
  {id:"cn--1966--p03",track:"cn",year:1966,yearApprox:false,dim:"politics",weight:4,title:"红卫兵运动与首次接见",summary:"8月18日毛泽东在天安门接受百万师生检阅，随后全国大串联。",detail:{background:"1966年5月29日北京清华大学附属中学成立全国第一个“红卫兵”组织，6月起北京中学相继成立同类组织，中学与高校学生成为运动的先行群体。",process:"1966年8月18日毛泽东在北京天安门首次接见首都革命师生代表，参加接见的师生与红卫兵约100万人；此后8月31日、9月15日、10月1日、10月18日、11月3日、11月10日、11月26日毛泽东又多次接见，据《人民日报》报道前后共八次、累计1100余万人次。8月起学生凭免费乘车与伙食补助赴各地“革命串联”，把运动信息带到中小城市与农村。",impact:"大规模串联造成铁路运输与地方食宿供应紧张，国务院与铁道部门自1966年11月起发出通知限制外出串联的乘车安排；红卫兵跨区域行动使运动扩散到全国，并出现冲击党政机关、批斗干部与民主人士的现象。",figures:["毛泽东","林彪","聂元梓","宋彬彬"],place:"北京天安门；全国各大中城市",state:"中华人民共和国",sources:["《人民日报》1966年8月19日、《中国共产党中央委员会关于无产阶级文化大革命的决定》（1966年8月8日）","《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["红卫兵","大串联","接见"]},related:["cn--1966--p02", "cn--1966--p04", "world--1966--c02"]},
  {id:"cn--1966--p04",track:"cn",year:1966,yearApprox:false,dim:"politics",weight:3,title:"“破四旧”运动",summary:"8月起提出破除旧思想、旧文化、旧风俗、旧习惯，文物古迹受损。",detail:{background:"1966年6月1日《人民日报》社论《横扫一切牛鬼蛇神》号召破除旧思想、旧文化、旧风俗、旧习惯；8月1日毛泽东复信清华大学红卫兵表示祝贺，复信于8月18日发表后“破四旧”口号在全国流传。",process:"1966年8月18日后，北京等地红卫兵走上街头张贴“破四旧”标语，改换街道、公园与店铺名称，进入居民住宅查抄金银、文物、古籍与字画，并毁坏寺观、祠堂、陵墓与墓碑；同年11月9日山东师生红卫兵在谭厚兰带领下进入曲阜孔庙、孔林拆毁碑刻与塑像，1966年8月北京昌平明定陵地宫被打开、万历帝及皇后遗骨被焚毁。",impact:"“破四旧”造成公私收藏与地面文物的集中损毁，1966年8月至9月全国多地宗教场所、名人墓葬与古建筑被冲击；1978年后中央要求各地对“文革”中查抄的物资进行清退处理，1982年11月19日《中华人民共和国文物保护法》公布施行，从法律上明确了文物保护的归属与责任。",figures:["毛泽东","聂元梓","谭厚兰"],place:"北京、上海、曲阜、杭州等",state:"中华人民共和国",sources:["《人民日报》1966年8月社论、《中华人民共和国文物保护法》（1982年11月19日通过）"],"tags":["破四旧","文物","查抄"]},related:["cn--1966--p03", "cn--1966--p02", "world--1966--c02"]},
  {id:"cn--1966--i01",track:"cn",year:1966,yearApprox:false,dim:"institution",weight:3,title:"1966年高校招生推迟",summary:"6月中央批准推迟当年招生，此后高校连续四年停止统考招生。",detail:{background:"1966年高等学校招生工作原定于7、8月进行，高考拟于7月中旬举行；“文化大革命”发动后北京高校先行停课。",process:"1966年6月13日中共中央、国务院批转教育部《关于1966年高等学校招收新生的问题》，决定当年高等学校与中等专业学校招收新生工作推迟半年；据《中华人民共和国教育大事记（1949—1982）》记载，此后1966年至1970年全国高等院校连续停止统一招生，1959至1965年入学的在校学生延迟分配。",impact:"高考中断使1966至1970届中学毕业生升学长路受阻，1970年起改为推荐“工农兵学员”；1977年10月国务院批转教育部恢复高校统一招生考试。",figures:["何东昌","刘冰","教育部"],place:"北京；全国高等院校",state:"中华人民共和国",sources:["《关于1966年高等学校招收新生的问题》（1966年6月13日批转）、《中华人民共和国教育大事记（1949—1982）》"],"tags":["高校招生","停课","高考中断"]},related:["cn--1966--p02", "cn--1977--i01", "cn--1952--i01"]},
  {id:"cn--1967--p01",track:"cn",year:1967,yearApprox:false,dim:"politics",weight:4,title:"“一月风暴”与全面夺权",summary:"1月上海造反组织夺取市委市人委权力，此后各省相继夺权。",detail:{background:"1966年12月上海“工总司”等组织成立并形成与市委对峙的局面；1966年12月30日中央明确支持该组织。",process:"1967年1月6日上海30多个造反组织召开“打倒上海市委大会”，夺取上海市党政机关权力，史称“一月风暴”；1月8日毛泽东表示“这是一个阶级推翻一个阶级，这是一场大革命”，1月11日中央、国务院、中央军委、中央文革小组给上海各组织发贺电；此后各省、市、自治区党政机关相继被夺权。",impact:"夺权使各级党组织与政府机关陷于瘫痪，1967年1月至2月国务院多个部委被冲击；为恢复秩序，1967年起中央对部分单位实行军事管制并由军队“三支两军”介入地方工作。",figures:["毛泽东","张春桥","姚文元","王洪文"],place:"上海；全国各省市",state:"中华人民共和国",sources:["《中共中央、国务院、中央军委、中央文革小组贺电》（1967年1月11日）、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["一月风暴","夺权","上海"]},related:["cn--1966--p02", "cn--1967--p02", "cn--1968--i01"]},
  {id:"cn--1967--p02",track:"cn",year:1967,yearApprox:false,dim:"politics",weight:3,title:"“二月抗争”与“二月逆流”",summary:"2月中央政治局会议上多位老同志批评文革做法，被定为“逆流”。",detail:{background:"夺权与批斗波及军队与国务院系统，1967年1月至2月多位元帅与副总理在碰头会上提出意见。",process:"1967年2月11日至16日周恩来主持的中央政治局碰头会（怀仁堂会议）上，谭震林、陈毅、叶剑英、李富春、李先念、徐向前、聂荣臻等就“文化大革命”的搞法、老干部被打倒与军队是否搞“四大自由”提出强烈批评；2月19日毛泽东主持中央政治局会议批评这些同志，随后他们的意见被作为“二月逆流”在全国范围受到批判。",impact:"“二月逆流”案使一批资深领导人受到长期压制，军队与政府工作更深度由中央文革与“三支两军”系统主导；1978年12月经中共中央批准，中央组织部为“二月逆流”错案平反。",figures:["谭震林","陈毅","叶剑英","李富春","李先念","徐向前","聂荣臻","周恩来"],place:"北京中南海怀仁堂",state:"中华人民共和国",sources:["《毛泽东年谱（1949—1976）》下卷、《关于为“二月逆流”等冤案进行平反的请示报告》（1978年）"],"tags":["二月抗争","二月逆流","平反"]},related:["cn--1967--p01", "cn--1968--p01"]},
  {id:"cn--1967--s01",track:"cn",year:1967,yearApprox:false,dim:"science",weight:4,title:"第一颗氢弹空投试验成功",summary:"6月17日空投氢弹爆炸成功，距首颗原子弹2年8个月。",detail:{background:"1960年底于敏等提出突破氢弹的理论方案；1965年9月二机部九院完成氢弹原理性方案的理论突破，1966年12月28日成功进行氢弹原理试验，据《当代中国的国防科技事业》记载当量约33万吨。",process:"1967年6月17日8时20分，中国第一颗氢弹在核试验基地由强-5甲型轰炸机空投爆炸成功，据《当代中国的国防科技事业》记载爆炸当量约为330万吨梯恩梯；从第一颗原子弹到第一颗氢弹，中国用时2年8个月，快于美、苏、英的间隔时间。",impact:"使中国具备热核武器能力；中国政府1964年10月17日声明即宣布中国在任何时候、任何情况下都不会首先使用核武器，1967年6月17日声明再次重申这一立场并呼吁全面禁止和彻底销毁核武器。据公开资料，中国自1964年10月至1996年7月共进行45次核试验，1996年7月29日最后一次试验后宣布从1996年7月30日起暂停核试验。",figures:["于敏","钱三强","邓稼先","朱光亚","程开甲","聂荣臻"],place:"新疆马兰核试验基地",state:"中华人民共和国",sources:["《中华人民共和国政府声明》（1967年6月17日）、《当代中国的国防科技事业》（当代中国出版社）"],"tags":["氢弹","空投试验","国防科技"]},related:["cn--1964--s01", "cn--1967--p01", "world--1967--s01", "world--1966--m01"]},
  {id:"cn--1968--p01",track:"cn",year:1968,yearApprox:false,dim:"politics",weight:4,title:"八届十二中全会与刘少奇案",summary:"10月13日至31日全会批准审查报告，将刘少奇开除出党。",detail:{background:"1966年8月起刘少奇受到批判，1967年3月成立“刘少奇、王光美专案组”，专案材料经江青、康生、谢富治等人主持审查。",process:"1968年10月13日至31日中共八届十二中全会在北京召开，97名中央委员中仅40人出席、候补中央委员多数被剥夺出席会议；全会批准《关于叛徒、内奸、工贼刘少奇罪行的审查报告》，决定“把刘少奇永远开除出党，撤销其党内外一切职务”，并宣布由中央政治局代行了中央委员会职权的部分工作。",impact:"此案是“文化大革命”期间影响最大的一桩政治案件；1980年2月中共十一届五中全会通过《关于为刘少奇同志平反的决议》，撤销八届十二中全会的结论与党章处分，1982年11月中央书记处批转的复查报告确认原定性材料不能成立。",figures:["刘少奇","毛泽东","林彪","康生","王光美"],place:"北京",state:"中华人民共和国",sources:["《关于叛徒、内奸、工贼刘少奇罪行的审查报告》（1968年10月）","《中国共产党第十一届中央委员会第五次全体会议公报》（1980年2月29日）"],"tags":["八届十二中全会","刘少奇案","平反"]},related:["cn--1968--p02", "cn--1969--f01", "cn--1967--p02"]},
  {id:"cn--1968--p02",track:"cn",year:1968,yearApprox:false,dim:"politics",weight:4,title:"知识青年上山下乡高潮",summary:"12月毛泽东指示“知识青年到农村去”，运动进入高潮。",detail:{background:"1955年毛泽东在编辑《中国农村的社会主义高潮》时为浙江永嘉县关于农村剩余劳动力的按语提出就地努力与向边疆迁移相结合；1964年中央作出动员和组织城市知识青年参加农村社会主义建设的决定；1966年后城镇中学毕业生无法升学就业，积压毕业生达数十万人。",process:"1968年12月22日《人民日报》发表毛泽东“知识青年到农村去，接受贫下中农的再教育，很有必要”的指示，随即在全国掀起高潮；据国务院知识青年上山下乡领导小组办公室1980年代公布的统计，1968年至1978年全国约有1600万知识青年到农村与边疆插队落户或进入国营农场、生产建设兵团，其中“文化大革命”期间为1200余万人。",impact:"这一安置方式在缓解城镇就业压力的同时中断了城市青年的学业与职业发展；1978年后各地陆续放宽返城条件，1980年8月全国劳动就业会议提出统筹安排返城知青与城镇就业，大规模运动式动员此后停止，到1980年代初上山下乡基本结束。",figures:["毛泽东","邢燕子","侯隽","董加耕"],place:"北京；全国农村与边疆农场",state:"中华人民共和国",sources:["《人民日报》1968年12月22日、《知识青年上山下乡的若干政策问题的规定》（1978年12月）"],"tags":["上山下乡","知识青年","安置"]},related:["cn--1968--p01", "cn--1966--i01", "cn--1978--e01"]},
  {id:"cn--1968--i01",track:"cn",year:1968,yearApprox:false,dim:"institution",weight:3,title:"29个省级革命委员会全部建立",summary:"9月5日西藏、新疆同日成立革委会，取代原党政机关。",detail:{background:"1967年1月夺权后，各地先后建立“革命委员会”或“革命筹备小组”，中央以军队支左人员、干部代表与群众组织代表“三结合”的方式组织省级权力机构。",process:"1968年9月5日西藏自治区革命委员会、新疆维吾尔自治区革命委员会同时成立；至此全国29个省、市、自治区（不含台湾省）的革命委员会全部建立，省级党委机关此后陆续被革委会核心小组或党的核心领导小组取代。",impact:"革命委员会取代原有的党委与人民委员会，形成党政合一的一元化领导体制，是1966至1976年地方政权组织形态的基本特征；1979年9月五届全国人大二次会议通过地方组织法与选举法，把地方各级革命委员会改为各级人民政府。",figures:["曾雍雅","龙书金","谢富治"],place:"拉萨、乌鲁木齐；全国各省会",state:"中华人民共和国",sources:["《人民日报》1968年9月6日、《中华人民共和国地方各级人民代表大会和地方各级人民政府组织法》（1979年9月）"],"tags":["革命委员会","三结合","地方建制"]},related:["cn--1967--p01", "cn--1969--p01"]},
  {id:"cn--1968--s01",track:"cn",year:1968,yearApprox:false,dim:"science",weight:3,title:"南京长江大桥建成",summary:"9月30日铁路桥通车、12月29日公路桥通车，全部自主设计建造。",detail:{background:"1960年起由铁道部大桥工程局自行设计与施工，钢材、水泥等由国内生产供应，深水基础采用气压沉箱与管柱结合方案。",process:"1968年9月30日铁路桥建成通车，正桥长1576米、上层公路桥4车道、连同引桥全长6772米；1968年12月29日公路桥建成通车。据《当代中国的桥梁建设》记载，大桥是我国自主设计、自主施工并采用国产材料建造的第一座双层铁路公路两用长江大桥。",impact:"打通津浦与沪宁线，使京沪铁路全程贯通，成为“自力更生”路线的代表性工程；其钢梁、深水基础与桥头堡设计经验为1970年代后武汉、九江等长江大桥提供参照。",figures:["梅旸春","彭敏","林一山"],place:"江苏南京下关与浦口之间",state:"中华人民共和国",sources:["《南京长江大桥工程总结报告》、《人民日报》1968年12月30日"],"tags":["南京长江大桥","自主设计","铁路贯通"]},related:["cn--1957--s01", "cn--1967--p01"]},
  {id:"cn--1969--p01",track:"cn",year:1969,yearApprox:false,dim:"politics",weight:3,title:"中共九大召开",summary:"4月1日至24日召开，把林彪的“接班人”地位写入党章。",detail:{background:"1967年八大代表资格问题与九大筹备工作由康生、谢富治主持的“八大代表资格审查小组”处理，多数原中央委员被取消出席会议资格。",process:"1969年4月1日至24日中国共产党第九次全国代表大会在北京召开，出席代表1512人由“民主协商”产生而非正常选举程序；林彪代表中央作政治报告，4月14日通过的新党章把“林彪同志是毛泽东同志的亲密战友和接班人”写入总纲，大会选出中央委员170人、候补中央委员109人。",impact:"九大在思想上、政治上、组织上的指导方针被《中国共产党的九十年》认定为“错误的”；它使“文化大革命”的错误理论和实践合法化，1973年8月十大仍延续“无产阶级专政下继续革命”的表述。",figures:["毛泽东","林彪","周恩来","康生","谢富治"],place:"北京",state:"中华人民共和国",sources:["林彪《在中国共产党第九次全国代表大会上的报告》（1969年4月1日）、《中国共产党章程》（1969年4月14日通过）"],"tags":["九大","党章","接班人"]},related:["cn--1968--p01", "cn--1969--m01", "cn--1970--p01"]},
  {id:"cn--1969--m01",track:"cn",year:1969,yearApprox:false,dim:"military",weight:4,title:"珍宝岛事件与中苏边境冲突",summary:"3月2日至17日珍宝岛发生三次武装冲突，9月两国总理会谈。",detail:{background:"珍宝岛位于乌苏里江主航道中心线中国一侧，1964年边界谈判中苏方曾提出该岛归属问题；1967年起苏方边防军多次登岛巡逻并拦截中国民兵作业。",process:"1969年3月2日苏联边防军上岛袭击中国边防巡逻队，中国边防部队还击；3月15日苏方以飞机、坦克与炮兵登岛进攻，中方伏击后双方三次交火至3月17日；8月13日铁列克提方向发生另一次严重冲突。9月11日周恩来与苏联部长会议主席柯西金在北京首都机场举行会谈，达成维持边界现状、避免武装冲突、双方军队在争议地区脱离接触等谅解。",impact:"事件使中国把苏联视为主要军事威胁，1969年“九大”后全国进入“深挖洞、广积粮”的备战动员与三线建设加速阶段；中苏边界谈判自1969年10月20日恢复，问题直至1991年《中苏国界东段协定》与2004年补充协定才基本解决。",figures:["毛泽东","周恩来","柯西金","何友发"],place:"黑龙江乌苏里江珍宝岛；新疆铁列克提",state:"中华人民共和国",sources:["《中华人民共和国政府声明》（1969年3月）、《中华人民共和国对外关系文件集》第14集"],"tags":["珍宝岛","中苏冲突","边界谈判"]},related:["cn--1969--p01", "cn--1964--e01", "cn--1962--m01", "world--1969--m01"]},
  {id:"cn--1969--f01",track:"cn",year:1969,yearApprox:false,dim:"figure",weight:3,title:"刘少奇在开封逝世",summary:"11月12日刘少奇因病在开封去世，1980年2月中央为其平反。",detail:{background:"1968年10月八届十二中全会后刘少奇被监护治疗；1969年10月被送往河南开封，化名“刘卫黄”住院。",process:"据1980年2月中共十一届五中全会《关于为刘少奇同志平反的决议》记载，刘少奇在患病期间“得不到及时正确的治疗”，于1969年11月12日晨在开封逝世，终年71岁；其骨灰由开封市殡仪馆以“刘卫黄”名义寄存至1980年。",impact:"1980年5月17日刘少奇追悼大会在北京人民大会堂举行，邓小平致悼词；同年五中全会决议撤销八届十二中全会强加给他的“叛徒、内奸、工贼”的罪名与“把刘少奇永远开除出党”的决议，恢复其作为马克思主义者和无产阶级革命家的名誉。",figures:["刘少奇","邓小平","王光美"],place:"河南开封；北京",state:"中华人民共和国",sources:["《中国共产党第十一届中央委员会第五次全体会议关于为刘少奇同志平反的决议》（1980年2月29日）、《人民日报》1980年5月18日"],"tags":["刘少奇","平反","历史案件"]},related:["cn--1968--p01", "cn--1980--i01"]},
  {id:"cn--1970--s01",track:"cn",year:1970,yearApprox:false,dim:"science",weight:4,title:"第一颗人造地球卫星“东方红一号”",summary:"4月24日长征一号火箭发射，卫星重173公斤并播送乐曲。",detail:{background:"1958年5月中央提出研制人造卫星的设想；1965年中央专委批准第一颗人造卫星的研制方案，任务代号“651”；此后同步研制“长征一号”运载火箭、跟踪测控网与地面站。",process:"1970年4月24日21时35分，中国第一颗人造地球卫星“东方红一号”由“长征一号”运载火箭在酒泉卫星发射中心发射升空，卫星重量173公斤，近地点439公里、远地点2384公里、运行周期114分钟，播送《东方红》乐曲；4月25日全球收到卫星信号，4月26日新华社播发关于卫星与火箭的公开消息。",impact:"使中国成为继苏、美、法、日之后第五个独立研制并发射人造卫星的国家，2016年起4月24日被设立为“中国航天日”；由该任务形成的长征系列运载火箭沿用至今。",figures:["钱学森","任新民","戚发轫","赵九章","屠守锷"],place:"酒泉卫星发射中心（内蒙古额济纳旗境内）",state:"中华人民共和国",sources:["新华社《关于中国第一颗人造地球卫星的消息》（1970年4月26日）、《当代中国的航天事业》"],"tags":["东方红一号","长征火箭","第五个"]},related:["cn--1956--s02", "cn--1964--s01"]},
  {id:"cn--1970--s02",track:"cn",year:1970,yearApprox:false,dim:"science",weight:3,title:"成昆铁路全线通车",summary:"7月1日全线正式运营，正线长1096公里，桥隧约占四成。",detail:{background:"1958年7月起由铁道兵第二师等部队分段施工，1964年8月中央决定会战式抢通，投入铁道兵与机械筑路部队共约41万人。",process:"1970年7月1日成昆铁路全线正式通车交付运营，正线全长1096公里（成都—昆明）；据《当代中国的铁路建设》记载，全线有桥梁991座、隧道427座，桥隧总延长约占线路全长的四成，穿越小相岭、普济州等地质复杂地段，沿线设车站122个。",impact:"打通攀西地区与云贵间的铁路通道，使攀枝花钢铁基地、六盘水煤矿与西昌卫星发射中心的物资运输成为可能，是三线建设的骨干工程；筑路期间有2000余名铁道兵官兵与筑路工人牺牲，沿线建有22处烈士陵园。",figures:["彭敏","刘建章"],place:"四川成都至云南昆明",state:"中华人民共和国",sources:["《当代中国的铁路建设》（中国铁道出版社）、《人民日报》1970年7月2日"],"tags":["成昆铁路","铁道兵","三线建设"]},related:["cn--1952--s01", "cn--1964--e01"]},
  {id:"cn--1970--p01",track:"cn",year:1970,yearApprox:false,dim:"politics",weight:3,title:"九届二中全会与“设国家主席”争论",summary:"8月23日至9月6日庐山全会围绕天才论与国家主席问题发生争论。",detail:{background:"1970年3月起毛泽东在武汉等地多次就修改宪法表态，明确表示不设国家主席、自己不当国家主席；同年7月至8月中央政治局会议着手讨论修改宪法与四届人大的筹备问题。",process:"1970年8月23日至9月6日中共九届二中全会在庐山召开，会议按原定议程讨论修改宪法、国民经济第四个五年计划与战备问题；8月29日起华北组会议材料围绕“天才地、创造性地、全面地继承、捍卫和发展了马克思列宁主义”等表述与是否设国家主席发生争论，9月9日毛泽东印发《我的一点意见》批评陈伯达，全会结束后中央指定人对陈伯达的问题进行审查。",impact:"全会暴露出林彪集团与毛泽东之间的裂痕，成为1971年“九一三事件”的直接前奏；1970年12月至1971年批陈整风运动展开。",figures:["毛泽东","林彪","陈伯达","周恩来"],place:"江西庐山",state:"中华人民共和国",sources:["毛泽东《我的一点意见》（1970年9月9日）、《中国共产党第九届中央委员会第二次全体会议公报》"],"tags":["九届二中全会","设国家主席","陈伯达"]},related:["cn--1969--p01", "cn--1971--p04"]},
  {id:"cn--1970--i01",track:"cn",year:1970,yearApprox:false,dim:"institution",weight:3,title:"高等学校试行推荐“工农兵学员”",summary:"6月27日中央批转北大清华报告，招生废除文化考试。",detail:{background:"1970年高校复课，招生对象、条件与办法需要重新确定；“文化大革命”期间对“追求高分”的考试制度持批判态度。",process:"1970年6月27日中共中央批转《北京大学、清华大学关于招生（试点）的请示报告》，规定高等学校招生废除文化考试，实行“群众推荐、领导批准、学校复审”的办法，招生对象为具有初中毕业以上文化程度的工人、贫下中农、解放军战士与革命干部，学制一般为3年。",impact:"1970至1976年全国高等院校共招收“工农兵学员”约94万人（据《中国教育年鉴》统计口径），学员文化课基础差异悬殊，1977年12月恢复高考后这批学员的学历与学籍由国务院教育主管部门按统一口径认定。",figures:["周培源","刘冰","迟群"],place:"北京；全国高等院校",state:"中华人民共和国",sources:["中共中央批转《北京大学、清华大学关于招生（试点）的请示报告》（1970年6月27日）、《中华人民共和国教育大事记（1949—1982）》"],"tags":["工农兵学员","推荐入学","高校招生"]},related:["cn--1966--i01", "cn--1977--i01"]},
  {id:"cn--1971--p01",track:"cn",year:1971,yearApprox:false,dim:"politics",weight:4,title:"基辛格秘密访华",summary:"7月9日至11日基辛格抵京与周恩来会谈，15日双方同时公告。",detail:{background:"1969年珍宝岛事件后，中央决定通过大使级会谈以外的渠道探索中美接触；1970年10月毛泽东在天安门对斯诺表示「美国人民是伟大的人民」，12月又表示愿与美国总统或其代表会谈。",process:"1971年7月9日至11日，美国总统国家安全事务助理基辛格由巴黎飞抵北京，在中南海与周恩来秘密会谈，双方就台湾问题、印度支那问题与尼克松访问事宜交换意见；7月15日北京与华盛顿同时发表公告，宣布尼克松总统接受周恩来总理邀请，将于1972年5月以前的适当时间访问中国。",impact:"秘密访华打破了中美22年无正式接触的僵局，日本方面事先未获通报；1971年10月基辛格第二次访华落实访问安排，1972年2月尼克松访华并发表上海公报。",figures:["周恩来","基辛格","尼克松","黄华","毛泽东"],place:"北京中南海",state:"中华人民共和国",sources:["《中美两国政府同时发表的公告》（1971年7月15日）、基辛格《论中国》（2011年）"],"tags":["基辛格访华","中美关系","秘密外交"]},related:["cn--1969--m01", "cn--1971--p02", "cn--1972--p01", "world--1971--p06"]},
  {id:"cn--1971--p02",track:"cn",year:1971,yearApprox:false,dim:"politics",weight:3,title:"“乒乓外交”",summary:"4月美国乒乓球队访华，周恩来接见，两国民间往来重启。",detail:{background:"1971年3月第31届世界乒乓球锦标赛在日本名古屋举行，中国代表团参赛；美国队方面通过多种渠道表示希望与中国选手交往并访华。",process:"1971年4月美国选手科恩误上中国队班车，庄则栋主动赠礼致意；4月14日毛泽东决定邀请美国乒乓球队访华，4月10日至17日美国、加拿大等国球队先后到北京，周恩来在人民大会堂接见各国代表团成员并表示这次访问“打开了两国人民友好往来的大门”。",impact:"1971年4月美国白宫宣布放宽对美国船只向中国提供石油与天然气的限制、放宽人员往来与禁运措施，中国乒乓球队随后回访美国；这一过程后来被概括为“小球转动大球”。",figures:["毛泽东","周恩来","庄则栋","科恩"],place:"日本名古屋；北京",state:"中华人民共和国",sources:["新华社1971年4月关于美国乒乓球队访华的报道、《中华人民共和国外交史》第三卷"],"tags":["乒乓外交","民间往来","名古屋"]},related:["cn--1971--p01", "world--1971--p06", "world--1971--p02"]},
  {id:"cn--1971--p03",track:"cn",year:1971,yearApprox:false,dim:"politics",weight:5,title:"中国恢复在联合国的合法席位",summary:"10月25日第26届联大通过2758号决议，76票赞成、35票反对。",detail:{background:"1950年至1971年，在美国操纵下历届联大多次通过暂缓讨论中国代表权问题的提案；1961年起阿尔巴尼亚等国连续提案恢复中华人民共和国权利，1970年表决时赞成票首次过半但被以未达所需多数为由判为无效。",process:"1971年10月25日第26届联合国大会表决中国代表权问题：美国等提出的缓议修正案未获通过，阿尔巴尼亚、阿尔及利亚等23国草案以76票赞成、35票反对、17票弃权通过，成为大会第2758号决议，承认中华人民共和国的代表是中国在联合国的唯一合法代表，并要求立即驱逐蒋介石的代表。",impact:"11月1日联合国通知停止台湾当局机构的代表权，11月15日乔冠华率中国代表团首次出席联大全体会议，中国在安全理事会的常任理事国席位同时恢复；1971年内又有多个国家与中华人民共和国建交。",figures:["乔冠华","姬鹏飞","周恩来","毛泽东"],place:"美国纽约联合国总部",state:"中华人民共和国",sources:["联合国大会第2758（第二十六届）号决议（1971年10月25日）、新华社1971年10月27日电"],"tags":["2758号决议","代表权","联合国"]},related:["cn--1954--p04", "cn--1971--p01", "cn--1974--p02", "world--1971--p04"]},
  {id:"cn--1971--p04",track:"cn",year:1971,yearApprox:false,dim:"politics",weight:5,title:"九一三事件",summary:"9月13日林彪等乘飞机外逃，凌晨在温都尔汗附近坠毁身亡。",detail:{background:"1970年九届二中全会后中央开展批陈整风；1971年3月林立果等在空军机关进行策划，据1980年特别法庭公布的材料形成《“571工程”纪要》；8月中旬至9月上旬毛泽东在南方巡视途中同多地负责人谈话，批评林彪在庐山会议上的表现。",process:"据中共中央1971年9月的通报并经1981年最高人民法院特别法庭审理确认，9月12日晚林立果等策划出逃，13日凌晨林彪、叶群、林立果等乘256号三叉戟飞机从山海关机场强行起飞北逃，飞机在蒙古温都尔汗附近坠毁，机上人员全部死亡；同日黄永胜、吴法宪、李作鹏、邱会作被责令作出检查，中央派工作组进驻总政治部、空军与海军领导机关。",impact:"林彪事件使许多干部和群众从“文化大革命”的迷梦中清醒；1971年10月起中央逐级通报事件并展开批林整风，1981年1月特别法庭认定林彪、江青两个集团篡夺党和国家最高权力的犯罪事实。",figures:["林彪","叶群","林立果","毛泽东","周恩来"],place:"山海关机场；蒙古温都尔汗",state:"中华人民共和国",sources:["中共中央《关于林彪叛国出逃事件的通知》（1971年9月发出、10月起传达到基层）、最高人民法院特别法庭《判决书》（1981年1月25日）"],"tags":["九一三事件","林彪","温都尔汗"]},related:["cn--1970--p01", "cn--1973--p01"]},
  {id:"cn--1971--s01",track:"cn",year:1971,yearApprox:false,dim:"science",weight:4,title:"青蒿乙醚中性提取物研制成功",summary:"10月4日屠呦呦课题组第191号样品抑疟率达100%。",detail:{background:"1967年5月23日全军与地方13个单位召开疟疾防治协作会议，启动代号“523”的抗疟药物研究；1969年1月中医研究院中药研究所组建研究组，屠呦呦任组长，从历代医籍整理方药。",process:"课题组从葛洪《肘后备急方》“青蒿一握，以水二升渍，绞取汁，尽服之”的记载得到启发，把高温煎煮改为低温乙醚萃取；1971年10月4日第191号乙醚中性提取物样品对鼠疟、猴疟疟原虫的抑制率达到100%，随后在云南疟疾区组织临床观察。",impact:"这一节点使青蒿研究从数百个方药中确定方向，1972年分离出有效单体、1970年代中期完成结构测定并投产；以青蒿素为基础的联合疗法后被世界卫生组织列为治疗恶性疟的首选推荐方案，2015年屠呦呦据此获诺贝尔生理学或医学奖。",figures:["屠呦呦","中医研究院中药研究所课题组"],place:"北京；云南疟疾流行区",state:"中华人民共和国",sources:["屠呦呦《青蒿及青蒿素类药物》（化学工业出版社，2009年）、“523任务”档案资料汇编（1978年内部印发）"],"tags":["青蒿素","523任务","抗疟"]},related:["cn--1972--s01", "world--1972--s02"]},
  {id:"cn--1972--p01",track:"cn",year:1972,yearApprox:false,dim:"politics",weight:5,title:"尼克松访华与《上海公报》",summary:"2月21日至28日尼克松访华，28日在上海发表联合公报。",detail:{background:"1971年7月与10月基辛格两次访华，落实尼克松访问的日期与公报方案；访华前美方通知台湾当局不得公开介入中美会谈。",process:"1972年2月21日至28日美国总统尼克松访华，2月21日毛泽东在中南海会见尼克松与基辛格，周恩来同尼克松、罗杰斯先后举行五次会谈；2月28日双方在上海发表《中美联合公报》，中方重申台湾是中国一部分、中华人民共和国政府是唯一合法政府，美方表示认识到所有国家都主张只有一个中国、台湾是中国的一部分，并确认将逐步减少对台军事存在直至最终撤出全部武装力量与军事设施，双方还写入不在亚太地区谋求霸权的条款。",impact:"公报以各自陈述立场的方式处理分歧，成为中美三个联合公报的基础；访问期间双方决定互设联络处，1973年5月起互派代表，这一进程直接推动日本在同年9月实现邦交正常化。",figures:["毛泽东","周恩来","尼克松","基辛格","罗杰斯"],place:"北京、杭州、上海",state:"中华人民共和国",sources:["《中美联合公报》（1972年2月28日）、《中华人民共和国外交史》第三卷"],"tags":["尼克松访华","上海公报","中美关系"]},related:["cn--1971--p01", "cn--1972--p02", "cn--1979--p01", "world--1972--p01"]},
  {id:"cn--1972--p02",track:"cn",year:1972,yearApprox:false,dim:"politics",weight:4,title:"中日邦交正常化",summary:"9月25日至30日田中角荣访华，29日发表中日联合声明。",detail:{background:"1972年7月7日田中角荣接替佐藤荣作出任日本首相并公开表示要实现日中邦交正常化；中方以“复交三原则”为前提，即中华人民共和国是代表中国的唯一合法政府、台湾属于中国、1952年《日华和约》非法无效。",process:"1972年9月25日至30日日本首相田中角荣、外相大平正芳访华，9月27日毛泽东会见田中与大平；9月29日两国政府发表《中日联合声明》，宣布结束两国间的不正常状态，日本方面对过去战争给中国人民造成的重大损害表示深刻歉意，中方在声明第五项中宣布放弃对日本的战争赔偿要求，双方承诺遵循和平共处五项原则、任何一方不在亚太地区谋求霸权；1973年1月起互派大使。",impact:"联合声明与1978年8月12日签订的《中日和平友好条约》构成两国关系的政治基础；1972年内中国与日本、联邦德国等多国建交或升格关系，对外关系出现新的局面。",figures:["毛泽东","周恩来","田中角荣","大平正芳"],place:"北京",state:"中华人民共和国",sources:["《中日联合声明》（1972年9月29日）、《中华人民共和国外交史》第三卷"],"tags":["中日建交","田中角荣","战争赔偿"]},related:["cn--1972--p01", "world--1972--p04"]},
  {id:"cn--1972--e01",track:"cn",year:1972,yearApprox:false,dim:"economy",weight:4,title:"四三方案：引进西方成套设备",summary:"1972年起从西方引进化纤化肥成套设备，规模达43亿美元。",detail:{background:"1972年前后国内棉花播种面积有限，化纤原料大量依赖进口；1972年1月22日国家计委向国务院报送《关于进口成套化纤、化肥技术设备的报告》，李先念、华国锋批示同意。",process:"1972年内先后与日本、法国、联邦德国、美国、荷兰、意大利、瑞士等国签订12套大型化纤与成套化肥设备合同；1973年1月国务院批准国家计委《关于增加引进成套设备的请示报告》，把引进总规模定为折合43亿美元，俗称“四三方案”，项目覆盖大化肥、化纤、烷基苯、石油化工与发电设备。",impact:"这批设备在1970年代后期陆续建成投产，国产化纤与尿素供应明显增加，缓解了穿衣与肥料不足的压力；它是1957年后首次大规模利用西方设备与技术信贷，为1978年后扩大引进积累了经验。",figures:["周恩来","李先念","余秋里","谷牧"],place:"北京；辽阳、上海、四川泸州等引进项目地",state:"中华人民共和国",sources:["国家计委《关于进口成套化纤、化肥技术设备的报告》（1972年1月22日报送）、国务院批准的《关于增加引进成套设备的请示报告》（1973年1月）"],"tags":["技术引进","成套设备","四三方案"]},related:["cn--1973--e01"]},
  {id:"cn--1972--s01",track:"cn",year:1972,yearApprox:false,dim:"science",weight:3,title:"青蒿素有效单体分离成功",summary:"11月课题组从乙醚提取物中分离出抗疟有效单体结晶。",detail:{background:"1971年10月乙醚中性提取物取得100%抑制率后，“523”办公会议组织多单位协作，把工作推进到有效成分分离与结构测定。",process:"1972年3月8日至11日全国疟疾防治研究协作组办公会议在南京听取青蒿乙醚提取物临床观察结果的报告；同年11月中医研究院课题组从乙醚中性部位分离出对鼠疟、猴疟抑制率达100%的有效单体结晶，1973年山东、云南等地单位亦取得同类结晶，后经结构测定确认为含过氧桥的新型倍半萜内酯，定名为青蒿素。",impact:"青蒿素的分离与结构确定使抗疟药物摆脱了对氯喹等合成药的单一路径，1975年起在国内试用于临床；相关成果1979年获国家发明奖，2011年屠呦呦获拉斯克临床医学奖，2015年获诺贝尔生理学或医学奖。",figures:["屠呦呦","全国523办公室","中医研究院中药研究所课题组"],place:"北京；江苏南京",state:"中华人民共和国",sources:["屠呦呦《青蒿及青蒿素类药物》（化学工业出版社，2009年）、世界卫生组织《疟疾治疗指南》公开出版物"],"tags":["青蒿素","有效单体","结构测定"]},related:["cn--1971--s01", "world--1972--s02"]},
  {id:"cn--1973--p01",track:"cn",year:1973,yearApprox:false,dim:"politics",weight:3,title:"邓小平恢复工作并参加中央领导",summary:"3月中央决定恢复其组织生活并任国务院副总理，12月参加政治局。",detail:{background:"1968年10月八届十二中全会后邓小平被停止中央领导职务，1969年10月下放到江西新建县的拖拉机修配厂劳动；林彪事件后毛泽东多次说邓小平“政治上一次犯错误”但“人才难得”。",process:"1973年3月中共中央作出恢复邓小平党的组织生活、分配其国务院副总理职务的决定；4月12日邓小平出席周恩来主持的招待柬埔寨国家元首西哈努克的宴会，公开露面；8月中共十大选举他为中央委员；12月12日毛泽东在中央政治局会议上提议邓小平参加政治局，12月22日中央发出通知，决定邓小平参加中央政治局和中央军事委员会。",impact:"复出使邓小平得以在1975年主持党、政、军日常工作；1977年7月中共十届三中全会作出《关于恢复邓小平同志职务的决议》，恢复其中共中央副主席、国务院副总理、中央军委副主席兼总参谋长的职务。",figures:["邓小平","毛泽东","周恩来"],place:"北京；江西新建",state:"中华人民共和国",sources:["《邓小平年谱（1975—1997）》上卷、中共中央关于邓小平参加中央和中央军事委员会领导工作的通知（1973年12月22日）"],"tags":["邓小平复出","国务院副总理","军委领导"]},related:["cn--1966--p02", "cn--1975--p01", "cn--1977--p01"]},
  {id:"cn--1973--p02",track:"cn",year:1973,yearApprox:false,dim:"politics",weight:3,title:"中共十大召开",summary:"8月24日至28日十大在北京召开，王洪文当选中央副主席。",detail:{background:"九大之后中央长时间未召开全国代表大会；十大出席的1249名代表由“民主协商”方式产生，而非正常的选举程序。",process:"1973年8月24日至28日中国共产党第十次全国代表大会在北京召开，周恩来作政治报告，报告继续肯定“无产阶级专政下继续革命”的理论并宣告“文化大革命”的胜利；王洪文作关于修改党的章程的报告；大会选出中央委员195人、候补中央委员124人，8月30日十届一中全会选举毛泽东为主席，周恩来、王洪文、康生、叶剑英、李德生为副主席，王洪文列副主席第二位、时年38岁。",impact:"十大延续了九大的错误指导方针，江青、张春桥、姚文元、王洪文在中央领导机构中形成“四人帮”，使1975年的全面整顿与1976年的政治冲突不可避免；1977年十一大仍宣布“文化大革命”结束。",figures:["毛泽东","周恩来","王洪文","康生","叶剑英"],place:"北京",state:"中华人民共和国",sources:["周恩来《在中国共产党第十次全国代表大会上的报告》（1973年8月24日）、《中国共产党第十次全国代表大会文件汇编》"],"tags":["十大","继续革命","四人帮"]},related:["cn--1969--p01", "cn--1974--p01"]},
  {id:"cn--1973--e01",track:"cn",year:1973,yearApprox:false,dim:"economy",weight:3,title:"第一次全国农业学大寨会议",summary:"12月国务院召开全国农业学大寨会议，部署农田建设与机械化。",detail:{background:"1966年2月毛泽东提出用二十年时间基本实现农业机械化的设想；1970年北方地区农业会议后“农业学大寨”成为农村工作主线，1971年与1973年粮食产量两度突破5000亿斤。",process:"1973年12月国务院在北京召开第一次全国农业学大寨会议，提出到1980年基本实现农业机械化的目标，部署各地兴修农田水利、大办化肥与农药工业、总结昔阳县等地学大寨的经验；会议把集体经营与限制自留地、家庭副业作为“大批资本主义”的内容一并推行。",impact:"会议推动了1970年代中期农田基建、农机工业与化肥生产的扩张，据国家统计局公布的序列，1973年全国粮食总产量达5305.8亿斤、为1957年以来的最高水平；同时对家庭副业与集市贸易的限制加剧了农村经济的单一化。",figures:["周恩来","李先念","陈永贵"],place:"北京；山西昔阳",state:"中华人民共和国",sources:["《第一次全国农业学大寨会议文件》（1973年12月）、国家统计局编《中国统计年鉴（1983）》农业产出序列"],"tags":["农业学大寨","机械化","粮食产量"]},related:["cn--1972--e01", "cn--1978--e01"]},
  {id:"cn--1973--s01",track:"cn",year:1973,yearApprox:false,dim:"science",weight:5,title:"籼型杂交水稻三系配套成功",summary:"冬季协作组确认不育系、保持系、恢复系配套，亩产提高约两成。",detail:{background:"1964年袁隆平在湖南安江农业学校开始寻找水稻雄性不育株并开展三系育种试验；1970年冬其助手李必湖、冯克珊在海南岛找到一株花粉败育的野生稻，被称为“野败”，为回交转育不育系提供了载体。",process:"1973年冬全国杂交水稻科研协作组在江苏苏州开会，确认通过野败型细胞质不育系、保持系与恢复系的转育与测交，籼型杂交水稻三系配套成功；袁隆平在会上提交《杂交水稻的育种实践》报告，同年秋季在湖南长沙等地示范，据《当代中国的农业科学技术》记载三系组合亩产较常规品种提高约两成。",impact:"1975年冬中央把杂交水稻列为重点推广项目，1976年起在全国示范推广；1981年“籼型杂交水稻”获国家发明奖特等奖，袁隆平2000年获首届国家最高科学技术奖、2019年获共和国勋章。",figures:["袁隆平","李必湖","冯克珊"],place:"江苏苏州；湖南长沙、安江",state:"中华人民共和国",sources:["袁隆平《杂交水稻的育种与栽培》（科学出版社）、《当代中国的农业科学技术》（当代中国出版社）"],"tags":["杂交水稻","三系配套","粮食增产"]},related:["cn--1956--s02", "cn--1973--e01"]},
  {id:"cn--1974--p01",track:"cn",year:1974,yearApprox:false,dim:"politics",weight:3,title:"批林批孔运动",summary:"1月中央转发《林彪与孔孟之道》材料，运动在全国展开。",detail:{background:"1973年7月毛泽东在一次谈话中批评郭沫若《十批判书》尊孔反法；同年下半年江青等组织北京大学、清华大学大批判组编辑《林彪与孔孟之道》材料。",process:"1974年1月中共中央向全国转发《林彪与孔孟之道》材料，批林批孔运动全面展开；2月《人民日报》《红旗》杂志发表社论，把批孔与“限制资产阶级法权”“反对修正主义”联系起来；河南省唐河县马振扶公社中学1973年7月批改学生试卷一事被作为“林彪路线回潮”的典型在全国通报，一批干部与教师受到清查处理，1979年3月教育部与河南省委复查后为该事件平反。",impact:"运动与“反经验主义”的提法结合，矛头指向1972年以来的经济恢复与老干部复出；据《中国共产党的九十年》记载，1974年工农业总产值只比上年增长1.4%，铁路货运量下降，部分企业再度半停产。",figures:["毛泽东","江青","王洪文","康生","姚文元"],place:"北京；全国各单位",state:"中华人民共和国",sources:["中共中央转发《林彪与孔孟之道》材料的通知（1974年1月）、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["批林批孔","马振扶事件","大批判"]},related:["cn--1971--p04", "cn--1975--e01"]},
  {id:"cn--1974--p02",track:"cn",year:1974,yearApprox:false,dim:"politics",weight:3,title:"邓小平出席联大特别会议与三个世界",summary:"4月邓小平在联大六届特别会议发言，阐明三个世界划分。",detail:{background:"1973年9月毛泽东在会见外宾时提出“中间地带”与三个世界的划分思路；1974年2月22日他在同赞比亚总统卡翁达谈话时系统阐述这一理论。",process:"1974年4月6日至14日邓小平率中国代表团出席纽约联合国大会第六届特别会议，4月10日在会上发言，阐明第一世界为美苏两个超级大国、第二世界为日本、欧洲、加拿大等发达国家、第三世界为亚非拉发展中国家，宣布中国属于第三世界、永远不称霸、不在国外驻军和建立军事基地；随后邓小平对加拿大、墨西哥、秘鲁、智利进行正式访问。",impact:"三个世界的划分成为1970年代中国对外战略的公开表述，为加强与第三世界国家关系并发展同西欧、日本的关系提供依据；邓小平的发言被联合国大会文件收录并译成多种文字发行。",figures:["邓小平","毛泽东","乔冠华"],place:"美国纽约联合国总部",state:"中华人民共和国",sources:["邓小平《在联合国大会第六届特别会议上的发言》（1974年4月10日）、毛泽东关于三个世界划分的谈话（1974年2月22日）"],"tags":["三个世界","联大特别会议","不称霸"]},related:["cn--1971--p03", "cn--1974--m01", "world--1971--p04"]},
  {id:"cn--1974--m01",track:"cn",year:1974,yearApprox:false,dim:"military",weight:3,title:"西沙自卫反击战",summary:"1月19日至20日海战与登岛作战，收复珊瑚、甘泉、金银三岛。",detail:{background:"1956年起南越当局陆续声称对西沙群岛拥有主权；1974年1月南越军舰在甘泉岛、金银岛附近冲撞中国渔船与巡逻舰艇，1月11日中华人民共和国外交部发表声明重申南海诸岛是中国固有领土。",process:"1974年1月19日晨南越军舰向中国巡逻舰艇开炮，人民解放军海军舰艇编队与渔轮、民兵在永乐环礁海域还击；据新华社1974年1月20日的报道，中国军民击沉南越护航炮舰1艘、击伤驱逐舰3艘，20日陆军与民兵登岛收复珊瑚、甘泉、金银三岛，中方18人牺牲，南越方面被击毙与被俘各数十人，其中含美军军事联络官1名被俘。",impact:"此役使中国完全控制西沙群岛，此后在西沙设立行政建制并驻防；中越（南越）关系恶化，南海诸岛主权问题自此长期成为地区争端议题，1975年越南统一后争端重心转移至南沙群岛。",figures:["毛泽东","叶剑英","邓小平"],place:"西沙群岛永乐环礁（金银岛、珊瑚岛、甘泉岛）",state:"中华人民共和国",sources:["新华社《关于西沙群岛军民被迫还击的报道》（1974年1月20日）、《中华人民共和国外交部声明》（1974年1月11日）"],"tags":["西沙海战","自卫反击","南海诸岛"]},related:["cn--1974--p02", "cn--1979--m01"]},
  {id:"cn--1974--s01",track:"cn",year:1974,yearApprox:false,dim:"science",weight:3,title:"第一艘核潜艇交付海军使用",summary:"8月1日首艘核潜艇举行命名签字仪式并服役，工程代号09。",detail:{background:"1958年聂荣臻提出中国研制核潜艇的建议；1962年中央决定保留这一研制项目，1965年9月工程正式立项、代号“09”，由二机部负责艇用核动力装置、六机部负责艇体建造；1970年12月首艇下水。",process:"1974年8月1日，中国第一艘核潜艇在辽宁葫芦岛举行命名签字仪式并交付海军使用，命名为“长征1号”，属攻击型核潜艇（091型首艇）；因该工程长期保密，其研制与服役情况到1990年代才陆续见诸公开报道。",impact:"使中国成为继美国、苏联、英国、法国之后第五个拥有核潜艇的国家，海基核反击与远洋保障能力由此起步；091型的动力与噪声问题在1980年代起持续改进。",figures:["彭士禄","黄纬禄","赵仁恺","聂荣臻"],place:"辽宁葫芦岛（渤海造船厂）",state:"中华人民共和国",sources:["《当代中国的船舶工业》（当代中国出版社）、《彭士禄传》（广东人民出版社，2007年）"],"tags":["核潜艇","091型","海军装备"]},related:["cn--1964--s01", "cn--1967--s01"]},
  {id:"cn--1975--p01",track:"cn",year:1975,yearApprox:false,dim:"politics",weight:3,title:"四届人大一次会议重申四个现代化",summary:"1月13日至17日开会，周恩来重申本世纪内实现四个现代化。",detail:{background:"1974年10月至11月毛泽东在同周恩来、王洪文等的谈话中提出“还是安定团结为好”“把国民经济搞上去”，并多次说“人才难得”，提议由邓小平任国务院第一副总理。",process:"1975年1月13日至17日第四届全国人民代表大会第一次会议在北京召开，周恩来在《政府工作报告》中重申1964年三届人大提出的“在本世纪内全面实现农业、工业、国防和科学技术的现代化，使我国国民经济走在世界前列”的设想；会议通过修订后的宪法，选举朱德为全国人大常委会委员长，决定周恩来任总理、邓小平任第一副总理；1月5日中央通知任命邓小平为中央军委副主席兼总参谋长，2月5日决定由邓小平在毛泽东领导下主持军委日常工作。",impact:"会议为1975年全面整顿提供了法定平台，邓小平以第一副总理与总参谋长身份主持中央日常工作，铁路、钢铁、科技与军队整顿依次展开；会议通过的宪法仍保留“坚持无产阶级专政下的继续革命”的表述。",figures:["周恩来","邓小平","朱德","毛泽东","张春桥"],place:"北京人民大会堂",state:"中华人民共和国",sources:["周恩来《政府工作报告》（1975年1月13日）、《中华人民共和国第四届全国人民代表大会第一次会议文件》"],"tags":["四个现代化","四届人大","全面整顿"]},related:["cn--1964--p03", "cn--1975--e01", "cn--1975--i01"]},
  {id:"cn--1975--e01",track:"cn",year:1975,yearApprox:false,dim:"economy",weight:4,title:"以铁路整顿为突破口的全面整顿",summary:"3月中央发出九号文件整顿铁路，整顿随后扩展到工业与科技。",detail:{background:"1974年“批林批孔”使运输与生产秩序再度混乱，全国20个铁路局中徐州、南昌、长沙等局长期完不成运输任务，煤炭与支农物资积压。",process:"1975年2月25日至3月8日国务院召开全国主管工业的党委第一书记会议，部署以铁路为重点的整顿；3月5日中共中央发出《关于加强铁路工作的决定》（中发〔1975〕9号，即“九号文件”），规定全国铁路由铁道部统一管理、集中指挥，万里任铁道部部长，中央派工作组进驻徐州、南昌、长沙等局并依法处理打砸抢首恶分子。",impact:"整顿迅速见效，据《中国共产党的九十年》记载，1975年4月堵塞最严重的徐州局面貌改观，全国货车日装车数上升到历史最好水平；铁路整顿成为全面整顿的突破口，此后钢铁、国防科技、科学院与军队整顿相继展开，1975年经济形势明显好转。",figures:["邓小平","万里","毛泽东","周恩来"],place:"北京；徐州、南昌、长沙等铁路局",state:"中华人民共和国",sources:["中共中央《关于加强铁路工作的决定》（中发〔1975〕9号，1975年3月5日）、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["铁路整顿","九号文件","全面整顿"]},related:["cn--1975--p01", "cn--1975--s01", "cn--1975--p02"]},
  {id:"cn--1975--s01",track:"cn",year:1975,yearApprox:false,dim:"science",weight:3,title:"科学院整顿与《汇报提纲》",summary:"胡耀邦等9月上报科技工作汇报提纲，提出科技是生产力。",detail:{background:"1975年7月15日中央派胡耀邦、李昌等到中国科学院主持工作，要求调查科技战线状况并恢复科研秩序。",process:"胡耀邦等在科学院召开50余次座谈会与调查会，9月形成《关于科技工作的几个问题（汇报提纲）》并上报，提纲以“科学技术是生产力”立论，提出正确处理政治与业务、红与专的关系，保证科研人员的业务研究时间，并肯定1949年以来科技工作的成绩；1975年9月26日至10月12日邓小平在听取国防科研汇报时同样强调“科学技术是生产力”。",impact:"《汇报提纲》在1975年冬“批邓、反击右倾翻案风”中被作为“修正主义科研纲领”在全国批判，科学院整顿措施被中止；1978年3月全国科学大会重新确认“科学技术是生产力”的论断，1988年邓小平进一步提出“科学技术是第一生产力”。",figures:["胡耀邦","李昌","邓小平","华罗庚"],place:"北京（中国科学院）",state:"中华人民共和国",sources:["胡耀邦、李昌等《关于科技工作的几个问题（汇报提纲）》（1975年9月上报）、《中国共产党的九十年》（社会主义革命和建设时期）"],"tags":["科学院整顿","汇报提纲","科学技术是生产力"]},related:["cn--1978--s01", "cn--1975--e01"]},
  {id:"cn--1975--i01",track:"cn",year:1975,yearApprox:false,dim:"institution",weight:3,title:"1975年宪法公布施行",summary:"1月17日四届人大一次会议通过，全文仅4章30条。",detail:{background:"1974年7月中共十届二中全会讨论修改宪法问题并成立宪法修改起草委员会，同年10月至1975年1月各省、市、自治区组织讨论宪法草案。",process:"1975年1月17日第四届全国人民代表大会第一次会议通过《中华人民共和国宪法》，全文4章30条，是建国后条文最少的一部宪法；宪法写入“中国共产党是领导核心”，把“坚持无产阶级专政下的继续革命”作为指导思想，保留群众“大鸣、大放、大字报、大辩论”的规定，不设国家主席，并删去1954年宪法中公民在法律上一律平等的条款。",impact:"该宪法实施仅三年（1975年1月至1978年3月）；1980年2月中共十一届五中全会建议修改宪法、取消“四大”条款，1982年12月4日五届全国人大五次会议通过现行宪法，重新以1954年宪法为基础。",figures:["毛泽东","周恩来","张春桥","邓小平"],place:"北京",state:"中华人民共和国",sources:["《中华人民共和国宪法》（1975年1月17日通过）、《中华人民共和国宪法》（1982年12月4日通过）"],"tags":["七五宪法","继续革命","四大"]},related:["cn--1954--i01", "cn--1975--p01", "cn--1982--i01"]},
  {id:"cn--1975--d01",track:"cn",year:1975,yearApprox:false,dim:"disaster",weight:3,title:"河南“75·8”水库溃决",summary:"8月8日极端暴雨致板桥、石漫滩等水库垮坝，京广铁路中断。",detail:{background:"1975年8月3号台风北上，8月5日至8日河南驻马店地区林庄出现极端暴雨，三天雨量1605毫米、单日雨量逾1000毫米，位居同期世界纪录前列；淮河流域上游水库群设计标准偏低。",process:"1975年8月8日凌晨，板桥、石漫滩两座大型水库及数十座中小型水库相继溃决，下泄洪水冲击遂平、西平、上蔡、漯河等地，京广铁路遂平至明港区间线路被冲毁、中断运营48天；武汉军区与驻军组织抢险，中央派出工作组与医疗队，8月中旬洪水消退后转入安置与防疫。",impact:"官方当年未公开报道灾情细节，1980至1990年代水利与气象部门陆续公开的调查文献记载，溃坝造成的直接死亡人数约2.6万人，学界对包括灾后疫病在内的总死亡人数另有更高估计，未见统一口径；此后全国水库普遍提高溢洪道与保坝标准，1991年《水库大坝安全管理条例》施行。",figures:["毛泽东","华国锋","钱正英"],place:"河南驻马店（板桥、石漫滩水库）",state:"中华人民共和国",sources:["水利电力部《关于河南省板桥、石漫滩水库垮坝情况的报告》（1975年）、《河南水旱灾害》（黄河水利出版社，2004年）"],"tags":["水库溃决","暴雨","淮河流域"]},related:["cn--1954--d01", "cn--1976--d01"]},
  {id:"cn--1975--p02",track:"cn",year:1975,yearApprox:false,dim:"politics",weight:4,title:"批邓、反击右倾翻案风",summary:"1975年11月起中央政治局批评邓小平，1976年2月推向全国。",detail:{background:"1975年秋毛泽东多次谈话要求肯定“文化大革命”“三七开”的成绩、以安定团结为好，同时批评邓小平主持的整顿工作没有“肯定文化大革命的成绩”。",process:"1975年11月起中央政治局根据毛泽东的批评意见多次开会批评邓小平，“批邓、反击右倾翻案风”在高层与宣传系统展开；12月《人民日报》《红旗》杂志发表《教育革命的方向不容篡改》等文章，科学院、铁道部与国防科研系统的整顿措施被指为“复辟”“翻案”并遭到清查；1976年2月25日中央召集党政军负责人会议把运动推向全国，各地举行批邓集会，1975年的整顿文件陆续被收回或修订。",impact:"运动使1975年整顿中断，经济与秩序再度动荡；1976年4月7日中央政治局通过决议撤销邓小平党内外一切职务、保留党籍，1977年7月中共十届三中全会决定恢复其职务，1981年历史决议把这场运动列为“文化大革命”后期的错误之一。",figures:["毛泽东","邓小平","姚文元","江青","迟群"],place:"北京；全国",state:"中华人民共和国",sources:["《毛泽东年谱（1949—1976）》下卷、《关于建国以来党的若干历史问题的决议》（1981年6月）"],"tags":["批邓","反击右倾翻案风","整顿中断"]},related:["cn--1975--e01", "cn--1976--p02", "world--1976--p02"]},
  {id:"cn--1976--p01",track:"cn",year:1976,yearApprox:false,dim:"politics",weight:3,title:"周恩来逝世",summary:"1月8日因患癌症在北京逝世，终年77岁，15日追悼大会举行。",detail:{background:"周恩来1972年5月确诊膀胱癌，1975年后病情加重仍坚持工作；1976年1月初最后一次出席国事活动。",process:"1976年1月8日9时57分，国务院总理周恩来因患癌症经抢救无效在北京逝世，终年77岁；1月15日追悼大会在人民大会堂举行，邓小平致悼词；送灵车队沿长安街东行时街头有大量群众自发肃立致哀，一些国家宣布降半旗或发表声明致哀。",impact:"周恩来的逝世使长期积压的社会情绪集中释放，各地以送花圈、诗词等形式展开的悼念活动与1976年4月天安门广场事件的形成直接相关；1976年4月7日中央政治局任命华国锋为国务院总理。",figures:["周恩来","邓颖超","邓小平","毛泽东"],place:"北京",state:"中华人民共和国",sources:["新华社《关于周恩来同志逝世的公报》（1976年1月8日）、《周恩来传（1949—1976）》（中央文献出版社）"],"tags":["周恩来","逝世","悼念"]},related:["cn--1976--p02", "cn--1975--p01"]},
  {id:"cn--1976--p02",track:"cn",year:1976,yearApprox:false,dim:"politics",weight:4,title:"四五运动（天安门事件）",summary:"4月4日至5日数十万群众到天安门悼念周恩来，随后遭清场。",detail:{background:"1976年1月周恩来逝世后，各地干部与群众以吊唁、送花圈等形式表达对“四人帮”的不满；3月下旬南京出现悼念与声讨“四人帮”的标语大字报，北京厂矿学校把花圈送到人民英雄纪念碑前。",process:"1976年4月4日清明节，北京数十万群众到天安门广场悼念周恩来，张贴诗词与传单，矛头指向“四人帮”；4月5日凌晨广场上的花圈与诗词被清走，滞留群众与奉命驱散的民兵、公安人员发生冲突，有人受伤；当晚中央政治局开会把事件定性为“反革命政治事件”，4月7日凌晨清场，当晚通过撤销邓小平党内外一切职务、任命华国锋为中共中央第一副主席和国务院总理的两个决议，随后北京开展拘捕与清查。",impact:"1978年11月14日中央政治局批准中共北京市委作出为“四五”运动平反的决定，宣布1976年4月5日的群众运动“完全是革命的”，撤销“反革命政治事件”的结论并释放被拘人员；1981年历史决议确认，以天安门事件为代表的群众运动对于后来粉碎江青反革命集团、结束“文化大革命”的灾难具有重大意义。",figures:["周恩来","邓小平","江青","华国锋"],place:"北京天安门广场；南京等地",state:"中华人民共和国",sources:["中共北京市委《关于坚决执行中央方针、为“四五”运动平反的决定》（1978年11月14日）、《关于建国以来党的若干历史问题的决议》（1981年6月）"],"tags":["四五运动","天安门事件","平反"]},related:["cn--1976--p01", "cn--1975--p02", "cn--1976--p05", "world--1976--c01"]},
  {id:"cn--1976--s01",track:"cn",year:1976,yearApprox:false,dim:"science",weight:3,title:"吉林陨石雨与1770公斤主陨石",summary:"3月8日陨石带落于吉林周边，收集到世界最大单块石陨石。",detail:{background:"1976年3月8日15时前后，吉林、永吉、舒兰一带天空出现白色烟带与连续爆炸声，地面多人目击到陨落的石块与冰雪上的烧蚀孔洞。",process:"1976年3月8日一场陨石雨降落在吉林省吉林市周边的永吉、舒兰、磐石一带，散落区呈北西向带状分布、长约72公里；据中国科学院紫金山天文台的公开研究资料，事后共收集到陨石总重约4吨，其中3月23日从永吉县六米深泥水中取出的“吉林1号”重1770公斤，为迄今世界上发现的最大单块石陨石。",impact:"吉林陨石属普通球粒陨石，其矿物与同位素研究表明形成年龄约46亿年，为太阳系早期物质研究提供了珍贵样品；相关成果自1978年起陆续发表于《科学通报》等刊物，样品长期供国内外实验室共享研究。",figures:["中国科学院紫金山天文台","吉林省地震办公室"],place:"吉林永吉、舒兰、磐石一带",state:"中华人民共和国",sources:["中国科学院紫金山天文台《吉林陨石》（科学出版社）、《科学通报》相关论文（1978年起）"],"tags":["陨石雨","吉林1号","球粒陨石"]},related:[]},
  {id:"cn--1976--d01",track:"cn",year:1976,yearApprox:false,dim:"disaster",weight:4,title:"唐山大地震",summary:"7月28日3时42分发生7.8级地震，市区建筑大部被毁。",detail:{background:"1975年2月4日辽宁海城7.3级地震曾因短临预报与疏散而减少伤亡；国家地震局自1966年邢台地震后逐步建立群测群防体系，唐山是京津唐工业基地的组成部分。",process:"1976年7月28日3时42分，河北省唐山市发生里氏7.8级地震，震源深度约12公里，震中烈度11度，天津、北京等地震感强烈且天津受损严重；据国家地震局编《中国地震年鉴》记载，地震直接造成24.2万余人死亡、16.4万余人重伤，唐山市区建筑物损毁约九成，开滦煤矿、京山铁路与供水系统一度瘫痪。",impact:"北京军区与全国部队、医疗队于7月28日至29日赶赴灾区，全国调集施工力量参加抢救与恢复生产；1976年冬起重建规划编制，新市区在1980年代中期基本建成，1986年10月唐山抗震纪念碑落成，这一灾害与海城经验共同推动我国建筑抗震设防标准的修订加严。",figures:["华国锋","叶剑英","唐山抗震救灾指挥部","北京军区"],place:"河北唐山、丰南；天津",state:"中华人民共和国",sources:["新华社《关于唐山、丰南地区强烈地震和军民抗震救灾的报道》（1976年8月）、国家地震局编《中国地震年鉴》"],"tags":["唐山地震","抗震救灾","烈度11度"]},related:["cn--1976--d02", "cn--1975--d01", "world--1976--d01"]},
  {id:"cn--1976--d02",track:"cn",year:1976,yearApprox:false,dim:"disaster",weight:3,title:"四川松潘—平武7.2级地震",summary:"8月16日与23日两次7.2级地震，因提前疏散伤亡减轻。",detail:{background:"1973年起国家地震局与四川省地震部门把岷山一带列为监视重点；1976年7月28日唐山地震后全国震情紧张，8月上旬松潘、平武一带前兆资料明显增多。",process:"1976年8月16日21时34分，四川省松潘、平武之间发生7.2级地震，8月23日同一地区再次发生7.2级地震；由于8月上旬四川省革命委员会在松潘、平武组织疏散、暂停山区交通与工矿作业，人员伤亡显著减轻，据国家地震局公开资料，两次主震造成死亡39至41人（不同统计口径），而部分区乡房屋破坏严重。",impact:"松潘—平武地震与海城地震常被作为我国群测群防与短临预报的两例公开记录，而唐山地震的漏报则显示当时预报能力的局限；这些经验推动了1980年代地震监测台网扩建与工程抗震规范的修订。",figures:["国家地震局","四川省革命委员会"],place:"四川松潘、平武",state:"中华人民共和国",sources:["国家地震局编《中国地震年鉴》、《四川省志·地震志》（四川人民出版社）"],"tags":["松潘地震","地震预报","疏散"]},related:["cn--1976--d01"]},
  {id:"cn--1976--p03",track:"cn",year:1976,yearApprox:false,dim:"politics",weight:3,title:"朱德逝世",summary:"7月6日朱德在北京逝世，终年90岁，11日追悼大会举行。",detail:{background:"朱德1955年被授予中华人民共和国元帅称号并名列首位，此后长期担任全国人大常委会委员长，在“文化大革命”中仍负责统一战线与对外友好方面的工作。",process:"1976年7月6日，中共中央副主席、全国人大常委会委员长朱德因心脏病发作经抢救无效在北京逝世，终年90岁；7月11日追悼大会在人民大会堂举行，叶剑英致悼词，党、政、军方面领导人与各国使节参加。",impact:"周恩来、朱德、毛泽东在1976年1月至9月相继逝世，使这一年成为建国以来领导人更替最集中的一年；悼念活动与“批邓、反击右倾翻案风”的推进相互交织，社会情绪的高涨成为1976年10月政治变动的背景之一。",figures:["朱德","康克清","叶剑英","毛泽东"],place:"北京",state:"中华人民共和国",sources:["《人民日报》1976年7月7日、叶剑英《在朱德同志追悼大会上的悼词》（1976年7月11日）"],"tags":["朱德","逝世","悼词"]},related:["cn--1976--p01", "cn--1976--p04"]},
  {id:"cn--1976--p04",track:"cn",year:1976,yearApprox:false,dim:"politics",weight:4,title:"毛泽东逝世",summary:"9月9日0时10分毛泽东在北京逝世，终年83岁，18日追悼大会。",detail:{background:"1976年以来毛泽东病情反复，医疗组自5月起加强监护，他仍审阅文件并会见外宾；9月上旬再度病危。",process:"1976年9月9日0时10分，中共中央主席、中央军委主席毛泽东因疾病抢救无效在北京逝世，终年83岁；同日中共中央、全国人大常委会、国务院、中央军委联合发布公报，9月18日首都各界30万人在天安门广场举行追悼大会，华国锋致悼词；联合国大会为此休会致哀并下半旗，据新华社当时报道，外国政府、议会与政党送来的吊唁电函达上百起。",impact:"毛泽东逝世后不到一个月，中央政治局于1976年10月6日采取果断措施粉碎“四人帮”，“文化大革命”由此结束；1981年6月《关于建国以来党的若干历史问题的决议》对毛泽东作出“功绩是第一位的，错误是第二位的”评价，并把他的思想与晚年的错误区分开来。",figures:["毛泽东","华国锋","叶剑英","汪东兴"],place:"北京",state:"中华人民共和国",sources:["中共中央、全国人大常委会、国务院、中央军委《关于毛泽东主席逝世的公报》（1976年9月9日）、华国锋《悼毛泽东同志》（《人民日报》1976年9月19日）"],"tags":["毛泽东","逝世","历史决议"]},related:["cn--1976--p05", "cn--1981--p01", "world--1976--p02", "world--1976--p01"]},
  {id:"cn--1976--p05",track:"cn",year:1976,yearApprox:false,dim:"politics",weight:5,title:"粉碎江青反革命集团",summary:"10月6日中央政治局对王洪文、张春桥、江青、姚文元隔离审查。",detail:{background:"1976年8月至10月上旬，“四人帮”加紧夺取党和国家领导权的活动，通过其舆论系统宣扬“按既定方针办”，并调动上海等地的武装力量；叶剑英、华国锋、李先念、汪东兴等经多次接触形成采取果断措施的共识。",process:"1976年10月6日晚，华国锋、叶剑英等在中南海怀仁堂对王洪文、张春桥、江青、姚文元实行隔离审查，同时对北京、上海的联络点与新闻单位采取管制措施；10月14日中央向全党全国公开宣布“四人帮”问题，10月18日发出《关于王洪文、张春桥、江青、姚文元反党集团问题的通知》；1977年7月十届三中全会决定永远开除四人的党籍、撤销其党内外一切职务；1980年11月20日至1981年1月25日最高人民法院特别法庭公开审判，对江青、张春桥判处死刑缓期二年执行。",impact:"这一措施结束了持续十年的内乱局面，1977年8月中共十一大宣布“文化大革命”结束，1981年历史决议以1976年10月粉碎江青反革命集团为“文化大革命”结束的界标；此后教育、科技与经济领域的拨乱反正与1978年12月十一届三中全会的转折具备政治前提。",figures:["华国锋","叶剑英","李先念","汪东兴","江青","张春桥","王洪文","姚文元"],place:"北京中南海怀仁堂；上海",state:"中华人民共和国",sources:["中共中央《关于王洪文、张春桥、江青、姚文元反党集团问题的通知》（1976年10月18日）、最高人民法院特别法庭《判决书》（1981年1月25日）"],"tags":["四人帮","隔离审查","特别法庭"]},related:["cn--1976--p04", "cn--1976--p02", "cn--1977--p01", "world--1976--p02"]},
  {id:"cn--1977--p01",track:"cn",year:1977,yearApprox:false,dim:"politics",weight:4,title:"十届三中全会恢复邓小平职务",summary:"1977年7月21日，全会通过关于恢复邓小平同志职务的决议。",detail:{background:"1976年4月邓小平被撤销党内外一切职务、只保留党籍；1977年2月至4月，叶剑英等多次提出请邓小平重新出来工作，党内与舆论的呼声集中到这一议题上。",process:"1977年7月16日至21日，中国共产党第十届中央委员会第三次全体会议在北京举行，通过《关于恢复邓小平同志职务的决议》，决定恢复邓小平的中共中央副主席、中共中央政治局常委、国务院副总理、中共中央军事委员会副主席等职务；全会同时追认华国锋为中央委员会主席、中央军委主席，并审理王洪文、康生、谢富治问题，决定开除三人党籍。",impact:"据《中国共产党历史》第二卷的叙述，邓小平复出主管科学与教育工作，1977年8月主持科学和教育工作座谈会并推动当年恢复高考，为1978年12月十一届三中全会后的政策调整提供了领导层条件。",figures:["邓小平","叶剑英","华国锋"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十届中央委员会第三次全体会议关于恢复邓小平同志职务的决议》（1977年7月21日通过）、《人民日报》1977年7月23日"],"tags":["十届三中全会","邓小平复出","领导层调整"]},related:["cn--1976--p05", "cn--1977--i01", "cn--1978--p02"]},
  {id:"cn--1977--p02",track:"cn",year:1977,yearApprox:false,dim:"politics",weight:3,title:"“两个凡是”方针的提出",summary:"1977年2月7日“两报一刊”社论提出“两个凡是”的表述。",detail:{background:"1976年10月“文化大革命”结束后，党内与社会各界要求纠正“左”的错误、复查重大冤案；当时中央主要领导人仍需在毛泽东晚年决策的框架内处理这些问题。",process:"1977年2月7日，《人民日报》《解放军报》《红旗》杂志发表社论《学好文件抓住纲》，提出“凡是毛主席作出的决策，我们都坚决维护，凡是毛主席的指示，我们都始终不渝地遵循”，这一提法此后被概括为“两个凡是”；1977年3月中央工作会议上，叶剑英等就“两个凡是”问题发言表示异议。",impact:"据《中国共产党历史》第二卷记载，这一方针在实际上妨碍了平反冤假错案与清理“文化大革命”错误的进程；1978年5月《实践是检验真理的唯一标准》发表后，围绕这一提法形成全国性讨论，1978年12月中共十一届三中全会批评了“两个凡是”。",figures:["华国锋","叶剑英"],place:"北京",state:"中华人民共和国",sources:["《人民日报》《解放军报》《红旗》1977年2月7日社论《学好文件抓住纲》","《中国共产党历史（1949—1978）》第二卷（中共党史出版社2011年）"],"tags":["两个凡是","真理标准","1977年"]},related:["cn--1977--p01", "cn--1978--p01"]},
  {id:"cn--1977--p03",track:"cn",year:1977,yearApprox:false,dim:"politics",weight:3,title:"中共十一大宣告“文革”结束",summary:"1977年8月12日至18日十一大在北京举行，修改党章并选举中央委员会。",detail:{background:"第十一次全国代表大会原应在1976年召开，“文化大革命”结束后的过渡期使大会推迟到1977年8月；筹备期间关于如何总结十年经验存在不同意见。",process:"1977年8月12日至18日，中国共产党第十一次全国代表大会在北京举行，华国锋作《政治报告》，叶剑英作《关于修改党的章程的报告》，邓小平致开幕词；大会通过修改后的《中国共产党章程》和新选举的中央委员会，重申「在本世纪内把我国建设成为伟大的社会主义强国」。",impact:"大会宣告“文化大革命”结束，但仍延续“无产阶级专政下继续革命”的提法，未能从指导思想上系统清理“左”的错误；据《中国共产党历史》第二卷，这一任务由1978年12月十一届三中全会与1981年《关于建国以来党的若干历史问题的决议》完成。",figures:["华国锋","叶剑英","邓小平"],place:"北京",state:"中华人民共和国",sources:["《中国共产党第十一次全国代表大会文件汇编》（人民出版社1977年）、《人民日报》1977年8月19日"],"tags":["中共十一大","党章修改","过渡期"]},related:["cn--1977--p02", "cn--1981--p01"]},
  {id:"cn--1977--i01",track:"cn",year:1977,yearApprox:false,dim:"institution",weight:4,title:"恢复全国高等学校招生文化考试",summary:"1977年10月12日国务院批转招生意见，12月10日起各省同步考试。",detail:{background:"1966年起高等学校停止正规招生，1970年至1976年按“自愿报名、群众推荐、领导批准、学校复审”办法招收工农兵学员；1977年重建人才选拔制度成为教育与科技界的共同要求。",process:"1977年8月6日，武汉大学教师查全性在邓小平主持召开的科学和教育工作座谈会上建议当年恢复考试招生；8月13日至9月22日教育部召开全国高等学校招生工作会议作出决定，10月12日国务院批转《关于1977年高等学校招生工作的意见》，规定德智体全面考核、统一考试、择优录取；12月10日起各省、市、自治区分别举行考试。",impact:"据教育部资料与《中国教育年鉴》，1977年全国报考青年约570万人，经两次追加招生指标后高等院校录取新生数万人，中等专业学校另录取一批学生；1978年夏季高校又增招新生，高校招生自此回到统一考试轨道。",figures:["邓小平","查全性"],place:"北京（决策），各省、市、自治区（开考）",state:"中华人民共和国",sources:["国务院批转教育部《关于1977年高等学校招生工作的意见》（1977年10月12日）、《中国教育年鉴（1949—1981）》（中国地图出版社1984年）"],"tags":["恢复高考","招生制度","教育"]},related:["cn--1966--i01", "cn--1978--s01"]},
  {id:"cn--1977--i02",track:"cn",year:1977,yearApprox:false,dim:"institution",weight:2,title:"国务院批准恢复研究生招生",summary:"1977年11月国务院批准恢复高等学校与科研机构研究生招生。",detail:{background:"1966年后高等学校与科研机构停止招收研究生，科研与教学队伍出现断层；1977年国家科委、中国科学院与教育部共同酝酿恢复培养高层次人才的办法。",process:"1977年11月，国务院批准教育部、中国科学院关于高等学校和科研机构招收研究生的报告，恢复研究生招生制度，明确招生由培养单位单独组织考试；1978年春季，全国高等学校与科研机构同时招收1977届、1978届研究生，报考人数达数万人。",impact:"据教育部《中国教育年鉴》记载，研究生招生的恢复与1977年恢复高考共同重建了分层人才培养体系；1980年2月《中华人民共和国学位条例》通过后，研究生培养与学位授予制度正式衔接。",figures:["方毅"],place:"北京",state:"中华人民共和国",sources:["国务院批转教育部、中国科学院关于招收研究生的报告（1977年11月）、《中国教育年鉴（1949—1981）》（中国地图出版社1984年）"],"tags":["研究生教育","人才培养","恢复招生"]},related:["cn--1977--i01", "cn--1980--i04"]},
  {id:"cn--1977--c01",track:"cn",year:1977,yearApprox:false,dim:"culture",weight:2,title:"短篇小说《班主任》发表",summary:"1977年11月刘心武《班主任》刊于《人民文学》，被视为新时期文学开端。",detail:{background:"1966年至1976年文学创作题材受限，作品数量与题材范围大幅下降；“文化大革命”结束后，作家开始以小说触及十年造成的精神创伤。",process:"1977年11月，刘心武的短篇小说《班主任》在《人民文学》复刊号上发表，以中学班主任张俊石面对受“文革”影响的学生为线索，提出需要“救救被‘四人帮’坑害了的孩子”；1978年8月11日，卢新华的短篇小说《伤痕》在《文汇报》发表，这类作品随后被概括为“伤痕文学”。",impact:"据洪子诚《中国当代文学史》的通行叙述，《班主任》被视为新时期文学的开端之一，1978年至1980年间同类题材作品大量出现，并与关于真理标准的讨论相互呼应，推动文学界的反思写作。",figures:["刘心武","卢新华"],place:"北京（《人民文学》编辑部）",state:"中华人民共和国",sources:["《人民文学》1977年第11期、《文汇报》1978年8月11日","洪子诚《中国当代文学史》（北京大学出版社1999年）"],"tags":["伤痕文学","《班主任》","新时期文学"]},related:["cn--1978--c01"]},
];
